function testPlaceSourceSameTargetDpBuff(){
  const issues=[];
  const tia=base('EX6-040');
  const tiaMain=tia.mechanics.find(m=>m.trigger==='MAIN');
  const tiaDp=tiaMain?.actions?.find(a=>a.type==='DP_MOD');
  if(tiaDp?.target?.sameAsPreviousTarget!==true) issues.push('EX6-040 That Digimon gets +2000 DP must use sameAsPreviousTarget:true after PLACE_SOURCE');

  const ludomon=base('EX6-038');
  const zuba=base('EX6-007');
  const zubaE=base('EX6-008');
  for(const card of [ludomon,zuba,zubaE]){
    const ps=card.mechanics.find(m=>m.trigger==='MAIN')?.actions?.find(a=>a.type==='PLACE_SOURCE');
    if(String(ps?.buff?.stat||'').toUpperCase()!=='DP' || !Number(ps?.buff?.value||0)) issues.push(`${card.id} PLACE_SOURCE should preserve its embedded DP buff for the host`);
  }

  const g=mkGame(['EX6-040','EX6-038','BT1-010','BT1-011'],['BT2-010']);
  g.zones.p1.hand=[];
  const tiaHand=addHand(g,'p1','EX6-040');
  g.zones.p1.battleArea=[];
  const first=addBattle(g,'p1','BT1-010',{tag:'placeSourceFirst'});
  const second=addBattle(g,'p1','BT1-011',{tag:'placeSourceSecond'});
  if(tiaMain){ enqueue(g,'p1',tiaHand,tiaMain.actions,'EX6-040 MAIN'); autoResolve(g); }
  if(!first.stack || !first.stack.some(c=>c.id==='EX6-040')) issues.push('EX6-040 was not placed under the first chosen host');
  if(!hasTurnEffect(first,'DP_MOD',e=>Number(e.value)===2000)) issues.push('EX6-040 did not apply +2000 DP to the PLACE_SOURCE host');
  if(hasTurnEffect(second,'DP_MOD',e=>Number(e.value)===2000)) issues.push('EX6-040 incorrectly applied +2000 DP to a different Digimon');
  if(g.pendingTarget || g.pendingChoice || g.pendingTrashRevive || g.effectQueue.length) issues.push('EX6-040 PLACE_SOURCE same-target DP flow left pending work');

  const g2=mkGame(['EX6-038','BT1-010','BT1-011'],['BT2-010']);
  g2.zones.p1.hand=[];
  const ludoHand=addHand(g2,'p1','EX6-038');
  g2.zones.p1.battleArea=[];
  const host=addBattle(g2,'p1','BT1-010',{tag:'ludoHost'});
  const other=addBattle(g2,'p1','BT1-011',{tag:'ludoOther'});
  const ludoMain=ludomon.mechanics.find(m=>m.trigger==='MAIN');
  if(ludoMain){ enqueue(g2,'p1',ludoHand,ludoMain.actions,'EX6-038 MAIN'); autoResolve(g2); }
  if(!host.stack || !host.stack.some(c=>c.id==='EX6-038')) issues.push('EX6-038 was not placed under the first chosen host');
  if(!hasTurnEffect(host,'DP_MOD',e=>Number(e.value)===2000)) issues.push('EX6-038 PLACE_SOURCE.buff did not apply +2000 DP to the host');
  if(hasTurnEffect(other,'DP_MOD',e=>Number(e.value)===2000)) issues.push('EX6-038 incorrectly applied PLACE_SOURCE.buff to a different Digimon');

  issues.push(...checkInvariants(g,'placeSourceSameTargetTia'), ...checkInvariants(g2,'placeSourceBuffLudomon'));
  return {name:'PLACE_SOURCE same-target DP buff applies to the host', issues};
}


function testPlayedByThisEffectAttackRedirect(){
  const issues=[];
  const jeri=base('BT19-078');
  const jeriInherited=jeri.mechanics.find(m=>m.trigger==='OPPONENT_ATTACKED');
  const jeriRedirect=jeriInherited?.actions?.find(a=>a.type==='CHANGE_ATTACK_TARGET');
  if(jeriRedirect?.condition?.type!=='PLAYED_BY_THIS_EFFECT') issues.push('BT19-078 redirect must require PLAYED_BY_THIS_EFFECT');
  if(jeriRedirect?.target?.playedByThisEffect!==true) issues.push('BT19-078 redirect must target the Digimon played by this effect');

  const whiff=mkGame(['BT19-078','BT1-010','BT1-011'],['BT2-010']);
  whiff.zones.p1.battleArea=[]; whiff.zones.p2.battleArea=[];
  const oldJeri=addBattle(whiff,'p1','BT19-078',{tag:'oldJeri'});
  const attacker=addBattle(whiff,'p2','BT2-010',{tag:'attacker'});
  whiff.counterTiming={isActive:false, defenderId:'p1', step:'IDLE', pendingAttack:{attackerId:'p2', attackerInstanceId:attacker.instanceId, targetType:'player', targetPlayerId:'p1', targetInstanceId:null}};
  if(jeriInherited){ enqueue(whiff,'p1',oldJeri,jeriInherited.actions,'BT19-078 inherited whiff'); autoResolve(whiff); }
  if(whiff.counterTiming.pendingAttack.targetType!=='player') issues.push('BT19-078 whiffed play still redirected attack to an old Jeri');

  const g=mkGame(['BT19-078','BT1-010','BT1-011'],['BT2-010']);
  g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[];
  const host=addBattle(g,'p1','EX2-054',{tag:'motherHost'});
  host.stack=[clone('BT19-078','sourceJeri')];
  const old=addBattle(g,'p1','BT19-078',{tag:'oldJeri2'});
  const atk=addBattle(g,'p2','BT2-010',{tag:'attacker2'});
  g.counterTiming={isActive:false, defenderId:'p1', step:'IDLE', pendingAttack:{attackerId:'p2', attackerInstanceId:atk.instanceId, targetType:'player', targetPlayerId:'p1', targetInstanceId:null}};
  if(jeriInherited){ enqueue(g,'p1',host,jeriInherited.actions,'BT19-078 inherited success'); autoResolve(g); }
  const played=g.zones.p1.battleArea.find(c=>c.id==='BT19-078' && c.instanceId!==old.instanceId);
  if(!played) issues.push('BT19-078 source Jeri was not played from source');
  if(g.counterTiming.pendingAttack.targetInstanceId!==played?.instanceId) issues.push('BT19-078 did not redirect to the exact Jeri played by this effect');
  if(g.counterTiming.pendingAttack.targetInstanceId===old.instanceId) issues.push('BT19-078 redirected to an older Jeri already in play');

  const waru=base('BT15-078');
  const waruAtk=waru.mechanics.find(m=>m.trigger==='WHEN_ATTACKING');
  const waruPlay=waruAtk?.actions?.find(a=>a.type==='PLAY_FROM_TRASH');
  const waruRedirect=waruAtk?.actions?.find(a=>a.type==='CHANGE_ATTACK_TARGET');
  if(waruPlay?.playSuspended!==true) issues.push('BT15-078 opponent Digimon played by attack effect must enter suspended');
  if(waruPlay?.suppressOnPlay!==true) issues.push('BT15-078 opponent Digimon played by attack effect must suppress On Play');
  if(waruRedirect?.condition?.type!=='PLAYED_BY_THIS_EFFECT' || waruRedirect?.target?.playedByThisEffect!==true) issues.push('BT15-078 attack redirect must bind to the Digimon played by this effect');

  const w=mkGame(['BT15-078','BT1-010'],['BT2-010','BT2-013']);
  w.zones.p1.battleArea=[]; w.zones.p2.battleArea=[]; w.zones.p2.trash=[];
  const waruBody=addBattle(w,'p1','BT15-078',{tag:'waru'});
  const p2Trash=clone('BT2-010','p2trash'); w.zones.p2.trash.push(p2Trash);
  w.counterTiming={isActive:false, defenderId:'p2', step:'IDLE', pendingAttack:{attackerId:'p1', attackerInstanceId:waruBody.instanceId, targetType:'player', targetPlayerId:'p2', targetInstanceId:null}};
  if(waruAtk){ enqueue(w,'p1',waruBody,waruAtk.actions,'BT15-078 WHEN_ATTACKING'); autoResolve(w); }
  const playedOpp=w.zones.p2.battleArea.find(c=>c.id==='BT2-010');
  if(!playedOpp) issues.push('BT15-078 did not play opponent Digimon from trash');
  if(playedOpp && !playedOpp.isSuspended) issues.push('BT15-078 played opponent Digimon was not suspended');
  if(w.counterTiming.pendingAttack.targetInstanceId!==playedOpp?.instanceId) issues.push('BT15-078 did not switch attack target to the played opponent Digimon');

  issues.push(...checkInvariants(whiff,'playedByThisEffectWhiff'), ...checkInvariants(g,'playedByThisEffectJeri'), ...checkInvariants(w,'playedByThisEffectWaru'));
  return {name:'Played-by-this-effect attack redirects bind to successful play result', issues};
}



function testSuspendAnyIfOwnSuspendedFollowup(){
  const issues=[];
  const anemoi=base('ST18-15');
  const main=anemoi.mechanics.find(m=>m.trigger==='MAIN');
  const suspend=main?.actions?.[0];
  const ret=main?.actions?.[1];
  const unsuspend=main?.actions?.[2];
  if(suspend?.type!=='SUSPEND' || suspend?.target?.owner!=='any') issues.push('ST18-15 must encode printed "Suspend 1 Digimon" as SUSPEND owner:any');
  if(ret?.condition?.type!=='SUSPENDED_OWN_BY_THIS_EFFECT') issues.push('ST18-15 return must require same-effect own suspension success');
  if(unsuspend?.target?.owner!=='any') issues.push('ST18-15 final unsuspend must be able to choose any Digimon');

  const zepha=base('EX7-036');
  for(const trig of ['WHEN_DIGIVOLVING','WHEN_ATTACKING']){
    const mech=zepha.mechanics.find(m=>m.trigger===trig);
    if(!mech) issues.push(`EX7-036 missing ${trig} suspend/conditional return mechanic`);
    const zSuspend=mech?.actions?.[0];
    const zReturn=mech?.actions?.[1];
    if(zSuspend?.type!=='SUSPEND' || zSuspend?.target?.owner!=='any') issues.push(`EX7-036 ${trig} must suspend any Digimon`);
    if(zReturn?.condition?.type!=='SUSPENDED_OWN_BY_THIS_EFFECT') issues.push(`EX7-036 ${trig} return must require same-effect own suspension success`);
  }

  const wind=base('EX7-069');
  for(const trig of ['MAIN','SECURITY']){
    const mech=wind.mechanics.find(m=>m.trigger===trig);
    if(!mech) issues.push(`EX7-069 missing ${trig} suspend/conditional unsuspend mechanic`);
    const wSuspend=mech?.actions?.[0];
    const wUnsuspend=mech?.actions?.[1];
    if(wSuspend?.type!=='SUSPEND' || wSuspend?.target?.owner!=='any' || Number(wSuspend?.target?.maxLevel)!==6) issues.push(`EX7-069 ${trig} must suspend any level 6 or lower Digimon`);
    if(wUnsuspend?.type!=='UNSUSPEND' || wUnsuspend?.condition?.type!=='SUSPENDED_OWN_BY_THIS_EFFECT') issues.push(`EX7-069 ${trig} unsuspend must require same-effect own suspension success`);
  }


  const much=base('BT24-044');
  const muchOnPlay=much.mechanics.find(m=>m.trigger==='ON_PLAY');
  const mSuspend=muchOnPlay?.actions?.[0];
  const mReveal=muchOnPlay?.actions?.[1];
  if(mSuspend?.type!=='SUSPEND' || mSuspend?.target?.owner!=='any' || Number(mSuspend?.target?.maxLevel)!==6) issues.push('BT24-044 On Play must suspend any level 6 or lower Digimon');
  if(mReveal?.type!=='REVEAL_AND_SELECT' || mReveal?.condition?.type!=='SUSPENDED_OWN_BY_THIS_EFFECT') issues.push('BT24-044 reveal must require same-effect own suspension success');

  const whiff=mkGame(['ST18-15','BT1-010'],['BT2-010','BT2-011']);
  whiff.zones.p1.battleArea=[]; whiff.zones.p2.battleArea=[];
  const opp=addBattle(whiff,'p2','BT2-010',{tag:'oppOnly'});
  enqueue(whiff,'p1',anemoi,main.actions,'ST18-15 opponent-only suspend');
  autoResolve(whiff);
  if(!whiff.zones.p2.battleArea.find(c=>c.instanceId===opp.instanceId)) issues.push('ST18-15 incorrectly returned opponent Digimon after only opponent was suspended by this effect');

  const g=mkGame(['ST18-15','BT1-010'],['BT2-010','BT2-011']);
  g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[];
  const own=addBattle(g,'p1','BT1-010',{tag:'ownTarget'});
  const oppSuspended=addBattle(g,'p2','BT2-010',{tag:'oppSuspended'}); oppSuspended.isSuspended=true;
  enqueue(g,'p1',anemoi,main.actions,'ST18-15 own suspend gates return');
  autoResolve(g);
  if(g.zones.p2.battleArea.find(c=>c.instanceId===oppSuspended.instanceId)) issues.push('ST18-15 did not return opponent suspended Digimon after this effect suspended your Digimon');
  if(own.isSuspended) issues.push('ST18-15 final unsuspend did not allow/resolve the own suspended Digimon after owner:any target support');

  const windMain=wind.mechanics.find(m=>m.trigger==='MAIN');
  const windWhiff=mkGame(['EX7-069','BT1-010'],['BT2-010','BT2-011']);
  windWhiff.zones.p1.battleArea=[]; windWhiff.zones.p2.battleArea=[];
  const windOpp=addBattle(windWhiff,'p2','BT2-010',{tag:'windOpp', level:4});
  enqueue(windWhiff,'p1',wind,windMain.actions,'EX7-069 opponent suspend should not gate unsuspend');
  autoResolve(windWhiff);
  if(!windOpp.isSuspended) issues.push('EX7-069 did not suspend opponent level 6 or lower Digimon');
  if(windWhiff.zones.p1.battleArea.some(c=>!c.isSuspended)) issues.push('EX7-069 should not create an own unsuspend follow-up after only opponent was suspended');

  const windSuccess=mkGame(['EX7-069','BT1-010'],['BT2-010','BT2-011']);
  windSuccess.zones.p1.battleArea=[]; windSuccess.zones.p2.battleArea=[];
  const windOwn=addBattle(windSuccess,'p1','BT1-010',{tag:'windOwn', level:3});
  enqueue(windSuccess,'p1',wind,windMain.actions,'EX7-069 own suspend gates unsuspend');
  autoResolve(windSuccess);
  if(windOwn.isSuspended) issues.push('EX7-069 did not unsuspend one of your Digimon after this effect suspended your Digimon');

  const muchWhiff=mkGame(['BT24-044','BT1-010','BT20-085'],['BT2-010','BT2-011']);
  muchWhiff.zones.p1.battleArea=[]; muchWhiff.zones.p2.battleArea=[]; muchWhiff.zones.p1.hand=[]; muchWhiff.zones.p1.revealed=[]; muchWhiff.zones.p1.deck=[clone('BT20-085','shotoTop'), clone('BT1-010','avianTop'), clone('BT2-010','otherTop')];
  const muchOpp=addBattle(muchWhiff,'p2','BT2-010',{tag:'muchOpp', level:4});
  enqueue(muchWhiff,'p1',much,muchOnPlay.actions,'BT24-044 opponent suspend should not reveal');
  autoResolve(muchWhiff);
  if(!muchOpp.isSuspended) issues.push('BT24-044 did not suspend opponent level 6 or lower Digimon');
  if(muchWhiff.zones.p1.revealed.length || muchWhiff.zones.p1.hand.some(c=>c.id==='BT20-085')) issues.push('BT24-044 incorrectly revealed/added after only opponent Digimon was suspended');

  const muchSuccess=mkGame(['BT24-044','BT1-010','BT20-085'],['BT2-010','BT2-011']);
  muchSuccess.zones.p1.battleArea=[]; muchSuccess.zones.p2.battleArea=[]; muchSuccess.zones.p1.hand=[]; muchSuccess.zones.p1.revealed=[]; muchSuccess.zones.p1.deck=[clone('BT2-010','otherBottom'), clone('BT1-010','avianMid'), clone('BT20-085','shotoTop')];
  addBattle(muchSuccess,'p1','BT1-010',{tag:'muchOwn', level:3});
  enqueue(muchSuccess,'p1',much,muchOnPlay.actions,'BT24-044 own suspend gates reveal');
  autoResolve(muchSuccess);
  if(!muchSuccess.zones.p1.hand.some(c=>c.id==='BT20-085')) issues.push('BT24-044 did not reveal/add after this effect suspended your Digimon');

  issues.push(...checkInvariants(whiff,'suspendAnyWhiff'), ...checkInvariants(g,'suspendAnySuccess'), ...checkInvariants(windWhiff,'windSlicerWhiff'), ...checkInvariants(windSuccess,'windSlicerSuccess'));
  return {name:'Generic Suspend 1 Digimon gates If-this-effect-suspended-your-Digimon follow-up', issues};
}


function testDeletedOwnByThisEffectFollowup(){
  const issues=[];
  const wendi=base('ST17-04');
  const onPlay=wendi.mechanics.find(m=>m.trigger==='ON_PLAY');
  const follow=onPlay?.actions?.[1];
  if(follow?.condition?.type!=='DELETED_OWN_BY_THIS_EFFECT') issues.push('ST17-04 follow-up must require DELETED_OWN_BY_THIS_EFFECT');

  const whiff=mkGame(['ST17-04','BT17-043'],['BT2-010','BT2-011']);
  whiff.zones.p1.battleArea=[]; whiff.zones.p2.battleArea=[]; whiff.zones.p1.trash=[];
  const oppLv3=addBattle(whiff,'p2','BT2-010',{tag:'oppLv3', level:3});
  whiff.zones.p1.trash.push(clone('BT17-043','trashTerrierWhiff'));
  enqueue(whiff,'p1',wendi,onPlay.actions,'ST17-04 opponent delete should not gate own follow-up');
  autoResolve(whiff);
  if(whiff.zones.p2.battleArea.find(c=>c.instanceId===oppLv3.instanceId)) issues.push('ST17-04 did not delete the opponent level 3 target in whiff branch');
  if(whiff.zones.p1.battleArea.some(c=>c.id==='BT17-043')) issues.push('ST17-04 incorrectly played Terriermon after deleting only opponent Digimon');

  const g=mkGame(['ST17-04','BT17-043'],['BT2-010','BT2-011']);
  g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.zones.p1.trash=[];
  const ownLv3=addBattle(g,'p1','BT17-043',{tag:'ownLv3', level:3});
  g.zones.p1.trash.push(clone('BT17-043','trashTerrierSuccess'));
  enqueue(g,'p1',wendi,onPlay.actions,'ST17-04 own delete gates follow-up');
  autoResolve(g);
  if(g.zones.p1.battleArea.find(c=>c.instanceId===ownLv3.instanceId)) issues.push('ST17-04 did not delete own level 3 target in success branch');
  if(!g.zones.p1.battleArea.some(c=>c.id==='BT17-043')) issues.push('ST17-04 did not play Terriermon after this effect deleted one of your Digimon');

  issues.push(...checkInvariants(whiff,'deletedOwnWhiff'), ...checkInvariants(g,'deletedOwnSuccess'));
  return {name:'If-this-effect-deleted-one-of-your-Digimon gates follow-up by same-effect own deletion', issues};
}


function testNotDeletedByThisEffectFollowup(){
  const issues=[];
  const fire=base('EX2-067');
  const fireMain=fire.mechanics.find(m=>m.trigger==='MAIN');
  const fireDraw=fireMain?.actions?.find(a=>a.type==='DRAW');
  if(fireDraw?.condition?.type!=='NOT_DELETED_BY_THIS_EFFECT') issues.push('EX2-067 Draw 2 must require NOT_DELETED_BY_THIS_EFFECT');

  const fireSuccess=mkGame(['EX2-067','BT1-010'],['BT2-010','BT2-011']);
  fireSuccess.zones.p1.battleArea=[]; fireSuccess.zones.p2.battleArea=[]; fireSuccess.zones.p1.hand=[];
  addBattle(fireSuccess,'p2','BT2-010',{tag:'smallDelete', dp:3000});
  const handBeforeSuccess=fireSuccess.zones.p1.hand.length;
  enqueue(fireSuccess,'p1',fire,fireMain.actions,'EX2-067 delete succeeds no draw');
  autoResolve(fireSuccess);
  if(fireSuccess.zones.p1.hand.length!==handBeforeSuccess) issues.push('EX2-067 incorrectly drew after this effect successfully deleted a Digimon');

  const fireWhiff=mkGame(['EX2-067','BT1-010'],['BT2-010','BT2-011']);
  fireWhiff.zones.p1.battleArea=[]; fireWhiff.zones.p2.battleArea=[]; fireWhiff.zones.p1.hand=[];
  addBattle(fireWhiff,'p2','BT2-011',{tag:'tooLarge', dp:5000});
  enqueue(fireWhiff,'p1',fire,fireMain.actions,'EX2-067 delete fails draw');
  autoResolve(fireWhiff);
  if(fireWhiff.zones.p1.hand.length!==2) issues.push(`EX2-067 did not draw 2 after no Digimon was deleted by this effect; hand=${fireWhiff.zones.p1.hand.length}`);

  const malo=base('BT16-081');
  const maloMain=malo.mechanics.find(m=>m.trigger==='WHEN_DIGIVOLVING');
  const tamerDelete=maloMain?.actions?.find(a=>a.type==='DELETE_DIGIMON' && a.target?.cardType==='tamer');
  if(tamerDelete?.condition?.type!=='NOT_DELETED_OPPONENT_BY_THIS_EFFECT') issues.push('BT16-081 Tamer deletion must require NOT_DELETED_OPPONENT_BY_THIS_EFFECT');

  const oppDeleted=mkGame(['BT16-081','BT1-010'],['BT2-010','BT2-011']);
  oppDeleted.zones.p1.battleArea=[]; oppDeleted.zones.p2.battleArea=[];
  addBattle(oppDeleted,'p1','BT1-010',{tag:'ownCost'});
  const oppD=addBattle(oppDeleted,'p2','BT2-010',{tag:'oppUnsuspended'});
  const oppTamer=addBattle(oppDeleted,'p2','BT9-094',{tag:'oppTamer', type:'tamer'});
  enqueue(oppDeleted,'p1',malo,maloMain.actions,'BT16-081 opponent delete succeeds no tamer delete');
  autoResolve(oppDeleted);
  if(oppDeleted.zones.p2.battleArea.find(c=>c.instanceId===oppD.instanceId)) issues.push('BT16-081 did not delete opponent Digimon in success branch');
  if(!oppDeleted.zones.p2.battleArea.find(c=>c.instanceId===oppTamer.instanceId)) issues.push('BT16-081 incorrectly deleted Tamer even though this effect deleted an opponent Digimon');

  const oppWhiff=mkGame(['BT16-081','BT1-010'],['BT2-010','BT2-011']);
  oppWhiff.zones.p1.battleArea=[]; oppWhiff.zones.p2.battleArea=[];
  addBattle(oppWhiff,'p1','BT1-010',{tag:'ownCostOnly'});
  const whiffTamer=addBattle(oppWhiff,'p2','BT9-094',{tag:'oppTamerWhiff', type:'tamer'});
  enqueue(oppWhiff,'p1',malo,maloMain.actions,'BT16-081 no opponent Digimon gates tamer delete');
  autoResolve(oppWhiff);
  if(oppWhiff.zones.p2.battleArea.find(c=>c.instanceId===whiffTamer.instanceId)) issues.push('BT16-081 did not delete Tamer after no opponent Digimon was deleted by this effect');

  issues.push(...checkInvariants(fireSuccess,'notDeletedFireSuccess'), ...checkInvariants(fireWhiff,'notDeletedFireWhiff'), ...checkInvariants(oppDeleted,'notDeletedOpponentSuccess'), ...checkInvariants(oppWhiff,'notDeletedOpponentWhiff'));
  return {name:'If-this-effect-did-not-delete gates follow-up by same-effect deletion failure', issues};
}


