function testOfficialRpsStartingPlayerRule(){
  const issues=[];
  if(normalizeRpsChoiceTest('ROCK')!=='rock') issues.push('normalizeRpsChoice should accept case-insensitive rock');
  if(getRpsWinnerTest('rock','scissors')!=='p1') issues.push('rock should beat scissors for P1');
  if(getRpsWinnerTest('paper','scissors')!=='p2') issues.push('scissors should beat paper for P2');
  if(getRpsWinnerTest('paper','paper')!=='tie') issues.push('matching RPS choices should tie and require a replay');
  const g = new GameState({name:'P1',avatar:null},{name:'P2',avatar:null},makeDeck(['BT1-010','BT1-011']),makeDeck(['BT2-010','BT2-011']),{startingPlayer:'p2'});
  if(g.turnPlayer!=='p2' || g.firstPlayer!=='p2') issues.push(`RPS winner P2 should be stored as first/turn player before mulligan, got first=${g.firstPlayer} turn=${g.turnPlayer}`);
  if(g.phase!=='MULLIGAN') issues.push(`game should stay in MULLIGAN after opening hands, got ${g.phase}`);
  if(g.zones.p1.hand.length!==5 || g.zones.p2.hand.length!==5) issues.push('opening hands should still be drawn only after RPS-selected GameState creation');
  if(g.zones.p1.security.length!==0 || g.zones.p2.security.length!==0) issues.push('security should not be placed before mulligan decisions');
  const earlySecondDecision = g.decideMulligan('p1', false);
  if(earlySecondDecision !== false) issues.push('second player should not be able to decide mulligan before the first player');
  if(g.mulliganDecisions.p1 !== null) issues.push('blocked second-player mulligan should not record a decision');
  g.decideMulligan('p2', false);
  g.decideMulligan('p1', false);
  if(g.turnPlayer!=='p2') issues.push(`RPS winner should remain the opening turn player, got ${g.turnPlayer}`);
  if(g.zones.p2.hand.length!==5) issues.push(`first player P2 should skip first draw and keep 5 cards, got ${g.zones.p2.hand.length}`);
  if(g.phase!=='HATCH') issues.push(`after mulligan, opening turn should reach breeding/hatch phase, got ${g.phase}`);
  if(g.zones.p1.security.length!==5 || g.zones.p2.security.length!==5) issues.push('security should be placed after both mulligan decisions');
  issues.push(...checkInvariants(g,'officialRpsStartingPlayer'));
  return {name:'Official RPS winner automatically goes first before opening setup', summary:g.getDebugSummary(), issues};
}

