function smokeMatch(){
  const p1=['EX2-046','EX2-047','EX2-049','EX2-053','EX2-054','EX2-007','ST7-12','BT16-097','BT24-090','BT24-034','BT25-033','EX8-029'];
  const p2=['BT1-010','BT1-019','BT1-020','BT5-079','EX4-010','BT9-094','BT16-047','BT25-025','BT25-053','EX8-035','EX9-055','EX9-057'];
  const g=mkGame(p1,p2);
  const turnReports=[]; const issues=[];
  for(let i=0;i<10 && !g.gameOver;i++){
    const p=g.turnPlayer;
    try { playOneTurn(g,p); } catch(e){ issues.push(`turn ${i+1} exception: ${e.stack||e.message}`); break; }
    const inv=checkInvariants(g,`smoke turn ${i+1}`); issues.push(...inv);
    turnReports.push({turn:i+1, next:g.turnPlayer, phase:g.phase, memory:g.memory, pending:pendingSummary(g), zones:g.getDebugSummary().zones});
    if(issues.length) break;
  }
  return {name:'10-turn mixed official-flow smoke match', turnReports, logs:g.actionLogs.slice(-30), issues};
}

