function testRound18HOfficialMulliganOrderGuard(){
  const issues=[];
  const g = new GameState({name:'P1',avatar:null},{name:'P2',avatar:null},makeDeck(['BT1-010','BT1-011']),makeDeck(['BT2-010','BT2-011']),{startingPlayer:'p2'});
  if(g.nextMulliganPlayer !== 'p2') issues.push(`nextMulliganPlayer should start with first player p2, got ${g.nextMulliganPlayer}`);
  const blocked = g.decideMulligan('p1', true);
  if(blocked !== false) issues.push('second player mulligan should be rejected before first player decides');
  if(g.mulliganDecisions.p1 !== null) issues.push('rejected second player mulligan must not mutate mulliganDecisions.p1');
  if(g.zones.p1.hand.length !== 5) issues.push('rejected mulligan must not redraw the second player hand');
  const firstOk = g.decideMulligan('p2', false);
  if(firstOk !== true || g.nextMulliganPlayer !== 'p1') issues.push(`after first player decision, nextMulliganPlayer should advance to p1, got ${g.nextMulliganPlayer}`);
  if(g.zones.p1.security.length !== 0 || g.zones.p2.security.length !== 0) issues.push('security must not be placed until both ordered mulligan decisions complete');
  const secondOk = g.decideMulligan('p1', false);
  if(secondOk !== true) issues.push('second player should be allowed after first player decides');
  if(g.phase !== 'HATCH') issues.push(`after both ordered mulligans, game should enter opening turn flow, got ${g.phase}`);
  if(g.zones.p1.security.length !== 5 || g.zones.p2.security.length !== 5) issues.push('security should be placed after both ordered mulligan decisions');

  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
  const server=fs.readFileSync(path.join(__dirname,'server.js'),'utf8');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/getExpectedMulliganPlayer\(\)/.test(gs) || !/playerId !== expectedPlayer/.test(gs)) issues.push('game-state.js should enforce first-player-first mulligan order');
  if(!/nextMulliganPlayer/.test(html) || !/canDeclareMulligan/.test(html)) issues.push('index.html should hide mulligan buttons until it is that player’s official decision turn');
  if(!/Waiting for/.test(server) || !/nextMulliganPlayer/.test(server)) issues.push('server should report ordered mulligan rejection instead of silently ignoring it');
  if(!/mulliganOrderLeak/.test(audit)) issues.push('audit-mechanics.js should include a Round 18H mulligan-order runtime guard');
  if(!/Round 18H official setup\/mulligan-order guardrails/.test(auto)) issues.push('auto-mechanics.js should document the official mulligan-order guardrail');
  return {name:'Round 18H official mulligan declaration order guard', summary:g.getDebugSummary(), issues};
}


function testRound18IOfficialRedrawProcedureGuard(){
  const issues=[];
  const g = new GameState({name:'P1',avatar:null},{name:'P2',avatar:null},makeDeck(['BT1-010','BT1-011','BT1-012','BT1-013','BT1-014']),makeDeck(['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']),{startingPlayer:'p1'});
  const originalHandIds = g.zones.p1.hand.map(c=>c.instanceId);
  const deckCountBefore = g.zones.p1.deck.length;
  const ok = g.decideMulligan('p1', true);
  if(ok !== true) issues.push('first player should be allowed to declare official re-draw');
  if(g.zones.p1.hand.length !== 5) issues.push(`official re-draw should draw exactly 5 cards, got ${g.zones.p1.hand.length}`);
  if(g.zones.p1.deck.length !== deckCountBefore) issues.push(`return-then-draw should preserve deck count before security setup; before ${deckCountBefore}, after ${g.zones.p1.deck.length}`);
  // Round 18J: this guard must not be flaky. After a legal return+shuffle+draw,
  // it is possible to draw one of the same physical cards again. Verify the
  // returned opening hand still exists in the combined deck/hand pool instead
  // of incorrectly requiring none of those instanceIds to be redrawn.
  const returnedPoolCount = originalHandIds.filter(id => g.zones.p1.deck.some(c=>c.instanceId===id) || g.zones.p1.hand.some(c=>c.instanceId===id)).length;
  if(returnedPoolCount !== originalHandIds.length) issues.push(`all returned initial hand cards should remain in deck/hand after shuffle+redraw, got ${returnedPoolCount}/${originalHandIds.length}`);
  const newHandUnique = new Set(g.zones.p1.hand.map(c=>c.instanceId)).size;
  if(newHandUnique !== g.zones.p1.hand.length) issues.push('re-draw hand should not contain duplicate physical instanceIds');
  const secondRedraw = g.decideMulligan('p1', true);
  if(secondRedraw !== false) issues.push('a player must not be able to re-draw more than once during setup');
  if(g.zones.p1.security.length !== 0 || g.zones.p2.security.length !== 0) issues.push('security must not be placed after only the first player re-draws');
  g.decideMulligan('p2', false);
  if(g.zones.p1.security.length !== 5 || g.zones.p2.security.length !== 5) issues.push('security should be placed only after both players complete keep/re-draw decisions');
  if(g.zones.p1.deck.length !== 40 || g.zones.p2.deck.length !== 40) issues.push(`after opening hand and security setup, each main deck should have 40 cards, got p1=${g.zones.p1.deck.length}, p2=${g.zones.p2.deck.length}`);

  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/zone\.deck\.push\(\.\.\.zone\.hand\)/.test(gs) || !/this\.shuffle\(zone\.deck\)/.test(gs)) issues.push('game-state.js should explicitly return hand to deck and shuffle during re-draw');
  if(!/mulliganRedrawProcedureLeak/.test(audit)) issues.push('audit-mechanics.js should include Round 18I re-draw procedure guard');
  if(!/Round 18I official setup\/re-draw procedure guardrails/.test(auto)) issues.push('auto-mechanics.js should document the official re-draw procedure guardrail');
  return {name:'Round 18I official re-draw procedure guard', summary:g.getDebugSummary(), issues};
}

