function testRound21UGrantedStartMainAttackTriggerGuard(){
  const issues=[];
  const ids=['BT21-073','BT16-058','BT18-099','P-183','BT25-054','BT21-057','BT12-107','BT12-065','BT23-032','BT23-056','EX10-034','EX5-048','EX10-008','EX6-042','BT21-077','ST15-16'];
  const walkActions=function*(obj){
    if(!obj || typeof obj!=='object') return;
    if(Array.isArray(obj)){ for(const v of obj) yield* walkActions(v); return; }
    if(obj.type) yield obj;
    for(const v of Object.values(obj)) yield* walkActions(v);
  };
  for(const id of ids){
    const card=byId.get(id);
    if(!card){ issues.push(`${id} missing from cards.json`); continue; }
    const blob=JSON.stringify(card.mechanics||[]);
    const actions=[...walkActions(card.mechanics||[])];
    if(actions.some(a=>a.type==='GRANT_KEYWORD' && /Start of Your Main Phase/i.test(String(a.buff?.keyword||a.buff?.value||a.keyword||'')) && /(This Digimon attacks|Attack with this Digimon)/i.test(String(a.buff?.keyword||a.buff?.value||a.keyword||'')))) issues.push(`${id} still encodes granted Start-of-Main attack text as GRANT_KEYWORD.`);
    if(!actions.some(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='START_OF_MAIN_PHASE' && JSON.stringify(a).includes('forcedAttack'))) issues.push(`${id} should encode granted Start-of-Main attack text as GRANT_TRIGGER_EFFECT START_OF_MAIN_PHASE with forcedAttack.`);
  }
  const fist=byId.get('BT18-099');
  const fistActions=[...walkActions(fist?.mechanics||[])];
  if(!fistActions.some(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='START_OF_MAIN_PHASE' && a.target?.owner==='opponent')) issues.push('BT18-099 Fist of Athena should grant the forced-attack text to an opponent Digimon, not your own Digimon.');
  try{
    const g=mkGame(['BT1-010','BT2-010'], ['BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const victim=addBattle(g,'p2','BT2-011',{tag:'forced-victim',stack:[]});
    victim.isSuspended=false; victim.playedThisTurn=false;
    enqueue(g,'p1',addBattle(g,'p1','BT1-010',{tag:'source',stack:[]}),[{type:'GRANT_TRIGGER_EFFECT',trigger:'START_OF_MAIN_PHASE',target:{owner:'opponent',cardType:'digimon',count:1},actions:[{type:'REQUEST_ATTACK_PLAYER',target:{owner:'own',cardType:'digimon',self:true,count:1},forcedAttack:true,label:'Round 21U granted forced attack'}],duration:'OPPONENTS_END_OF_TURN'}],'manual-start-main-grant');
    autoResolve(g);
    if(!Array.isArray(victim.turnEffects) || !victim.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='START_OF_MAIN_PHASE')) issues.push('Opponent Digimon should receive a temporary START_OF_MAIN_PHASE granted trigger.');
    g.turnPlayer='p2'; g.enterMainPhase('p2');
    if(!victim.isSuspended) issues.push('Granted Start-of-Main forced attack should suspend/attack with the affected Digimon when legal.');
    const pendingAttack = g.counterTiming?.pendingAttack || {};
    if(!g.counterTiming?.isActive || pendingAttack.attackerInstanceId !== victim.instanceId) issues.push('Granted Start-of-Main forced attack should open an attack/counter flow from the affected Digimon.');
    autoResolve(g);
  } catch(e){ issues.push('Round21U granted Start-of-Main runtime simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21U: granted Start-of-Main forced-attack text/.test(gs)) issues.push('game-state should route forcedAttack requests through forced-attack legality helper.');
  if(!/enqueueGrantedTriggerEffectsForCard\(activePlayerId, card, 'START_OF_MAIN_PHASE'/.test(gs)) issues.push('enterMainPhase should enqueue START_OF_MAIN_PHASE granted triggers from affected Digimon.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/grantedStartMainAttackKeywordLeak/.test(audit)) issues.push('audit-mechanics should guard granted Start-of-Main attack keyword leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21U granted Start-of-Main forced-attack guardrails/.test(auto)) issues.push('auto-mechanics should document Round 21U granted Start-of-Main guardrails.');
  return { name:'Round 21U granted Start-of-Main forced-attack guard', issues };
}



function testRound21WGrantedEndOfAttackTriggerGuard(){
  const issues=[];
  const card=byId.get('EX7-058');
  const witch=byId.get('EX6-048');
  if(!card) issues.push('EX7-058 missing from cards.json');
  if(!witch) issues.push('EX6-048 missing from cards.json');
  const walkActions=function*(obj){
    if(!obj || typeof obj!=='object') return;
    if(Array.isArray(obj)){ for(const v of obj) yield* walkActions(v); return; }
    if(obj.type) yield obj;
    for(const v of Object.values(obj)) yield* walkActions(v);
  };
  const actions=[...walkActions(card?.mechanics||[])];
  const witchActions=[...walkActions(witch?.mechanics||[])];
  const badKeyword=actions.find(a=>a.type==='GRANT_KEYWORD' && /end of attack/i.test(String(a.buff?.keyword||a.keyword||'')) && /delete this digimon/i.test(String(a.buff?.keyword||a.keyword||'')));
  if(badKeyword) issues.push('EX7-058 still grants End of Attack deletion as GRANT_KEYWORD.');
  const grants=actions.filter(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='END_OF_ATTACK' && JSON.stringify(a).includes('DELETE_DIGIMON'));
  if(grants.length < 2) issues.push('EX7-058 On Play and When Digivolving should both grant END_OF_ATTACK -> DELETE_DIGIMON.');
  if(actions.some(a=>a.type==='PLAY_FROM_HAND_OR_TRASH' && a.target?.cardType==='option' && JSON.stringify(a.target||{}).includes('LadyDevimon'))) issues.push('EX7-058 should not try to play a LadyDevimon/X Antibody option before making the token.');
  if(!actions.some(a=>a.type==='PLAY_TOKEN' && String(a.token?.name||'').includes('Volée'))) issues.push('EX7-058 should keep the printed Volée & Zerdrücken Token creation.');
  if(witchActions.some(a=>a.type==='SCHEDULE_DELAYED_ACTION' && String(a.timing||'').toUpperCase()==='END_OF_ATTACK')) issues.push('EX6-048 Witchmon should grant an END_OF_ATTACK trigger to the chosen Digimon, not schedule a global delayed deletion.');
  if(witchActions.filter(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='END_OF_ATTACK' && JSON.stringify(a).includes('DELETE_DIGIMON')).length < 2) issues.push('EX6-048 Witchmon On Play/When Digivolving should both grant END_OF_ATTACK -> DELETE_DIGIMON.');
  try{
    const g=mkGame(['EX7-058','BT2-010'], ['BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const source=addBattle(g,'p1','EX7-058',{tag:'lady-source',stack:[]});
    const victim=addBattle(g,'p2','BT2-011',{tag:'victim',stack:[clone('BT2-010','src')],playedThisTurn:false,isSuspended:false});
    enqueue(g,'p1',source,[{type:'GRANT_TRIGGER_EFFECT',trigger:'END_OF_ATTACK',target:{owner:'opponent',cardType:'digimon',count:1},actions:[{type:'DELETE_DIGIMON',target:{owner:'own',cardType:'digimon',self:true,count:1}}],duration:'OPPONENTS_END_OF_TURN'}],'manual-end-attack-delete');
    autoResolve(g);
    if(!Array.isArray(victim.turnEffects) || !victim.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='END_OF_ATTACK')) issues.push('End-of-Attack grant should attach a temporary trigger to the chosen opponent Digimon.');
    g.counterTiming = { isActive:false, defenderId:'p1', pendingAttack:{targetType:'player'}, step:'IDLE' };
    g.triggerEndOfAttackTiming('p2', victim.instanceId);
    autoResolve(g);
    if(g.zones.p2.battleArea.some(c=>c.instanceId===victim.instanceId)) issues.push('Granted END_OF_ATTACK trigger should delete the Digimon carrying it.');
    if(!g.zones.p2.trash.some(c=>c.instanceId===victim.instanceId)) issues.push('Deleted granted-trigger Digimon should move to its owner trash.');
  } catch(e){ issues.push('Round21W END_OF_ATTACK granted-trigger runtime simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21W: text granted to a Digimon/.test(gs)) issues.push('game-state should enqueue granted END_OF_ATTACK triggers during End of Attack timing.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/grantedEndOfAttackTriggerKeywordLeak/.test(audit)) issues.push('audit-mechanics should guard granted End of Attack keyword leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21W granted End-of-Attack trigger guardrails/.test(auto)) issues.push('auto-mechanics should document Round 21W granted End-of-Attack guardrails.');
  return { name:'Round 21W granted End-of-Attack trigger guard', issues };
}

function testRound21VGrantedWhenAttackingTriggerGuard(){
  const issues=[];
  const ids=['EX1-068','BT11-087','BT6-096','BT4-101','BT5-091'];
  const walkActions=function*(obj){
    if(!obj || typeof obj!=='object') return;
    if(Array.isArray(obj)){ for(const v of obj) yield* walkActions(v); return; }
    if(obj.type) yield obj;
    for(const v of Object.values(obj)) yield* walkActions(v);
  };
  for(const id of ids){
    const card=byId.get(id);
    if(!card){ issues.push(`${id} missing from cards.json`); continue; }
    const actions=[...walkActions(card.mechanics||[])];
    const badKeyword=actions.find(a=>a.type==='GRANT_KEYWORD' && /when attacking/i.test(String(a.buff?.keyword||a.keyword||'')));
    if(badKeyword) issues.push(`${id} still encodes granted When Attacking text as GRANT_KEYWORD.`);
    const badTrait=actions.find(a=>String(a.type||'').toUpperCase()==='HAS_TRAIT' && /when attacking/i.test(String(a.trait||a.value||'')));
    if(badTrait) issues.push(`${id} still checks granted When Attacking text via HAS_TRAIT.`);
    if(!actions.some(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='WHEN_ATTACKING')) issues.push(`${id} should use GRANT_TRIGGER_EFFECT with trigger WHEN_ATTACKING.`);
  }
  const ice=byId.get('EX1-068');
  const iceActions=[...walkActions(ice?.mechanics||[])];
  if(!iceActions.some(a=>a.type==='GRANT_TRIGGER_EFFECT' && a.trigger==='WHEN_ATTACKING' && JSON.stringify(a).includes('LOSE_MEMORY') && JSON.stringify(a).includes('2'))) issues.push('EX1-068 Ice Wall should grant WHEN_ATTACKING -> LOSE_MEMORY 2.');
  const takumi=byId.get('BT5-091');
  const takumiBlob=JSON.stringify(takumi?.mechanics||[]);
  if(!/ALL_TURNS/.test(takumiBlob) || !/GRANT_TRIGGER_EFFECT/.test(takumiBlob) || !/minLevel/.test(takumiBlob) || !/maxLevel/.test(takumiBlob)) issues.push('BT5-091 Takumi Aiba should statically grant the attack tax to all Lv.3 Digimon.');
  const trident=JSON.stringify(byId.get('BT6-096')?.mechanics||[]);
  if(!/sameAsPreviousTarget/.test(trident) || !/currentAttackTarget/.test(trident)) issues.push('BT6-096 Forbidden Trident should bind the granted trigger to the buffed Digimon and then to the current attack target.');
  const drag=JSON.stringify(byId.get('BT4-101')?.mechanics||[]);
  if(!/currentAttackTarget/.test(drag) || !/maxSourceCount/.test(drag)) issues.push('BT4-101 should delete only the current no-source attack target.');
  try{
    const g=mkGame(['BT1-010','BT2-010'], ['BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const source=addBattle(g,'p1','BT1-010',{tag:'ice-source',stack:[]});
    const attacker=addBattle(g,'p2','BT2-011',{tag:'ice-victim',stack:[],playedThisTurn:false,isSuspended:false});
    enqueue(g,'p1',source,[{type:'GRANT_TRIGGER_EFFECT',trigger:'WHEN_ATTACKING',target:{owner:'opponent',cardType:'digimon',count:'all'},actions:[{type:'LOSE_MEMORY',amount:2}],duration:'OPPONENTS_END_OF_TURN'}],'manual-ice-wall');
    autoResolve(g);
    if(!Array.isArray(attacker.turnEffects) || !attacker.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='WHEN_ATTACKING')) issues.push('Ice Wall-style action should attach WHEN_ATTACKING trigger to opponent Digimon.');
    g.turnPlayer='p2'; g.phase='MAIN'; g.memory=0;
    g.declareAttack('p2', attacker.instanceId, 'player');
    autoResolve(g);
    if(g.memory !== 2) issues.push(`P2 attacking with granted LOSE_MEMORY 2 should move memory to +2, got ${g.memory}.`);
  } catch(e){ issues.push('Round21V Ice Wall runtime simulation failed: '+(e.stack||e.message||e)); }
  try{
    const g=mkGame(['BT5-091','BT1-010'], ['BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p2'; g.phase='MAIN';
    addBattle(g,'p1','BT5-091',{tag:'takumi',stack:[]});
    const lv3=addBattle(g,'p2','BT2-011',{tag:'lv3',stack:[],playedThisTurn:false,isSuspended:false,level:3});
    g.declareAttack('p2', lv3.instanceId, 'player');
    autoResolve(g);
    if(g.memory !== 1) issues.push(`Takumi static Lv.3 attack tax should make P2 lose 1 memory, got ${g.memory}.`);
  } catch(e){ issues.push('Round21V Takumi static attack-tax simulation failed: '+(e.stack||e.message||e)); }
  try{
    const g=mkGame(['BT1-010','BT2-010'], ['BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const attacker=addBattle(g,'p1','BT1-010',{tag:'trident-attacker',stack:[],playedThisTurn:false,isSuspended:false});
    const target=addBattle(g,'p2','BT2-011',{tag:'lv3-target',stack:[clone('BT2-010','src')],playedThisTurn:false,isSuspended:true,level:3});
    enqueue(g,'p1',attacker,[{type:'GRANT_TRIGGER_EFFECT',trigger:'WHEN_ATTACKING',target:{owner:'own',cardType:'digimon',self:true,count:1},actions:[{type:'BOUNCE',target:{owner:'opponent',cardType:'digimon',count:1,maxLevel:3,currentAttackTarget:true}}],duration:'END_OF_TURN'}],'manual-trident-grant');
    autoResolve(g);
    g.declareAttack('p1', attacker.instanceId, 'digimon', target.instanceId);
    autoResolve(g);
    if(!g.zones.p2.hand.some(c=>c.instanceId===target.instanceId)) issues.push('Forbidden Trident-style trigger should bounce the current level 3 attack target to hand.');
    if(!g.zones.p2.trash.some(c=>c.id==='BT2-010')) issues.push('Returning the current attack target should trash its source cards by battle-area leave rules.');
  } catch(e){ issues.push('Round21V current attack target simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21V: temporary\/static text granted to the attacker/.test(gs)) issues.push('game-state should enqueue WHEN_ATTACKING granted triggers when the attacker attacks.');
  if(!/enqueueStaticGrantedTriggerEffectsForCard/.test(gs)) issues.push('game-state should evaluate static GRANT_TRIGGER_EFFECT providers such as Takumi at attack time.');
  if(!/currentAttackTarget/.test(gs)) issues.push('game-state should bind granted attack actions to the current attack target.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/grantedWhenAttackingTriggerKeywordLeak/.test(audit)) issues.push('audit-mechanics should guard granted When Attacking keyword leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21V granted When-Attacking trigger guardrails/.test(auto)) issues.push('auto-mechanics should document Round 21V granted When-Attacking guardrails.');
  return { name:'Round 21V granted When-Attacking trigger guard', issues };
}


function testRound21XGrantedAttackAndSuspendTriggerGuard(){
  const issues=[];
  const fros=JSON.stringify((byId.get('BT8-031')||{}).mechanics||[]);
  if(!/GRANT_TRIGGER_EFFECT/.test(fros) || !/WHEN_ATTACKING/.test(fros) || !/TRASH_BOTTOM_EVO/.test(fros) || !/"self"\s*:\s*true/.test(fros)) issues.push('BT8-031 should grant a real WHEN_ATTACKING -> TRASH_BOTTOM_EVO self trigger, not a fake keyword.');
  const waltz=JSON.stringify((byId.get('BT13-108')||{}).mechanics||[]);
  if(!/GRANT_TRIGGER_EFFECT/.test(waltz) || !/DIGIMON_SUSPENDED/.test(waltz) || !/DELETE_DIGIMON/.test(waltz) || !/"maxCost"\s*:\s*"this"/.test(waltz)) issues.push("BT13-108 Waltz's End should grant a real opponent-turn suspended trigger using maxCost:this.");
  if(!/lowest_play_cost/.test(waltz)) issues.push("BT13-108 Security should delete the opponent Digimon with the lowest play cost, not lowest level.");
  try{
    const g=mkGame(['BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const attacker=addBattle(g,'p1','BT1-010',{tag:'fros-attacker',stack:[clone('BT1-011','fros-src')],playedThisTurn:false,isSuspended:false});
    addBattle(g,'p2','BT8-031',{tag:'fros-provider',stack:[],playedThisTurn:false,isSuspended:false});
    g.declareAttack('p1', attacker.instanceId, 'player', null);
    autoResolve(g);
    if((attacker.stack||[]).length!==0) issues.push('FrosVelgrmon static granted WHEN_ATTACKING trigger should trash the attacker bottom source.');
    if(!g.zones.p1.trash.some(c=>c.id==='BT1-011')) issues.push('FrosVelgrmon granted trigger should move the trashed source to the attacker controller trash.');
  } catch(e){ issues.push('Round21X FrosVelgrmon simulation failed: '+(e.stack||e.message||e)); }
  try{
    const g=mkGame(['BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const source=addBattle(g,'p1','BT1-010',{tag:'waltz-target',playCost:3,stack:[],playedThisTurn:false,isSuspended:false});
    const cheap=addBattle(g,'p2','BT2-010',{tag:'waltz-cheap',playCost:3,stack:[],playedThisTurn:false,isSuspended:false});
    const expensive=addBattle(g,'p2','BT8-031',{tag:'waltz-expensive',playCost:11,stack:[],playedThisTurn:false,isSuspended:false});
    enqueue(g,'p1',base('BT13-108'),(byId.get('BT13-108').mechanics.find(m=>m.trigger==='MAIN')||{}).actions,'Waltz End');
    autoResolve(g);
    if(!Array.isArray(source.turnEffects) || !source.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='DIGIMON_SUSPENDED')) issues.push("Waltz's End should attach a DIGIMON_SUSPENDED granted trigger to the chosen Digimon.");
    if(!source.turnEffects.some(e=>e.type==='UNAFFECTED_BY_OPPONENT_EFFECTS')) issues.push("Waltz's End Option immunity should bind to the same chosen Digimon.");
    g.turnPlayer='p2'; g.phase='MAIN'; source.isSuspended=true; g.triggerDigimonSuspendedEvent('p1', source, {byEffect:true});
    autoResolve(g);
    if(!g.zones.p2.trash.some(c=>c.instanceId===cheap.instanceId)) issues.push("Waltz's End granted suspend trigger should delete opponent Digimon with play cost <= this Digimon.");
    if(!g.zones.p2.battleArea.some(c=>c.instanceId===expensive.instanceId)) issues.push("Waltz's End granted suspend trigger must not delete opponent Digimon above this Digimon's play cost.");
  } catch(e){ issues.push('Round21X Waltz End simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21X: targeted granted-trigger text/.test(gs)) issues.push('game-state should open a target window for targeted GRANT_TRIGGER_EFFECT grants.');
  if(!/maxCostLimit/.test(gs)) issues.push('game-state should support maxCost:"this" for granted same-Digimon play-cost comparisons.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/trash the bottom digivolution card of this digimon/.test(audit)) issues.push('audit-mechanics should guard FrosVelgrmon-style granted source-trash keyword leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21X granted source-trash/.test(auto)) issues.push('auto-mechanics should document Round 21X granted trigger guardrails.');
  return { name:'Round 21X granted attack/suspend trigger guard', issues };
}



function testRound21ZGrantedEndTurnDeletionTriggerGuard(){
  const issues=[];
  const blob=id=>JSON.stringify((byId.get(id)||{}).mechanics||[]);
  for(const id of ['EX10-058','EX6-057','EX6-070']){
    const b=blob(id);
    if(!/GRANT_TRIGGER_EFFECT/.test(b) || !/END_OF_TURN/.test(b) || !/DELETE_DIGIMON/.test(b)) issues.push(`${id} should encode granted [End of Your Turn] deletion as GRANT_TRIGGER_EFFECT END_OF_TURN.`);
    if(/GRANT_KEYWORD/.test(b) && /END_OF_TURN/.test(b) && /DELETE_DIGIMON/.test(b)) issues.push(`${id} must not keep fake GRANT_KEYWORD END_OF_TURN DELETE_DIGIMON text.`);
  }
  const skull=blob('BT10-080');
  if(/GRANT_KEYWORD/.test(skull) && /ON_DELETION/.test(skull) && /DELETE_DIGIMON/.test(skull)) issues.push('BT10-080 should not keep fake granted On Deletion DELETE_DIGIMON keyword text.');
  if(!/GRANT_TRIGGER_EFFECT/.test(skull) || !/ON_DELETION/.test(skull) || !/DELETE_DIGIMON/.test(skull)) issues.push('BT10-080 should encode granted On Deletion delete as GRANT_TRIGGER_EFFECT.');
  try{
    const g=mkGame(['EX6-057','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const lilith=addBattle(g,'p1','EX6-057',{tag:'lilith-source',stack:[],playedThisTurn:false,isSuspended:false});
    const victim=addBattle(g,'p2','BT2-010',{tag:'endturn-victim',stack:[],playedThisTurn:false,isSuspended:false});
    enqueue(g,'p1',lilith,(byId.get('EX6-057').mechanics.find(m=>m.trigger==='ON_PLAY')||{}).actions,'EX6 Lilithmon');
    autoResolve(g);
    if(!Array.isArray(victim.turnEffects) || !victim.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='END_OF_TURN')) issues.push('EX6-057 should attach END_OF_TURN granted trigger to selected opponent Digimon.');
    g.turnPlayer='p2'; g.phase='MAIN'; g.passTurn(); autoResolve(g);
    if(!g.zones.p2.trash.some(c=>c.instanceId===victim.instanceId)) issues.push('Granted END_OF_TURN delete trigger should delete the affected Digimon at its controller End of Turn.');
  } catch(e){ issues.push('Round21Z granted End-of-Turn runtime simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21Z: granted/.test(gs) || !/enqueueGrantedTriggerEffectsForCard\(playerId, card, 'END_OF_TURN'/.test(gs)) issues.push('game-state should enqueue granted END_OF_TURN triggers during End of Turn timing.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/grantedEndOfTurnDeletionKeywordLeak/.test(audit)) issues.push('audit-mechanics should guard fake keyword encoding for granted End-of-Turn deletion text.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21Z granted End-of-Turn deletion/.test(auto)) issues.push('auto-mechanics should document Round 21Z guardrails.');
  return { name:'Round 21Z granted End-of-Turn deletion trigger guard', issues };
}

function testRound21YActivatePrintedTriggerEffectGuard(){
  const issues=[];
  const c=id=>byId.get(id)||{};
  const blob=id=>JSON.stringify(c(id).mechanics||[]);
  const hasBadGrant=(id,kw)=> (c(id).mechanics||[]).some(m => JSON.stringify(m.actions||[]).includes('GRANT_KEYWORD') && JSON.stringify(m.actions||[]).includes(kw));
  const crimson=blob('BT11-097');
  if(!/ACTIVATE_TRIGGER_EFFECT/.test(crimson) || !/ON_DELETION/.test(crimson) || !/"trait":"Vaccine"|"trait":\s*"Vaccine"/.test(crimson) || !/"color":"Red"|"color":\s*"Red"/.test(crimson)) issues.push('BT11-097 Crimson Flare should activate one red Vaccine ON_DELETION effect, not grant an On Deletion keyword.');
  if(hasBadGrant('BT11-097','On Deletion')) issues.push('BT11-097 must not use GRANT_KEYWORD for printed activate [On Deletion] text.');
  const seiken=blob('BT10-110');
  if(!/ACTIVATE_TRIGGER_EFFECT/.test(seiken) || !/WHEN_DIGIVOLVING/.test(seiken) || !/sameAsPreviousTarget/.test(seiken) || !/Jesmon GX/.test(seiken)) issues.push('BT10-110 should activate one When Digivolving effect of the same Jesmon GX target.');
  if(hasBadGrant('BT10-110','When Digivolving')) issues.push('BT10-110 must not use GRANT_KEYWORD for printed activate [When Digivolving] text.');
  const nume=blob('BT15-057');
  if(!/GRANT_TRIGGER_EFFECT/.test(nume) || !/ON_DELETION/.test(nume) || !/PLAY_FROM_TRASH/.test(nume) || !/scope/.test(nume)) issues.push('BT15-057 static granted On Deletion should be a source-gated GRANT_TRIGGER_EFFECT.');
  const regulus=blob('RB1-030');
  if(!/GRANT_TRIGGER_EFFECT/.test(regulus) || !/ON_DELETION/.test(regulus) || !/lowest_level/.test(regulus)) issues.push('RB1-030 should grant a real ON_DELETION trigger deleting one lowest-level opponent Digimon.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/Round 21Y: printed clauses/.test(gs) || !/activateTriggerEffectOnCards/.test(gs)) issues.push('game-state should support same-target ACTIVATE_TRIGGER_EFFECT activation.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/activatePrintedTriggerKeywordLeak/.test(audit)) issues.push('audit-mechanics should guard fake keyword encoding for printed activate-trigger clauses.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 21Y activate printed trigger-effect guardrails/.test(auto)) issues.push('auto-mechanics should document Round 21Y activate-trigger guardrails.');
  return { name:'Round 21Y activate printed trigger-effect guard', issues };
}




function testRound22CMayAttackRequestGuard(){
  const issues=[];
  const ids=['BT20-044','BT23-047','BT12-100','BT20-017','BT20-019','BT24-047','BT22-015','EX8-027'];
  for(const id of ids){
    const c=byId.get(id)||{};
    const blob=JSON.stringify(c.mechanics||[]);
    if(/"GRANT_KEYWORD"[^}]*"may attack(?: a player)?"/i.test(blob) || /"keyword"\s*:\s*"may attack(?: a player)?"/i.test(blob)) issues.push(`${id} must not encode printed may-attack as GRANT_KEYWORD.`);
    if(!/REQUEST_ATTACK_PLAYER/.test(blob)) issues.push(`${id} should encode printed may-attack as REQUEST_ATTACK_PLAYER.`);
  }
  const finalBlade=JSON.stringify((byId.get('BT12-100')||{}).mechanics||[]);
  const kokatorimon=JSON.stringify((byId.get('BT24-047')||{}).mechanics||[]);
  if(!/sameAsPreviousTarget/.test(finalBlade)) issues.push('BT12-100 Final Xros Blade should bind “it may attack a player” to the unsuspended Shoutmon X7: Superior Mode.');
  if(!/sameAsPreviousTarget/.test(kokatorimon)) issues.push('BT24-047 Kokatorimon should bind “that Digimon may attack” to the Digimon unsuspended by this effect.');
  try{
    const g=mkGame(['BT20-044','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingChoice=null; g.actionLogs=[]; g.turnPlayer='p1'; g.phase='MAIN';
    const breakdra=addBattle(g,'p1','BT20-044',{tag:'break',playedThisTurn:false,isSuspended:false,stack:[]});
    const agumon=addBattle(g,'p1','BT1-010',{tag:'agumon',playedThisTurn:false,isSuspended:false,stack:[]});
    const action=((byId.get('BT20-044').mechanics||[]).find(m=>m.trigger==='ON_PLAY').actions||[]).find(a=>a.type==='REQUEST_ATTACK_PLAYER');
    if(!action) issues.push('BT20-044 should have a REQUEST_ATTACK_PLAYER action for the follow-up may-attack clause.');
    else {
      const ok=g.requestAttackPlayer('p1', breakdra, action);
      if(!ok || g.pendingChoice?.mode!=='ATTACK_PLAYER_CHOICE') issues.push('REQUEST_ATTACK_PLAYER runtime should open an optional attacker choice window for “1 of your Digimon may attack”.');
      if(!(g.pendingChoice?.cards||[]).some(c=>c.instanceId===agumon.instanceId)) issues.push('Effect attack choice should include a legal own Digimon attacker, not just the source card.');
    }
  } catch(e){ issues.push('Round22C REQUEST_ATTACK_PLAYER runtime simulation failed: '+(e.stack||e.message||e)); }
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/mayAttackKeywordRequestLeak/.test(audit)) issues.push('audit-mechanics should guard may-attack GRANT_KEYWORD leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22C may-attack request/.test(auto)) issues.push('auto-mechanics should document Round 22C guardrails.');
  return { name:'Round 22C may-attack request guard', issues };
}

function testRound22BGrantedOnDeletionPlayGainGuard(){
  const issues=[];
  const kristy=base('BT13-094');
  const cooties=base('BT11-106');
  const kristyBlob=JSON.stringify(kristy.mechanics||[]);
  const cootiesBlob=JSON.stringify(cooties.mechanics||[]);
  if(/GRANT_KEYWORD/.test(kristyBlob) && /Biyomon/.test(kristyBlob)) issues.push('BT13-094 must not encode granted On Deletion play-Biyomon text as GRANT_KEYWORD.');
  if(!/GRANT_TRIGGER_EFFECT/.test(kristyBlob) || !/ON_DELETION/.test(kristyBlob) || !/PLAY_FROM_HAND_OR_TRASH/.test(kristyBlob) || !/Biyomon/.test(kristyBlob)) issues.push('BT13-094 should grant ON_DELETION -> PLAY_FROM_HAND_OR_TRASH Biyomon.');
  if((cooties.mechanics||[]).some(m => (m.actions||[]).some(a => a.type==='GRANT_KEYWORD' && /Gain 3 memory/i.test(String(a.buff?.keyword||a.keyword||''))))) issues.push('BT11-106 must not encode granted On Deletion Gain 3 memory as GRANT_KEYWORD.');
  if(!/GRANT_TRIGGER_EFFECT/.test(cootiesBlob) || !/ON_DELETION/.test(cootiesBlob) || !/GAIN_MEMORY/.test(cootiesBlob)) issues.push('BT11-106 should grant ON_DELETION -> GAIN_MEMORY 3.');
  if(!/sameAsPreviousTarget/.test(cootiesBlob)) issues.push('BT11-106 granted On Deletion clause should bind to the same Digimon that gained cannot-be-blocked.');
  try{
    const g=mkGame(['BT13-094','BT1-010','BT2-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.zones.p1.hand=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const kristyCard=addBattle(g,'p1','BT13-094',{tag:'kristy'});
    const target=addBattle(g,'p1','BT1-010',{tag:'granted-target',stack:[]});
    const biyomon=addHand(g,'p1','BT2-010');
    const onPlay=(kristyCard.mechanics||[]).find(m=>m.trigger==='ON_PLAY');
    enqueue(g,'p1',kristyCard,onPlay.actions,'Kristy Damon On Play');
    autoResolve(g);
    if(!Array.isArray(target.turnEffects) || !target.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='ON_DELETION')) issues.push('BT13-094 runtime should attach a temporary ON_DELETION trigger to the chosen Digimon.');
    g.executePhysicalDeletion('p1', target, {byEffect:true});
    autoResolve(g);
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===biyomon.instanceId)) issues.push('BT13-094 granted On Deletion trigger should play Biyomon from hand when the affected Digimon is deleted.');
  } catch(e){ issues.push('BT13-094 granted On Deletion runtime simulation failed: '+(e.stack||e.message||e)); }
  try{
    const g=mkGame(['BT11-106','BT11-040','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const option=addBattle(g,'p1','BT11-106',{tag:'cooties'});
    const sukamon=addBattle(g,'p1','BT11-040',{tag:'sukamon',stack:[]});
    const main=(option.mechanics||[]).find(m=>m.trigger==='MAIN');
    enqueue(g,'p1',option,main.actions,'Cooties Kick Main');
    autoResolve(g);
    if(!Array.isArray(sukamon.turnEffects) || !sukamon.turnEffects.some(e=>e.type==='GRANTED_TRIGGER_EFFECT' && e.trigger==='ON_DELETION' && JSON.stringify(e.actions||[]).includes('GAIN_MEMORY'))) issues.push('BT11-106 runtime should attach ON_DELETION -> GAIN_MEMORY to the same chosen Digimon.');
    g.memory=0;
    g.executePhysicalDeletion('p1', sukamon, {byEffect:true});
    autoResolve(g);
    if(g.memory < 3) issues.push('BT11-106 granted On Deletion trigger should gain 3 memory when the affected Digimon is deleted.');
  } catch(e){ issues.push('BT11-106 granted On Deletion runtime simulation failed: '+(e.stack||e.message||e)); }
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/needsGainMemory/.test(audit) || !/needsPlayFromHandOrTrash/.test(audit)) issues.push('audit-mechanics should guard granted On Deletion gain/play keyword leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22B granted On-Deletion play\/gain/.test(auto)) issues.push('auto-mechanics should document Round 22B guardrails.');
  return { name:'Round 22B granted On-Deletion play/gain trigger guard', issues };
}

function testRound22AAttachEndAttackOnDeletionGuard(){
  const issues=[];
  const card=byId.get('BT16-015')||{};
  const mechanics=card.mechanics||[];
  const blob=JSON.stringify(mechanics);
  const endAttack=mechanics.find(m=>m.trigger==='END_OF_ATTACK');
  if(!endAttack) issues.push('BT16-015 must encode attach [End of Attack] as a real END_OF_ATTACK timing copy.');
  if(endAttack && (!JSON.stringify(endAttack).includes('SOURCE_COUNT') || !JSON.stringify(endAttack).includes('Phoenixmon') || !JSON.stringify(endAttack).includes('X Antibody'))) issues.push('BT16-015 END_OF_ATTACK copy must be gated by Phoenixmon/X Antibody in this Digimon sources.');
  if((mechanics||[]).some(m => JSON.stringify(m.actions||[]).includes('GRANT_KEYWORD') && JSON.stringify(m.actions||[]).includes('"keyword":"End of Attack"'))) issues.push('BT16-015 must not keep fake GRANT_KEYWORD End of Attack encoding.');
  if(!/PLAYED_BY_THIS_EFFECT/.test(blob) || !/played_by_this_effect/.test(blob)) issues.push('BT16-015 delete follow-up must bind max DP to the Digimon played by this same effect.');
  if(!/exceptTrait/.test(blob) || !/Sea Animal/.test(blob)) issues.push('BT16-015 play target should exclude Sea Animal by trait exclusion, not fake textContains.');
  try{
    const g=mkGame(['BT16-015','EX5-009','BT1-010'], ['BT2-010','BT6-020']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.zones.p1.hand=[]; g.effectQueue=[]; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const phoenix=addBattle(g,'p1','BT16-015',{tag:'phoenixx',stack:[clone('BT15-014','source-phoenix')],playedThisTurn:false,isSuspended:true});
    const excludedSeaAnimal=addHand(g,'p1','BT15-007');
    const playCandidate=addHand(g,'p1','EX5-009');
    const small=addBattle(g,'p2','BT2-010',{tag:'small-target',dp:3000,stack:[]});
    const big=addBattle(g,'p2','BT6-020',{tag:'big-target',dp:6000,stack:[]});
    enqueue(g,'p1',phoenix,(endAttack||{}).actions||[],'Phoenixmon X End of Attack');
    autoResolve(g);
    if(g.zones.p1.battleArea.some(c=>c.instanceId===excludedSeaAnimal.instanceId)) issues.push('BT16-015 END_OF_ATTACK copy must not play red Sea Animal cards excluded by official text.');
    if(!g.zones.p1.hand.some(c=>c.instanceId===excludedSeaAnimal.instanceId)) issues.push('BT16-015 excluded Sea Animal candidate should remain in hand.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===playCandidate.instanceId)) issues.push('BT16-015 END_OF_ATTACK copy should play a legal red trait Digimon from hand.');
    if(!g.zones.p2.trash.some(c=>c.instanceId===small.instanceId)) issues.push('BT16-015 delete follow-up should delete an opponent Digimon with DP <= the played Digimon.');
    if(g.zones.p2.trash.some(c=>c.instanceId===big.instanceId)) issues.push('BT16-015 delete follow-up must not delete above the played Digimon DP.');
  } catch(e){ issues.push('Round22A Phoenixmon runtime simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/played_by_this_effect/.test(gs) || !/exceptTrait/.test(gs)) issues.push('game-state should support same-effect played DP limits and trait exclusions.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/attachEndAttackOnDeletionTimingLeak/.test(audit)) issues.push('audit-mechanics should guard attach-End-of-Attack On Deletion timing leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22A Phoenixmon X/.test(auto)) issues.push('auto-mechanics should document Round 22A guardrails.');
  return { name:'Round 22A attach End-of-Attack to On Deletion guard', issues };
}




function testRound22GCantUseOptionGuard(){
  const issues=[];
  const c=id=>byId.get(id)||{};
  const has=(id,pred)=>Array.isArray(c(id).mechanics)&&c(id).mechanics.some(pred);
  if(!has('EX1-072',m=>m.trigger==='MAIN' && JSON.stringify(m).includes('CANT_USE_OPTION') && JSON.stringify(m).includes('OPPONENTS_END_OF_TURN'))) issues.push('EX1-072 Main should use CANT_USE_OPTION through opponent next turn, not STUN on option cards.');
  if(!has('EX1-072',m=>m.trigger==='SECURITY' && JSON.stringify(m).includes('CANT_USE_OPTION') && JSON.stringify(m).includes('ADD_CURRENT_SECURITY_TO_HAND'))) issues.push('EX1-072 Security should lock opponent Option use for the turn then add to hand.');
  if(!has('BT8-057',m=>m.trigger==='OPPONENTS_TURN' && JSON.stringify(m).includes('ALL_DIGIMON_SUSPENDED') && JSON.stringify(m).includes('CANT_USE_OPTION'))) issues.push('BT8-057 Shivamon should lock opponent Option use while all own Digimon are suspended.');
  const blob=JSON.stringify(c('BT8-057').mechanics||[]);
  if(/SUSPEND_OPPONENT/.test(blob) && /cardType":"option/.test(blob)) issues.push('BT8-057 must not try to suspend Option cards to represent option-use lock.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/optionUseLocks/.test(gs) || !/case 'CANT_USE_OPTION'/.test(gs)) issues.push('game-state should support temporary CANT_USE_OPTION option-use locks.');
  if(!/ALL_DIGIMON_SUSPENDED/.test(gs)) issues.push('game-state should support ALL_DIGIMON_SUSPENDED condition for Shivamon-style static locks.');
  try{
    const g=mkGame(['EX1-072','BT1-010'], ['BT1-010','BT3-097']);
    g.zones.p1.hand=[]; g.zones.p2.hand=[]; g.zones.p1.trash=[]; g.zones.p2.trash=[];
    const shutdown=clone('EX1-072','round22g');
    const option=clone('BT3-097','round22g-option');
    g.zones.p1.hand.push(shutdown);
    g.zones.p2.hand.push(option);
    enqueue(g,'p1',shutdown,c('EX1-072').mechanics[0].actions,'Round22G Emergency Program Shutdown');
    autoResolve(g);
    if(!g.isOptionUseLocked('p2', option, {})) issues.push('Opponent should not be able to use Option cards after EX1-072 Main resolves.');
    g.cleanupTurnEffectsForTiming('p1','END_OF_TURN');
    if(!g.isOptionUseLocked('p2', option, {})) issues.push('EX1-072 Main lock should last through opponent next turn, not expire at controller EOT.');
    g.cleanupTurnEffectsForTiming('p2','END_OF_TURN');
    if(g.isOptionUseLocked('p2', option, {})) issues.push('EX1-072 Main lock should expire at opponent EOT.');

    const s=mkGame(['BT8-057','BT1-010'], ['BT3-097','BT1-010']);
    s.zones.p1.battleArea=[]; s.zones.p2.hand=[];
    const shiva=addBattle(s,'p1','BT8-057',{tag:'shiva',isSuspended:false});
    const p2option=addHand(s,'p2','BT3-097');
    s.turnPlayer='p2';
    if(s.isOptionUseLocked('p2', p2option, {})) issues.push('Shivamon should not lock Option use while any own Digimon is unsuspended.');
    shiva.isSuspended=true;
    if(!s.isOptionUseLocked('p2', p2option, {})) issues.push('Shivamon should lock opponent Option use while all own Digimon are suspended.');
  }catch(e){ issues.push('runtime CANT_USE_OPTION smoke failed: '+(e.stack||e.message)); }
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/cantUseOptionEncodingLeak/.test(audit)) issues.push('audit-mechanics should catch bad can\'t-use-Option encodings.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22G can't-use-Option/.test(auto)) issues.push('auto-mechanics should document Round 22G CANT_USE_OPTION guardrails.');
  return { name:'Round 22G can\'t-use-Option player lock guard', issues };
}

function testRound22FCantAttackOrBlockCantBlockGuard(){
  const issues=[];
  const printed=/can't attack or block|cannot attack or block/i;
  for(const c of cards){
    const mainText=String(c.mainEffect||'');
    const sourceText=String(c.sourceEffect||'');
    const text=`${mainText} ${sourceText}`;
    if(!printed.test(text)) continue;
    for(const [idx,m] of (c.mechanics||[]).entries()){
      const trigger=String(m.trigger||'').toUpperCase();
      if(trigger==='SECURITY' && !printed.test(sourceText)) continue;
      const blob=JSON.stringify(m.actions||[]);
      if(/CANT_ATTACK/.test(blob) && !/CANT_BLOCK/.test(blob)) issues.push(`${c.id} mechanic ${idx} encodes printed can't attack/block without CANT_BLOCK.`);
      if(!/unsuspend/i.test(text) && /CANT_UNSUSPEND/.test(blob) && /CANT_ATTACK/.test(blob)) issues.push(`${c.id} should not approximate can't block with CANT_UNSUSPEND.`);
    }
  }
  try{
    const g=mkGame(['BT5-103','BT1-010'], ['BT1-010','BT1-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.counterTiming={isActive:true,defenderId:'p2',step:'BLOCKER',pendingAttack:{attackerId:'p1',attackerInstanceId:'atk'}};
    const attacker=addBattle(g,'p1','BT1-010',{tag:'atk',instanceId:'atk',stack:[]});
    const blocked=addBattle(g,'p2','BT1-010',{tag:'blocked',stack:[],isSuspended:false,turnEffects:[{type:'GRANT_KEYWORD',keyword:'Blocker'},{type:'CANT_BLOCK'}]});
    const legal=addBattle(g,'p2','BT1-010',{tag:'legal',stack:[],isSuspended:false,turnEffects:[{type:'GRANT_KEYWORD',keyword:'Blocker'}]});
    const blockers=g.getLegalBlockers('p2').map(c=>c.instanceId);
    if(blockers.includes(blocked.instanceId)) issues.push('getLegalBlockers must exclude Digimon with CANT_BLOCK even if they have <Blocker>.');
    if(!blockers.includes(legal.instanceId)) issues.push('getLegalBlockers should still include normal legal blockers.');
    g.performBlock('p2', blocked.instanceId);
    if(blocked.isSuspended) issues.push('performBlock must reject CANT_BLOCK targets before suspending them.');
  } catch(e){ issues.push('Round22F CANT_BLOCK runtime simulation failed: '+(e.stack||e.message||e)); }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/hasCantBlockRestriction/.test(gs) || !/CANT_BLOCK/.test(gs)) issues.push('game-state should implement CANT_BLOCK and use it during Blocker timing.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/cantAttackOrBlockCantBlockLeak/.test(audit)) issues.push('audit-mechanics should guard printed can\'t attack or block missing CANT_BLOCK.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22F can't-attack-or-block/.test(auto)) issues.push('auto-mechanics should document Round 22F CANT_BLOCK guardrails.');
  return { name:'Round 22F can\'t-attack-or-block CANT_BLOCK guard', issues };
}

