  if(!has('EX3-069',m=>JSON.stringify(m.actions||[]).includes('CANT_DIGIVOLVE') && JSON.stringify(m.actions||[]).includes('evolveToLevel') && JSON.stringify(m.actions||[]).includes('7'))) issues.push('EX3-069 Trial should restrict the played Four Great Dragons Digimon from digivolving to level 7, not all movement/DP state.');
  if(!has('BT13-083',m=>m.trigger==='ALL_TURNS' && JSON.stringify(m.actions||[]).includes('CANT_DIGIVOLVE'))) issues.push('BT13-083 Gizmon: AT should have static this-Digimon CANT_DIGIVOLVE.');
