  if(!has('BT23-085',m=>m.trigger==='ON_PLAY' && JSON.stringify(m.actions||[]).includes('DP_REDUCTION_IMMUNITY') && JSON.stringify(m.actions||[]).includes('sameAsPreviousTarget'))) issues.push('BT23-085 Ryuji should bind DP immunity, Reboot and Blocker to the same chosen Hudie Digimon.');
  if(!has('BT16-093',m=>m.trigger==='MAIN' && JSON.stringify(m.actions||[]).includes('DP_REDUCTION_IMMUNITY') && JSON.stringify(m.actions||[]).includes('digivolvedByThisEffect'))) issues.push('BT16-093 The Sparkle of Fate should grant DP_REDUCTION_IMMUNITY to the Digimon this effect digivolved.');
