function testRound22PCantBeReturnedGuard(){
  const issues=[];
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/CANT_BE_RETURNED/.test(gs)) issues.push('game-state should support CANT_BE_RETURNED as a real return-to-hand/deck restriction.');
  if(!/hasCantBeReturnedProtection/.test(gs)) issues.push('executeBattleAreaMove should consult CANT_BE_RETURNED before moving to hand/deck.');
  const cj=id=>JSON.stringify((byId.get(id)||{}).mechanics||[]);
  const must=['BT19-051','BT12-084','BT13-076','BT23-054','BT18-064','BT11-060','BT17-038','EX8-015','BT23-033','BT24-056','BT22-058','BT10-068','P-215','BT23-044','EX8-043','BT21-074','EX8-070'];
  for(const id of must){
    if(!cj(id).includes('CANT_BE_RETURNED')) issues.push(`${id} should encode printed can't-be-returned text with CANT_BE_RETURNED.`);
  }
  for(const id of must){
    const blob=cj(id);
    if(/PREVENT_LEAVE_PLAY/.test(blob)) issues.push(`${id} should not use broad PREVENT_LEAVE_PLAY for simple return protection.`);
  }
  if(/"type":"STUN"|"type": "STUN"/.test(cj('BT17-038')) || /"type":"STUN"|"type": "STUN"/.test(cj('EX8-070'))) issues.push('Return protection must not be approximated with STUN.');
  if(!/"count":"all"/.test(cj('BT10-068')) || !/DP_REDUCTION_IMMUNITY/.test(cj('BT10-068'))) issues.push('BT10-068 should apply all-your-Digimon +DP/return/DP-reduction protection to all Digimon.');
  try{
    const g=mkGame(['BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[];
    const protectedCard=addBattle(g,'p1','BT1-010',{tag:'returnlock'});
    protectedCard.turnEffects=[{type:'CANT_BE_RETURNED', toHand:true, toDeck:true, byEffect:true, opponentEffectsOnly:true, duration:'END_OF_TURN'}];
    if(g.executeBattleAreaMove('p1', protectedCard.instanceId, 'hand', {byEffect:true, sourcePlayerId:'p2'})!==false) issues.push('CANT_BE_RETURNED should block opponent-effect bounce to hand.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===protectedCard.instanceId)) issues.push('Blocked bounce should leave the protected Digimon in battle area.');
    if(g.executeBattleAreaMove('p1', protectedCard.instanceId, 'deck', {byEffect:true, sourcePlayerId:'p2'})!==false) issues.push('CANT_BE_RETURNED should block opponent-effect return to deck.');
    if(g.executeBattleAreaMove('p1', protectedCard.instanceId, 'security', {byEffect:true, sourcePlayerId:'p2'})!==true) issues.push('CANT_BE_RETURNED must not block send-to-security effects.');
    const ownProtected=addBattle(g,'p1','BT1-010',{tag:'ownreturn'});
    ownProtected.turnEffects=[{type:'CANT_BE_RETURNED', toHand:true, toDeck:true, byEffect:true, opponentEffectsOnly:true, duration:'END_OF_TURN'}];
    if(g.executeBattleAreaMove('p1', ownProtected.instanceId, 'hand', {byEffect:true, sourcePlayerId:'p1'})!==true) issues.push('opponentEffectsOnly CANT_BE_RETURNED must not block the owner’s own return effect.');
  }catch(e){ issues.push(`runtime CANT_BE_RETURNED smoke failed: ${e.message}`); }
  return { name:'Round 22P cannot-be-returned hand/deck guard', issues };
}

