  const yuuya=blob('BT11-093');
  if(!/UNAFFECTED_BY_OPPONENT_EFFECTS/.test(yuuya) || /GRANT_KEYWORD[\s\S]{0,200}option/.test(yuuya)) issues.push('BT11-093 Yuuya should use source-scoped UNAFFECTED_BY_OPPONENT_EFFECTS for opponent Option-card immunity, not GRANT_KEYWORD.');
  if(!/sameAsPreviousTarget/.test(yuuya) || !/Option cards/i.test(yuuya)) issues.push('BT11-093 Yuuya option immunity should bind to the same Digimon that received +2000 DP and preserve Option-card scope text.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
