  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/opponentEffectImmunityEncodingLeak/.test(audit) || !/auditOpponentEffectImmunityEncodingLeak/.test(audit)) issues.push('audit should include opponentEffectImmunityEncodingLeak guard.');
