    if(g.isActionBlockedByImmunity('p1', target, 'DELETE_DIGIMON', {byEffect:true, sourcePlayerId:'p2', sourceCard:clone('BT2-010','opp-digimon')})) issues.push('Option-scoped immunity must not block opponent Digimon effects.');
    target.turnEffects=[{type:'UNAFFECTED_BY_OPPONENT_EFFECTS', text:"isn't affected by your opponent's effects", duration:'END_OF_TURN', sourcePlayerId:'p1'}];
    if(!g.isActionBlockedByImmunity('p1', target, 'DELETE_DIGIMON', {byEffect:true, sourcePlayerId:'p2', sourceCard:clone('BT2-010','opp-digimon2')})) issues.push('General opponent-effect immunity should block opponent Digimon effects.');
