  if(!/REQUEST_ATTACK_DIGIMON/.test(blob('BT12-056')) || !/"self":true/.test(blob('BT12-056'))) issues.push('BT12-056 GranKuwagamon should use self REQUEST_ATTACK_DIGIMON.');
  if(!/REQUEST_ATTACK_PLAYER/.test(blob('BT21-072')) || !/withoutSuspending/.test(blob('BT21-072'))) issues.push('BT21-072 should use REQUEST_ATTACK_PLAYER with withoutSuspending:true.');
  if(!/"keyword":"Rush"/.test(blob('BT25-057')) || !/Security A\. \+1/.test(blob('BT25-057')) || /"keyword":"Can Attack"/.test(blob('BT25-057'))) issues.push('BT25-057 Final Judgment option side should grant Rush + Security A. +1, not fake Can Attack.');
