  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/REQUEST_ATTACK_DIGIMON/.test(audit) || !/attack active/.test(audit.toLowerCase())) issues.push('audit should reject fake attack keywords and allow REQUEST_ATTACK_DIGIMON.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
