    if(g.cardMatchesTarget(fieldDual,{owner:'own',cardType:'option',color:'Purple'})) issues.push('Field DUAL must not match Option-side color/Option references.');
    if(!g.cardMatchesTarget(fieldDual,{owner:'own',cardType:'digimon or option'})) issues.push('Field DUAL should still satisfy Digimon-or-Option selectors through its Digimon status.');
    const handDual=clone('BT25-085','22bf-hand-dual');
