function testRound22BDOptionIgnoreColorConditionGuard(){
  const issues=[];
  const card=id=>byId.get(id)||{};
  const singleMainIds=['BT9-110','BT8-110','BT9-098','BT23-091','BT9-109'];
  for(const id of singleMainIds){
    const c=card(id);
    const mains=(c.mechanics||[]).filter(m=>String(m.trigger||'').toUpperCase()==='MAIN');
    if(mains.length===1 && mains[0].condition) issues.push(`${id} ${c.name}: pre-[Main] ignore-color clause still gates the [Main] effect.`);
  }

  try{
    const g=mkGame(['BT9-110','BT2-010','BT20-086'], ['BT2-010','BT1-015']);
    g.zones.p1.hand=[]; g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.zones.p1.trash=[]; g.zones.p2.trash=[];
    g.turnPlayer='p1'; g.phase='MAIN'; g.memory=10; g.actionLogs=[];
    const blackTamer=addBattle(g,'p1','BT22-095',{tag:'22bd-white-tamer'});
    const target=addBattle(g,'p2','BT2-010',{tag:'22bd-target'});
    const xProgram=clone('BT9-110','22bd-xprogram');
    g.zones.p1.hand.push(xProgram);
    if(!g.canUseOptionCard('p1', xProgram, {from:'hand'})) issues.push('X Program should be usable through normal black color requirement even without Dex/DeathX in play.');
    g.playOrEvolve('p1', xProgram, 'hand', null, false);
    autoResolve(g);
    if((g.zones.p2.battleArea||[]).some(c=>c.instanceId===target.instanceId)) issues.push('X Program [Main] should resolve and delete a non-X-Antibody Digimon even when Dex/DeathX exists only as an ignore-color clause.');
    if(!(g.zones.p1.trash||[]).some(c=>c.id==='BT9-110')) issues.push('Used X Program should go to trash after resolving as an Option.');
    issues.push(...checkInvariants(g,'Round22BD option ignore-color runtime'));
  }catch(e){ issues.push('Round22BD runtime failed: '+(e.stack||e.message)); }

  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/optionIgnoreColorConditionLeak/.test(audit)) issues.push('audit should guard pre-[Main] ignore-color condition leaks.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22BD Option ignore-color/.test(auto)) issues.push('auto-mechanics should document Round 22BD Option ignore-color guardrails.');
  return {name:'Round 22BD Option ignore-color condition guard', issues};
}

function testRound22BCAttackTimingSimultaneousPriorityGuard(){
  const issues=[];
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/ATTACK_DECLARATION_TIMING/.test(gs) || !/EFFECT_ATTACK_TIMING/.test(gs)) issues.push('Attack timing producers should be collected inside explicit trigger batches for normal and effect-created attacks.');
  if(!/withTriggerBatch\('ATTACK_DECLARATION_TIMING'[\s\S]{0,2600}\{\s*resolve:\s*false\s*\}/.test(gs)) issues.push('Normal declared attacks must batch attack-timing triggers with resolve:false until all attack/Opponent Attack listeners are collected.');
  if(!/withTriggerBatch\('EFFECT_ATTACK_TIMING'[\s\S]{0,900}\{\s*resolve:\s*false\s*\}/.test(gs)) issues.push('Effect-created attacks must batch attack-timing triggers with resolve:false.');

  function setupPriorityGame(){
    const g=mkGame(['BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.pendingTarget=null; g.pendingChoice=null; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const attacker=addBattle(g,'p1','BT1-010',{tag:'22bc-attacker',playedThisTurn:false,isSuspended:false});
    attacker.mechanics=[{trigger:'WHEN_ATTACKING',actions:[{type:'DRAW',amount:1}]}];
    const defenderListener=addBattle(g,'p2','BT2-010',{tag:'22bc-defender-listener',playedThisTurn:false,isSuspended:false});
    defenderListener.mechanics=[{trigger:'OPPONENT_ATTACKED',actions:[{type:'DELETE_DIGIMON',target:{owner:'opponent',cardType:'digimon',count:1}}]}];
    return {g, attacker, defenderListener};
  }

  try{
    const {g, attacker}=setupPriorityGame();
    const beforeHand=g.zones.p1.hand.length;
    g.declareAttack('p1', attacker.instanceId, 'player', null);
    if(g.zones.p1.hand.length !== beforeHand + 1) issues.push('Normal attack: turn-player [When Attacking] DRAW should resolve before opponent OPPONENT_ATTACKED target window opens.');
    if(!g.pendingTarget || g.pendingTarget.playerId !== 'p2' || g.pendingTarget.actionType !== 'DELETE_DIGIMON') issues.push('Normal attack: opponent attack-listener target window should open only after turn-player trigger resolves.');
    if(!(g.effectQueue||[]).some(e=>e.effectText==='shift_to_counter')) issues.push('Normal attack: batched attack timing must still queue the shift_to_counter handoff.');
    autoResolve(g);
    if((g.zones.p1.battleArea||[]).some(c=>c.instanceId===attacker.instanceId)) issues.push('Normal attack: opponent attack-listener deletion should still resolve after the turn-player trigger.');
    issues.push(...checkInvariants(g,'Round22BC normal attack priority'));
  }catch(e){ issues.push('Round22BC normal attack priority runtime failed: '+(e.stack||e.message)); }

  try{
    const {g, attacker}=setupPriorityGame();
    const beforeHand=g.zones.p1.hand.length;
    const ok=g.startAttackWithoutSuspending('p1', attacker, 'player', null, 'Round22BC effect attack');
    if(ok === false) issues.push('Effect-created attack should start.');
    if(g.zones.p1.hand.length !== beforeHand + 1) issues.push('Effect-created attack: turn-player [When Attacking] DRAW should resolve before opponent OPPONENT_ATTACKED target window opens.');
    if(!g.pendingTarget || g.pendingTarget.playerId !== 'p2' || g.pendingTarget.actionType !== 'DELETE_DIGIMON') issues.push('Effect-created attack: opponent attack-listener target window should open only after turn-player trigger resolves.');
    if(!(g.effectQueue||[]).some(e=>e.effectText==='shift_to_counter')) issues.push('Effect-created attack: batched attack timing must still queue the shift_to_counter handoff.');
    autoResolve(g);
    if((g.zones.p1.battleArea||[]).some(c=>c.instanceId===attacker.instanceId)) issues.push('Effect-created attack: opponent attack-listener deletion should still resolve after the turn-player trigger.');
    issues.push(...checkInvariants(g,'Round22BC effect attack priority'));
  }catch(e){ issues.push('Round22BC effect attack priority runtime failed: '+(e.stack||e.message)); }

  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/attackTimingSimultaneousPriorityLeak/.test(audit)) issues.push('audit should guard attack timing simultaneous-priority regressions.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22BC attack timing simultaneous-priority/.test(auto)) issues.push('auto-mechanics should document Round 22BC attack timing guardrails.');
  return {name:'Round 22BC attack-timing simultaneous priority guard', issues};
}




function testRound22BLReturnSourceToHandCostAtomicityGuard(){
  const issues=[];
  const encodedCases={
    'BT11-073':['WHEN_DIGIVOLVING'],
    'BT10-067':['WHEN_DIGIVOLVING'],
    'BT5-087':['WHEN_ATTACKING']
  };
  for(const [id,triggers] of Object.entries(encodedCases)){
    const c=byId.get(id)||{};
    for(const trigger of triggers){
      const mech=(c.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()===trigger);
      if(!mech){ issues.push(`${id} missing ${trigger} mechanic.`); continue; }
      if(String(mech.cost?.type||'').toUpperCase()!=='RETURN_SOURCE_TO_HAND') issues.push(`${id} ${trigger} should use RETURN_SOURCE_TO_HAND as mechanic.cost.`);
      const first=String((mech.actions||[])[0]?.type||'').toUpperCase();
      if(first==='RETURN_SOURCE_TO_HAND' || first==='RETURN_TO_DECK') issues.push(`${id} ${trigger} still has source return as a normal first action.`);
    }
  }
  const zwart=byId.get('BT5-087')||{};
  const zwartAtk=(zwart.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='WHEN_ATTACKING')||{};
  const zwartActions=zwartAtk.actions||[];
  if(zwartActions.some(a=>String(a.type||'').toUpperCase()==='BOUNCE_SAME_LEVEL_AS_RETURNED_SOURCE')) issues.push('BT5-087 must not use same-level bounce placeholder for its printed delete payoff.');
  const zwartDelete=zwartActions.find(a=>String(a.type||'').toUpperCase()==='DELETE_DIGIMON');
  if(!zwartDelete || Number(zwartDelete.target?.maxCost)!==12 || zwartDelete.target?.isUnsuspended!==true) issues.push('BT5-087 payoff should delete an opponent unsuspended Digimon with play cost 12 or less.');

  try{
    const g=mkGame(['BT10-067','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const crit=addBattle(g,'p1','BT10-067',{tag:'22bl-critical-fail', stack:[]});
    const victim=addBattle(g,'p2','BT1-010',{tag:'22bl-victim-fail'});
    g.triggerEffect('p1', crit, 'WHEN_DIGIVOLVING');
    autoResolve(g);
    if(!(g.zones.p2.battleArea||[]).some(c=>c.instanceId===victim.instanceId)) issues.push('BT10-067 should not delete anything when RETURN_SOURCE_TO_HAND cost cannot be paid.');
    issues.push(...checkInvariants(g,'Round22BL Critical Arm failed source-return cost'));
  }catch(e){ issues.push('Round22BL Critical Arm failed-cost runtime failed: '+(e.stack||e.message)); }

  try{
    const g=mkGame(['BT10-067','BT11-073','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const source=clone('BT11-073','22bl-justimon-source');
    const crit=addBattle(g,'p1','BT10-067',{tag:'22bl-critical-ok', stack:[source]});
    const victim=addBattle(g,'p2','BT1-010',{tag:'22bl-victim-ok'});
    g.triggerEffect('p1', crit, 'WHEN_DIGIVOLVING');
    autoResolve(g);
    if((crit.stack||[]).some(c=>c.instanceId===source.instanceId)) issues.push('BT10-067 paid cost should remove the Justimon source from the stack.');
    if(!(g.zones.p1.hand||[]).some(c=>c.instanceId===source.instanceId)) issues.push('BT10-067 paid cost should return the Justimon source to hand.');
    if((g.zones.p2.battleArea||[]).some(c=>c.instanceId===victim.instanceId)) issues.push('BT10-067 paid cost should allow the play-cost-9-or-less delete payoff to resolve.');
    issues.push(...checkInvariants(g,'Round22BL Critical Arm paid source-return cost'));
  }catch(e){ issues.push('Round22BL Critical Arm paid-cost runtime failed: '+(e.stack||e.message)); }

  try{
    const g=mkGame(['BT5-087','BT10-040','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const source=clone('BT10-040','22bl-lv6-source');
    const zwartCard=addBattle(g,'p1','BT5-087',{tag:'22bl-zwart', stack:[source]});
    const victim=addBattle(g,'p2','BT1-010',{tag:'22bl-unsuspended-victim', isSuspended:false});
    const suspended=addBattle(g,'p2','BT2-010',{tag:'22bl-suspended-nontarget', isSuspended:true});
    g.triggerEffect('p1', zwartCard, 'WHEN_ATTACKING');
    autoResolve(g);
    if((zwartCard.stack||[]).some(c=>c.instanceId===source.instanceId)) issues.push('BT5-087 should remove the Lv.6 source when paying the cost.');
    if(!(g.zones.p1.hand||[]).some(c=>c.instanceId===source.instanceId)) issues.push('BT5-087 should return the Lv.6 source to hand.');
    if((g.zones.p2.battleArea||[]).some(c=>c.instanceId===victim.instanceId)) issues.push('BT5-087 should delete the unsuspended play-cost-12-or-less target after cost payment.');
    if(!(g.zones.p2.battleArea||[]).some(c=>c.instanceId===suspended.instanceId)) issues.push('BT5-087 should not delete a suspended Digimon for an unsuspended-only payoff.');
    issues.push(...checkInvariants(g,'Round22BL Omnimon Zwart source-return cost'));
  }catch(e){ issues.push('Round22BL Omnimon Zwart runtime failed: '+(e.stack||e.message)); }

  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/returnSourceToHandCostAtomicityLeak/.test(audit) || !/BT5-087/.test(audit)) issues.push('audit should guard Round 22BL return-source-to-hand cost regressions.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22BL source-return-to-hand/.test(auto)) issues.push('auto-mechanics should document Round 22BL guardrails.');
  return {name:'Round 22BL source-return-to-hand cost atomicity guard', issues};
}


function testRound22BKRemainingSourcePlacementCostPayoffGuard(){
  const issues=[];
  const card=id=>byId.get(id)||{};
  const encodedCases={
    'BT17-059':['WHEN_DIGIVOLVING'],
    'BT22-020':['WHEN_ATTACKING'],
    'BT17-021':['ON_PLAY'],
    'BT24-027':['ON_PLAY','WHEN_DIGIVOLVING'],
    'BT25-082':['WHEN_ATTACKING']
  };
  for(const [id,triggers] of Object.entries(encodedCases)){
    const c=card(id);
    for(const trigger of triggers){
      const mech=(c.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()===trigger);
      if(!mech) { issues.push(`${id} missing ${trigger} mechanic.`); continue; }
      if(String(mech.cost?.type||'').toUpperCase()!=='PLACE_SOURCE') issues.push(`${id} ${trigger} should gate its payoff behind mechanic.cost PLACE_SOURCE.`);
      if((mech.actions||[])[0]?.type==='PLACE_SOURCE') issues.push(`${id} ${trigger} still has PLACE_SOURCE as a normal first action.`);
    }
  }
  const black=card('BT25-082');
  const blackAtk=(black.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='WHEN_ATTACKING');
  if(!blackAtk || blackAtk.isInherited!==true) issues.push('BT25-082 source When Attacking must remain inherited after cost conversion.');
  const breaclaw=card('BT10-094');
  const breaclawMain=(breaclaw.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='MAIN')||{};
  const breaclawActions=breaclawMain.actions||[];
  const breaclawDraw=breaclawActions.find(a=>String(a.type||'').toUpperCase()==='DRAW');
  if(String(breaclawActions[0]?.type||'').toUpperCase()!=='DP_MOD') issues.push('BT10-094 should keep its independent first DP_MOD action.');
  if(!breaclawDraw || String(breaclawDraw.cost?.type||'').toUpperCase()!=='PLACE_SOURCE') issues.push('BT10-094 Draw payoff should carry an action-level PLACE_SOURCE cost.');
  if(breaclawActions.some(a=>String(a.type||'').toUpperCase()==='PLACE_SOURCE')) issues.push('BT10-094 must not leave PLACE_SOURCE as a normal action before Draw.');

  try{
    const g=mkGame(['BT17-059','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const dia=addBattle(g,'p1','BT17-059',{tag:'22bk-dia-fail'});
    g.triggerEffect('p1', dia, 'WHEN_DIGIVOLVING');
    autoResolve(g);
    const tokens=(g.zones.p1.battleArea||[]).filter(c=>/Diaboromon Token/i.test(c.name||''));
    if(tokens.length!==0) issues.push('BT17-059 should not play Diaboromon Tokens when the Doomsday Clock PLACE_SOURCE cost cannot be paid.');
    issues.push(...checkInvariants(g,'Round22BK Diaboromon failed source-cost'));
  }catch(e){ issues.push('Round22BK Diaboromon failed-cost runtime failed: '+(e.stack||e.message)); }

  try{
    const g=mkGame(['BT17-059','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const dia=addBattle(g,'p1','BT17-059',{tag:'22bk-dia-ok'});
    const doom=clone('BT17-091','22bk-doom');
    doom.id='BT17-091'; doom.name='Doomsday Clock'; doom.type='option'; doom.cardType='option'; doom.traitTokens=[]; doom.colors=['White'];
    g.zones.p1.hand.push(doom);
    g.triggerEffect('p1', dia, 'WHEN_DIGIVOLVING');
    autoResolve(g);
    if(!(dia.stack||[]).some(c=>c.instanceId===doom.instanceId)) issues.push('BT17-059 paid cost should place Doomsday Clock under Diaboromon.');
    const tokens=(g.zones.p1.battleArea||[]).filter(c=>/Diaboromon Token/i.test(c.name||''));
    if(tokens.length!==2) issues.push(`BT17-059 paid cost should play exactly 2 Diaboromon Tokens, got ${tokens.length}.`);
    issues.push(...checkInvariants(g,'Round22BK Diaboromon paid source-cost'));
  }catch(e){ issues.push('Round22BK Diaboromon paid-cost runtime failed: '+(e.stack||e.message)); }

  try{
    const g=mkGame(['BT10-094','BT1-010'], ['BT2-010','BT3-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.deck=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.actionLogs=[]; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const target=addBattle(g,'p1','BT1-010',{tag:'22bk-breaclaw-target'});
    const option=clone('BT10-094','22bk-breaclaw');
    const beforeHand=g.zones.p1.hand.length;
    enqueue(g,'p1',option,breaclawActions,'Breaclaw Round22BK');
    autoResolve(g);
    if(!hasTurnEffect(target,'DP_MOD',e=>Number(e.value||e.amount||0)===2000)) issues.push('BT10-094 should still apply the independent +2000 DP before the then-by cost.');
    if(g.zones.p1.hand.length!==beforeHand) issues.push('BT10-094 should not Draw 1 when the Gammamon PLACE_SOURCE cost cannot be paid.');
    issues.push(...checkInvariants(g,'Round22BK Breaclaw action-level cost'));
  }catch(e){ issues.push('Round22BK Breaclaw action-cost runtime failed: '+(e.stack||e.message)); }

  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/Round 22BK/.test(audit) || !/BT10-094/.test(audit)) issues.push('audit should guard Round 22BK source-placement payoff regressions.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22BK remaining source-placement/.test(auto)) issues.push('auto-mechanics should document Round 22BK guardrails.');
  return {name:'Round 22BK remaining source-placement payoff guard', issues};
}

