    const main = cards.filter(c => Number(c.level) !== 2 && !String(c.type||'').toLowerCase().includes('egg') && !excluded.has(c.id)).slice(0,50).map(c => ({...c}));
    const eggs = cards.filter(c => Number(c.level) === 2 || String(c.type||'').toLowerCase().includes('egg')).slice(0,4).map(c => ({...c}));
    const deck = [...main, ...eggs];
