    const rejected = { ok:false, error:'illegal DUAL normal digivolve', actionTelemetry:{ type:'play', actionPhase:'MAIN', endSnapshotPhase:'HATCH', actionApplied:false } };
    const applied = { ok:true, actionTelemetry:{ type:'declareAttack', actionPhase:'MAIN', endSnapshotPhase:'MAIN', actionApplied:true } };
    const rejectedEntry = server.getOfficialActionReportEntry(rejected, 'Main: digivolve LadyDevimon into BeelStarmon');
    if(rejectedEntry.includeInSuccessfulDecisions) issues.push('Rejected/no-op action must not be included in successful decision list.');
