    const decisions = server.buildOfficialSuccessfulDecisions([{decision:'bad DUAL attempt', result:rejected},{decision:'Attack: BeelStarmon attacks player', result:applied}]);
    if(decisions.includes('bad DUAL attempt')) issues.push('buildOfficialSuccessfulDecisions should filter out actionApplied:false/ok:false entries.');
    if(!decisions.includes('Attack: BeelStarmon attacks player')) issues.push('buildOfficialSuccessfulDecisions should retain true applied actions.');

    const state = server.formatOfficialTurnStateForReport({ memory:3, nextPlayer:'p2', phase:'HATCH', actionTelemetry:{ actionPhase:'MAIN', endSnapshotPhase:'HATCH', afterPhase:'HATCH' } });
