    const g=mkGame(['BT25-085','BT11-083','P-194'], ['BT2-010']);
    g.zones.p1.hand=[]; g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.pendingReveal=null; g.actionLogs=[];
    g.turnPlayer='p1'; g.turnCount=1; g.phase='MAIN'; g.memory=0;
    const target=addBattle(g,'p1','BT11-083',{tag:'22cw-target'});
    const dual=addHand(g,'p1','BT25-085');
    const before={ hand:g.zones.p1.hand.length, battle:g.zones.p1.battleArea.length, memory:g.memory };
    const room={ game:g, players:{ p1:{id:'socket-p1'}, p2:{id:'socket-p2'} }, match:{ wins:{p1:0,p2:0}, completedGames:[], gameNumber:1, bestOf:3 } };
    const result=executeGuardedRoomAction(room,'socket-p1',{type:'play', card:dual, zone:'battle', targetInstanceId:target.instanceId});
