function testRound22CTSearchSecurityThenRecoveryShuffleOrderGuard(){
  const issues=[];
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  const searchSecurityBody=(gs.match(/searchSecurityToHand\(playerId, action = \{\}\) \{[\s\S]*?\n    \}/)||[])[0] || '';
  if(!/Round 22CT/.test(searchSecurityBody)) issues.push('game-state.js should document Round 22CT search-security/recovery/shuffle order.');
  if(!/thenRecovery[\s\S]{0,180}recoveryDeck[\s\S]{0,220}shuffle\(zone\.security\)/.test(searchSecurityBody)) {
    issues.push('SEARCH_SECURITY_TO_HAND with thenRecovery must recover before shuffling security so the recovered card is included in the final shuffle.');
  }
  try{
    const angewomon=byId.get('BT11-042');
    if(!angewomon) issues.push('BT11-042 Angewomon must exist in cards.json.');
    else {
      const mech=(angewomon.mechanics||[]).find(m => String(m.trigger||'').toUpperCase()==='WHEN_DIGIVOLVING' && (m.actions||[]).some(a => a.type==='SEARCH_SECURITY_TO_HAND'));
      const action=(mech?.actions||[]).find(a => a.type==='SEARCH_SECURITY_TO_HAND') || null;
      if(!action) issues.push('BT11-042 Angewomon must use SEARCH_SECURITY_TO_HAND for its When Digivolving security search.');
      else {
        if(action.thenRecovery !== true) issues.push('BT11-042 SEARCH_SECURITY_TO_HAND must carry thenRecovery:true.');
        if(action.shuffle !== true) issues.push('BT11-042 SEARCH_SECURITY_TO_HAND must carry shuffle:true.');
      }
    }
    const g=mkGame(['P-194'], ['BT2-010']);
    g.zones.p1.hand=[]; g.zones.p1.battleArea=[]; g.zones.p1.trash=[]; g.zones.p1.revealed=[];
    const stayBottom=clone('BT1-010','22ct-security-bottom');
    const searched=clone('BT11-042','22ct-security-search');
    const stayTop=clone('BT2-010','22ct-security-top');
    const deckFiller=clone('BT1-010','22ct-deck-filler');
    const recovered=clone('BT2-010','22ct-recovered');
    g.zones.p1.security=[stayBottom, searched, stayTop];
    g.zones.p1.deck=[deckFiller, recovered];
    let shuffledSnapshot=[];
    g.shuffle = (arr) => {
      shuffledSnapshot = (arr || []).map(c => c.instanceId || c.id);
      arr.reverse();
    };
    const ok=g.searchSecurityToHand('p1', {
      target: { owner:'own', cardType:'card', traitAny:['Angel','Archangel','Fallen Angel'], count:1 },
      shuffle: true,
      thenRecovery: true,
      recoveryAmount: 1
    });
    if(!ok) issues.push('SEARCH_SECURITY_TO_HAND should find and add BT11-042 from security.');
    if(!g.zones.p1.hand.some(c => c.instanceId === searched.instanceId)) issues.push('searched security card should move to hand.');
    if(!g.zones.p1.security.some(c => c.instanceId === recovered.instanceId)) issues.push('thenRecovery should place the deck top card into security after a successful add.');
    if(!shuffledSnapshot.includes(recovered.instanceId)) issues.push('Round 22CT regression: recovered card was not present in the array passed to shuffle.');
    if(g.zones.p1.security.length !== 3) issues.push(`security count should stay 3 after add-one-to-hand plus Recovery +1, got ${g.zones.p1.security.length}.`);
    if(g.zones.p1.deck.some(c => c.instanceId === recovered.instanceId)) issues.push('recovered card should be removed from deck.');
  }catch(e){ issues.push('Round 22CT runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CT SEARCH_SECURITY_TO_HAND recovery-before-shuffle guard', issues};
}

function testRound22CSMagnadramonXEndAttackSecurityToHandCostGuard(){
  const issues=[];
  const card=byId.get('BT9-043');
  if(!card){ issues.push('BT9-043 Magnadramon (X Antibody) must exist in cards.json.'); return {name:'Round 22CS BT9-043 Magnadramon X End-of-Attack security-to-hand cost guard', issues}; }
  const text=String(card.mainEffect||'').replace(/\u00a0/g,' ');
  if(!/\[End of Attack\]/i.test(text) || !/add the top card of your security stack to your hand/i.test(text) || !/unsuspend this Digimon/i.test(text)) issues.push('BT9-043 should still print End-of-Attack add-top-security-to-hand self-unsuspend text.');
  const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
  const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
    && m.isInherited!==true
    && m.isOncePerTurn===true
    && String(m.cost?.type||'').toUpperCase()==='ADD_SECURITY_TO_HAND'
    && Number(m.cost?.amount||0)===1
    && /top|security_top/i.test(String(m.cost?.position||m.cost?.from||''))
    && (m.actions||[]).some(a=>String(a.type||'').toUpperCase()==='UNSUSPEND' && a.target?.self===true));
  if(!end) issues.push('BT9-043 End-of-Attack effect must be non-inherited END_OF_ATTACK OPT with ADD_SECURITY_TO_HAND top-security cost into self UNSUSPEND.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /ADD_SECURITY_TO_HAND|UNSUSPEND|security/i.test(JSON.stringify(m)))) issues.push('BT9-043 End-of-Attack self-unsuspend must not be END_OF_TURN.');
  const wd=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='WHEN_DIGIVOLVING');
  if(!wd || !/Magnadramon|X Antibody/.test(JSON.stringify(wd.condition||{}))) issues.push('BT9-043 When Digivolving DP reduction must stay gated by Magnadramon/X Antibody source condition.');
  if(wd && /UNSUSPEND/.test(JSON.stringify(wd.actions||[]))) issues.push('BT9-043 When Digivolving must not contain the End-of-Attack UNSUSPEND payoff.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/magnadramonBt9043EndAttackSecurityToHandCostLeak/.test(audit) || !/BT9-043/.test(audit)) issues.push('audit-mechanics should guard BT9-043 End-of-Attack security-to-hand cost regressions.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CS BT9-043 Magnadramon \(X Antibody\) guardrails/.test(auto)) issues.push('auto-mechanics should document Round 22CS BT9-043 guardrails.');

  try{
    let g=mkGame(['BT9-043','BT9-109','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.security=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[];
    const magna=addBattle(g,'p1','BT9-043',{tag:'22cs-magna',isSuspended:true});
    const bottom=clone('BT1-010','22cs-sec-bottom');
    const top=clone('BT2-010','22cs-sec-top');
    g.zones.p1.security=[bottom, top];
    g.triggerEffect('p1', magna, 'END_OF_TURN'); autoResolve(g);
    if(!magna.isSuspended) issues.push('BT9-043 must not unsuspend at END_OF_TURN.');
    if(g.zones.p1.security.length!==2 || g.zones.p1.hand.length!==0) issues.push('BT9-043 must not add security to hand at END_OF_TURN.');
    g.triggerEffect('p1', magna, 'END_OF_ATTACK'); autoResolve(g);
    if(magna.isSuspended) issues.push('BT9-043 should unsuspend this Digimon at END_OF_ATTACK after paying top-security-to-hand cost.');
    if(!g.zones.p1.hand.some(c=>c.instanceId===top.instanceId)) issues.push('BT9-043 cost should add the top security card to hand.');
    if(g.zones.p1.security.some(c=>c.instanceId===top.instanceId) || !g.zones.p1.security.some(c=>c.instanceId===bottom.instanceId)) issues.push('BT9-043 should remove only the top security card as cost.');

    const g2=mkGame(['BT9-043','BT1-010'], ['BT2-010']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.security=[]; g2.zones.p1.hand=[];
    const noSec=addBattle(g2,'p1','BT9-043',{tag:'22cs-no-sec',isSuspended:true});
    g2.triggerEffect('p1', noSec, 'END_OF_ATTACK'); autoResolve(g2);
    if(!noSec.isSuspended) issues.push('BT9-043 must not unsuspend if there is no security card to pay the cost.');
    if(g2.zones.p1.hand.length!==0) issues.push('BT9-043 no-security case must not add phantom cards to hand.');

    const g3=mkGame(['BT9-043','BT9-109','BT1-010'], ['BT2-010']);
    g3.zones.p1.battleArea=[]; g3.zones.p2.battleArea=[]; g3.zones.p1.security=[clone('BT1-010','22cs-s1'), clone('BT1-010','22cs-s2'), clone('BT1-010','22cs-s3')];
    const wdMagna=addBattle(g3,'p1','BT9-043',{tag:'22cs-wd-magna',isSuspended:true});
    wdMagna.stack=[clone('BT9-109','22cs-x-source')];
    const opp=addBattle(g3,'p2','BT2-010',{tag:'22cs-opp-dp',level:3});
    g3.triggerEffect('p1', wdMagna, 'WHEN_DIGIVOLVING'); autoResolve(g3);
    if(!wdMagna.isSuspended) issues.push('BT9-043 When Digivolving must not unsuspend this Digimon.');
    if(!hasTurnEffect(opp,'DP_MOD',e=>Number(e.value)===-3000)) issues.push('BT9-043 When Digivolving DP reduction should scale from own security count when source condition is met.');
  }catch(e){ issues.push('Round22CS runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CS BT9-043 Magnadramon X End-of-Attack security-to-hand cost guard', issues};
}

function testRound22CRGlowingDawnInheritedEndAttackTamerSourceCostGuard(){
  const issues=[];
  const ids=['ST23-08','ST23-04','BT25-041'];
  for(const id of ids){
    const card=byId.get(id);
    const blob=JSON.stringify(card?.mechanics || []);
    if(!card) { issues.push(`${id} must exist in cards.json.`); continue; }
    if(!/END_OF_ATTACK/.test(blob) || !/"isInherited"\s*:\s*true/.test(blob) || !/TRASH_BOTTOM_TAMER_SOURCE_COST/.test(blob) || !/Glowing Dawn/.test(blob) || !/UNSUSPEND/.test(blob) || !/"self"\s*:\s*true/.test(blob)) {
      issues.push(`${id} must encode inherited END_OF_ATTACK once-per-turn Tamer bottom face-down source cost into self UNSUSPEND.`);
    }
    if((card.mechanics||[]).some(m=>String(m?.trigger||'').toUpperCase()==='END_OF_TURN' && /TRASH_BOTTOM_TAMER_SOURCE_COST|UNSUSPEND/.test(JSON.stringify(m)))) issues.push(`${id} Glowing Dawn inherited source effect must not be END_OF_TURN.`);
  }
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/TRASH_BOTTOM_TAMER_SOURCE_COST/.test(gs) || !/faceDown/.test(gs) || !/isTamerLike\(host\)/.test(gs)) issues.push('game-state should support an atomic TRASH_BOTTOM_TAMER_SOURCE_COST from bottom face-down cards under own Tamers.');
  if(!/explicitTraitFieldTokens/.test(gs) || !/Glowing Dawn/.test(gs)) issues.push('game-state should preserve real trait tokens that are also card names, such as Glowing Dawn.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/glowingDawnInheritedEndAttackTamerSourceCostLeak/.test(audit) || !/ST23-08/.test(audit) || !/BT25-041/.test(audit)) issues.push('audit-mechanics should guard Glowing Dawn inherited End-of-Attack Tamer-source cost regressions.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CR Glowing Dawn inherited End-of-Attack Tamer-source cost guardrails/.test(auto)) issues.push('auto-mechanics should document Round 22CR Glowing Dawn source-effect guardrails.');
  try{
    const g=mkGame(['ST23-08','ST23-04','BT25-041','BT1-085','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.zones.p1.trash=[];
    const host=addBattle(g,'p1','ST23-08',{tag:'22cr-glowing-host',isSuspended:true});
    host.stack=[clone('ST23-04','22cr-source')];
    const tamer=addBattle(g,'p1','BT1-085',{tag:'22cr-tamer'});
    tamer.stack=[{...clone('BT1-010','22cr-facedown-cost'), faceDown:true}];

    g.triggerEffect('p1', host, 'END_OF_TURN'); autoResolve(g);
    if(!host.isSuspended) issues.push('Glowing Dawn source effect must not unsuspend at END_OF_TURN.');
    if((tamer.stack||[]).length !== 1) issues.push('Glowing Dawn source effect must not trash Tamer under-cards at END_OF_TURN.');

    g.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g);
    if(host.isSuspended) issues.push('Glowing Dawn source effect should unsuspend the source host at END_OF_ATTACK after paying the Tamer under-card cost.');
    if((tamer.stack||[]).length !== 0) issues.push('Glowing Dawn source effect should trash exactly the bottom face-down card from under a Tamer as cost.');
    if(!g.zones.p1.trash.some(c=>/22cr-facedown-cost/.test(String(c.instanceId)))) issues.push('Trashed bottom face-down Tamer under-card should move to trash.');

    const g2=mkGame(['BT1-010','ST23-08','BT1-085'], ['BT2-010']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.trash=[];
    const nonGlowing=addBattle(g2,'p1','BT1-010',{tag:'22cr-non-glowing-host',isSuspended:true});
    nonGlowing.stack=[clone('ST23-08','22cr-source-on-nonglowing')];
    const tamer2=addBattle(g2,'p1','BT1-085',{tag:'22cr-tamer2'});
    tamer2.stack=[{...clone('BT2-010','22cr-facedown-cost2'), faceDown:true}];
    g2.triggerEffect('p1', nonGlowing, 'END_OF_ATTACK'); autoResolve(g2);
    if(!nonGlowing.isSuspended) issues.push('Glowing Dawn inherited source effect must not unsuspend a non-Glowing Dawn source host.');
    if((tamer2.stack||[]).length !== 1) issues.push('Failed Glowing Dawn host condition must not spend the Tamer under-card cost.');

    const g3=mkGame(['ST23-08','BT25-041','BT1-085','BT1-010'], ['BT2-010']);
    g3.zones.p1.battleArea=[]; g3.zones.p1.trash=[];
    const host3=addBattle(g3,'p1','ST23-08',{tag:'22cr-host-no-facedown',isSuspended:true});
    host3.stack=[clone('BT25-041','22cr-bt25-source')];
    const tamer3=addBattle(g3,'p1','BT1-085',{tag:'22cr-tamer3'});
    tamer3.stack=[{...clone('BT1-010','22cr-faceup-under-tamer'), faceDown:false}];
    g3.triggerEffect('p1', host3, 'END_OF_ATTACK'); autoResolve(g3);
    if(!host3.isSuspended) issues.push('Glowing Dawn inherited source effect must not unsuspend if no bottom face-down Tamer under-card can be trashed.');
    if((tamer3.stack||[]).length !== 1) issues.push('Face-up/non-face-down Tamer under-card must not be accepted as the bottom face-down cost.');
  }catch(e){ issues.push('Round22CR runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CR Glowing Dawn inherited End-of-Attack Tamer-source cost guard', issues};
}

function testRound22CQMegadramonInheritedEndAttackUnsuspendCostGuard(){
  const issues=[];
  const card=byId.get('EX9-064');
  if(!card){ issues.push('EX9-064 Megadramon must exist in cards.json.'); return {name:'Round 22CQ EX9-064 Megadramon inherited End-of-Attack unsuspend-cost guard', issues}; }
  if(!/\[End of Attack\]/i.test(card.sourceEffect||'') || !/By unsuspending this Digimon/i.test(card.sourceEffect||'')) issues.push('EX9-064 should still have printed inherited [End of Attack] unsuspend-cost text.');
  const endAttack=(card.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited===true && String(m.cost?.type||'').toUpperCase()==='UNSUSPEND_THIS_DIGIMON_COST');
  if(!endAttack) issues.push('EX9-064 inherited effect must use END_OF_ATTACK + isInherited:true + UNSUSPEND_THIS_DIGIMON_COST.');
  if(endAttack && endAttack.isOncePerTurn!==true) issues.push('EX9-064 inherited End-of-Attack effect must be once per turn.');
  const blob=JSON.stringify(endAttack||{});
  if(!/DELETE_DIGIMON/.test(blob) || !/lowest_level/.test(blob) || !/"owner"\s*:\s*"own"/.test(blob)) issues.push('EX9-064 payoff must delete 1 own Digimon with the lowest level.');
  if((card.mechanics||[]).some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /lowest_level|UNSUSPEND/i.test(JSON.stringify(m)))) issues.push('EX9-064 inherited End-of-Attack effect must not remain on END_OF_TURN.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/UNSUSPEND_THIS_DIGIMON_COST/.test(gs) || !/canUnsuspendCard\(playerId, target, \{ reason: 'cost' \}\)/.test(gs)) issues.push('game-state should support UNSUSPEND_THIS_DIGIMON_COST as an atomic cost.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/megadramonEx9064InheritedEndAttackUnsuspendCostLeak/.test(audit)) issues.push('audit-mechanics should guard EX9-064 inherited End-of-Attack unsuspend cost.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CQ EX9-064 Megadramon inherited End-of-Attack unsuspend-cost guardrails/.test(auto)) issues.push('auto-mechanics should document Round 22CQ guardrails.');
  try{
    let g=mkGame(['EX9-064','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[];
    const topMeg=addBattle(g,'p1','EX9-064',{tag:'22cq-top-meg',isSuspended:true});
    const topLow=addBattle(g,'p1','BT1-010',{tag:'22cq-top-low'});
    g.triggerEffect('p1', topMeg, 'END_OF_ATTACK'); autoResolve(g);
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===topMeg.instanceId)) issues.push('Top-level EX9-064 must not fire its lower/source End-of-Attack effect.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===topLow.instanceId)) issues.push('Top-level EX9-064 must not delete own lowest-level Digimon.');

    g=mkGame(['EX1-073','EX9-064','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[];
    const host=addBattle(g,'p1','EX1-073',{tag:'22cq-host',isSuspended:true});
    host.stack=[clone('EX9-064','22cq-src')];
    const low=addBattle(g,'p1','BT1-010',{tag:'22cq-low'});
    g.triggerEffect('p1', host, 'END_OF_TURN'); autoResolve(g);
    if(!host.isSuspended) issues.push('EX9-064 source effect must not unsuspend the host at END_OF_TURN.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===low.instanceId)) issues.push('EX9-064 source effect must not delete at END_OF_TURN.');
    g.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g);
    if(host.isSuspended) issues.push('EX9-064 source effect should pay cost by unsuspending the source host at END_OF_ATTACK.');
    if(g.zones.p1.battleArea.some(c=>c.instanceId===low.instanceId)) issues.push('EX9-064 should delete the own lowest-level Digimon after the unsuspend cost is paid.');
    if(!g.zones.p1.trash.some(c=>c.instanceId===low.instanceId)) issues.push('EX9-064 deleted lowest-level Digimon should move to trash.');

    g=mkGame(['EX1-073','EX9-064','BT1-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[];
    const failHost=addBattle(g,'p1','EX1-073',{tag:'22cq-fail-host',isSuspended:false});
    failHost.stack=[clone('EX9-064','22cq-fail-src')];
    const failLow=addBattle(g,'p1','BT1-010',{tag:'22cq-fail-low'});
    g.triggerEffect('p1', failHost, 'END_OF_ATTACK'); autoResolve(g);
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===failLow.instanceId)) issues.push('EX9-064 must not delete if the host is already unsuspended and the unsuspend cost cannot be paid.');
  }catch(e){ issues.push('Round22CQ runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CQ EX9-064 Megadramon inherited End-of-Attack unsuspend-cost guard', issues};
}

function testRound22CPMetalGreymonInheritedEndAttackTamerSourcePlayGuard(){
  const issues=[];
  const card=byId.get('BT19-025')||{};
  const sourceText=String(card.sourceEffect||'').replace(/\u00a0/g,' ');
  if(!/\[End of Attack\]/i.test(sourceText) || !/level 4 or lower/i.test(sourceText) || !/\[Blue Flare\]/i.test(sourceText) || !/under any of your Tamers/i.test(sourceText)) issues.push('BT19-025 source text should still print inherited End-of-Attack Lv.4-or-lower Blue Flare play from under any of your Tamers.');
  const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
  const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
    && m.isInherited===true
    && m.isOncePerTurn===true
    && (m.actions||[]).some(a=>String(a.type||'').toUpperCase()==='PLAY_FROM_SOURCE'
      && String(a.target?.owner||'').toLowerCase()==='own'
      && String(a.target?.cardType||'').toLowerCase()==='digimon'
      && Number(a.target?.maxLevel)===4
      && /Blue Flare/i.test(String(a.target?.trait || a.target?.traitAny || ''))
      && String((a.sourceHostTarget||a.hostTarget||a.target?.sourceHostTarget||a.target?.hostTarget||{}).cardType||'').toLowerCase()==='tamer'));
  if(!end) issues.push('BT19-025 lower/source effect must be inherited END_OF_ATTACK once-per-turn and PLAY_FROM_SOURCE from an own Tamer host.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /PLAY_FROM_HAND_OR_TRASH|PLAY_FROM_HAND|PLAY_FROM_TRASH|PLAY_FROM_SOURCE/.test(JSON.stringify(m)))) issues.push('BT19-025 inherited End-of-Attack Tamer-source play must not remain encoded as END_OF_TURN.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /PLAY_FROM_SOURCE|PLAY_FROM_HAND_OR_TRASH|PLAY_FROM_HAND|PLAY_FROM_TRASH/.test(JSON.stringify(m)))) issues.push('BT19-025 lower/source play effect must not trigger from top-level MetalGreymon.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/metalGreymonBt19025InheritedEndAttackTamerSourcePlayLeak/.test(audit) || !/PLAY_FROM_SOURCE/.test(audit) || !/sourceHostTarget/.test(audit)) issues.push('audit-mechanics should guard Round 22CP BT19-025 inherited Tamer-source play.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CP BT19-025 MetalGreymon inherited End-of-Attack/.test(auto)) issues.push('auto-mechanics should document Round 22CP guardrails.');
  try{
    const turn=mkGame(['BT19-025','BT19-022','BT19-081','BT1-010'],['BT2-010']);
    turn.zones.p1.battleArea=[]; turn.zones.p1.hand=[]; turn.zones.p1.trash=[]; turn.effectQueue=[]; turn.pendingChoice=null;
    const turnHost=addBattle(turn,'p1','BT1-029',{tag:'22cp-turn-host',stack:[clone('BT19-025','22cp-turn-source')]});
    const turnTamer=clone('BT19-081','22cp-turn-tamer');
    const turnUnder=clone('BT19-022','22cp-turn-under');
    turnTamer.stack=[turnUnder];
    turn.zones.p1.battleArea.push(turnTamer);
    turn.triggerEffect('p1', turnHost, 'END_OF_TURN'); autoResolve(turn);
    if((turnTamer.stack||[]).length!==1 || turn.zones.p1.battleArea.some(c=>c.instanceId===turnUnder.instanceId)) issues.push('BT19-025 source effect must not play cards at END_OF_TURN.');

    const top=mkGame(['BT19-025','BT19-022','BT19-081','BT1-010'],['BT2-010']);
    top.zones.p1.battleArea=[]; top.zones.p1.hand=[]; top.zones.p1.trash=[]; top.effectQueue=[]; top.pendingChoice=null;
    const topMetal=addBattle(top,'p1','BT19-025',{tag:'22cp-top'});
    const topTamer=clone('BT19-081','22cp-top-tamer');
    const topUnder=clone('BT19-022','22cp-top-under');
    topTamer.stack=[topUnder];
    top.zones.p1.battleArea.push(topTamer);
    top.triggerEffect('p1', topMetal, 'END_OF_ATTACK'); autoResolve(top);
    if((topTamer.stack||[]).length!==1 || top.zones.p1.battleArea.some(c=>c.instanceId===topUnder.instanceId)) issues.push('BT19-025 inherited source effect must not trigger from top-level MetalGreymon.');

    const g=mkGame(['BT19-025','BT19-022','BT19-081','BT1-010'],['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.effectQueue=[]; g.pendingChoice=null;
    const host=addBattle(g,'p1','BT1-029',{tag:'22cp-host',stack:[clone('BT19-025','22cp-source')]});
    const tamer=clone('BT19-081','22cp-tamer');
    const underTamer=clone('BT19-022','22cp-under-tamer');
    tamer.stack=[underTamer];
    g.zones.p1.battleArea.push(tamer);
    const digimonHost=addBattle(g,'p1','BT1-010',{tag:'22cp-digimon-host',stack:[clone('BT19-022','22cp-under-digimon')]});
    const handCopy=addHand(g,'p1','BT19-022');
    const trashCopy=clone('BT19-022','22cp-trash'); g.zones.p1.trash.push(trashCopy);
    g.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g);
    const playedFromTamer=g.zones.p1.battleArea.find(c=>c.instanceId===underTamer.instanceId);
    if(!playedFromTamer) issues.push('BT19-025 source End-of-Attack should play the Lv.4 Blue Flare card from under an own Tamer.');
    if((tamer.stack||[]).some(c=>c.instanceId===underTamer.instanceId)) issues.push('BT19-025 PLAY_FROM_SOURCE should remove the played card from the Tamer stack.');
    if(!(digimonHost.stack||[]).some(c=>c.id==='BT19-022')) issues.push('BT19-025 should not play Blue Flare cards from under a Digimon host; only under own Tamers.');
    if(!g.zones.p1.hand.some(c=>c.instanceId===handCopy.instanceId)) issues.push('BT19-025 must not broaden the source zone to hand.');
    if(!g.zones.p1.trash.some(c=>c.instanceId===trashCopy.instanceId)) issues.push('BT19-025 must not broaden the source zone to trash.');
    issues.push(...checkInvariants(g,'Round22CPMetalGreymonTamerSourcePlay'));
  }catch(e){ issues.push('Round22CP runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CP BT19-025 MetalGreymon inherited End-of-Attack Tamer-source play guard', issues};
}

function testRound22CODexDoruGreymonInheritedEndAttackChosenLevelGuard(){
  const issues=[];
  const card=byId.get('BT17-067')||{};
  if(!/\[End of Attack\]/i.test(card.sourceEffect||'') || !/choose 1 of your Digimon/i.test(card.sourceEffect||'') || !/level equal to or lower/i.test(card.sourceEffect||'')) issues.push('BT17-067 should still print inherited End-of-Attack chosen-Digimon same/lower-level deletion text.');
  const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
  const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
    && m.isInherited===true
    && m.isOncePerTurn===true
    && String(m.cost?.type||'').toUpperCase()==='DELETE_OWN_DIGIMON_COST'
    && m.cost?.allowSource===true
    && (m.actions||[]).some(a=>String(a.type||'').toUpperCase()==='DELETE_DIGIMON'
      && String(a.target?.owner||'').toLowerCase()==='opponent'
      && String(a.target?.maxLevel||'').toLowerCase()==='deleted_cost_level'));
  if(!end) issues.push('BT17-067 lower/source effect must be inherited END_OF_ATTACK once-per-turn, delete chosen own Digimon, and bind opponent maxLevel to deleted_cost_level.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /DELETE_DIGIMON|DELETE_OWN_DIGIMON_COST/.test(JSON.stringify(m)))) issues.push('BT17-067 inherited deletion must not remain END_OF_TURN.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /deleted_cost_level|DELETE_OWN_DIGIMON_COST/.test(JSON.stringify(m)))) issues.push('BT17-067 source effect must not trigger from top-level DexDoruGreymon.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/dexDoruGreymonInheritedEndAttackChosenLevelLeak/.test(audit) || !/deleted_cost_level/.test(audit)) issues.push('audit-mechanics should guard Round 22CO DexDoruGreymon inherited chosen-level deletion.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CO BT17-067 DexDoruGreymon inherited End-of-Attack/.test(auto)) issues.push('auto-mechanics should document Round 22CO guardrails.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/deleted_cost_level/.test(gs) || !/deletedCostLevel/.test(gs)) issues.push('game-state should bind deleted_cost_level from DELETE_OWN_DIGIMON_COST for dynamic maxLevel target selection.');
  try{
    const top=mkGame(['BT17-067','BT1-010'], ['BT2-010']);
    top.zones.p1.battleArea=[]; top.zones.p2.battleArea=[]; top.effectQueue=[]; top.pendingTarget=null;
    const topDex=addBattle(top,'p1','BT17-067',{tag:'22co-top'});
    const own=addBattle(top,'p1','BT1-010',{tag:'22co-top-own',level:4});
    const opp=addBattle(top,'p2','BT2-010',{tag:'22co-top-opp',level:4});
    top.triggerEffect('p1', topDex, 'END_OF_ATTACK'); autoResolve(top);
    if(!top.zones.p1.battleArea.some(c=>c.instanceId===own.instanceId) || !top.zones.p2.battleArea.some(c=>c.instanceId===opp.instanceId)) issues.push('BT17-067 lower/source effect must not fire from a top-level DexDoruGreymon body.');

    const g=mkGame(['BT17-067','BT1-010'], ['BT2-010','BT2-011']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.pendingTarget=null;
    const chosen=addBattle(g,'p1','BT1-010',{tag:'22co-own-lv4',level:4});
    const host=addBattle(g,'p1','BT1-010',{tag:'22co-host-lv5',level:5,isSuspended:true});
    host.stack=[clone('BT17-067','22co-dex-source')];
    const high=addBattle(g,'p2','BT2-011',{tag:'22co-opp-lv5',level:5});
    const legal=addBattle(g,'p2','BT2-010',{tag:'22co-opp-lv4',level:4});
    g.triggerEffect('p1', host, 'END_OF_TURN'); autoResolve(g);
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===chosen.instanceId) || !g.zones.p2.battleArea.some(c=>c.instanceId===legal.instanceId)) issues.push('BT17-067 source effect must not delete anything at END_OF_TURN.');
    g.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g);
    if(g.zones.p1.battleArea.some(c=>c.instanceId===chosen.instanceId) || !g.zones.p1.trash.some(c=>c.instanceId===chosen.instanceId)) issues.push('BT17-067 should delete the chosen own Digimon at END_OF_ATTACK from inherited source.');
    if(!g.zones.p2.battleArea.some(c=>c.instanceId===high.instanceId)) issues.push('BT17-067 must not delete an opponent Digimon above the chosen/deleted own Digimon level.');
    if(g.zones.p2.battleArea.some(c=>c.instanceId===legal.instanceId) || !g.zones.p2.trash.some(c=>c.instanceId===legal.instanceId)) issues.push('BT17-067 should delete an opponent Digimon with level equal to or lower than the chosen/deleted Digimon.');

    const self=mkGame(['BT17-067','BT1-010'], ['BT2-010']);
    self.zones.p1.battleArea=[]; self.zones.p2.battleArea=[]; self.effectQueue=[]; self.pendingTarget=null;
    const selfHost=addBattle(self,'p1','BT1-010',{tag:'22co-self-host',level:5,isSuspended:true});
    selfHost.stack=[clone('BT17-067','22co-self-source')];
    const selfOpp=addBattle(self,'p2','BT2-010',{tag:'22co-self-opp',level:5});
    self.triggerEffect('p1', selfHost, 'END_OF_ATTACK'); autoResolve(self);
    if(self.zones.p1.battleArea.some(c=>c.instanceId===selfHost.instanceId)) issues.push('BT17-067 text says choose 1 of your Digimon, not other; source host should be a legal chosen Digimon when it is the only one.');
    if(self.zones.p2.battleArea.some(c=>c.instanceId===selfOpp.instanceId)) issues.push('BT17-067 opponent deletion should still resolve using the source host level when the host was the chosen/deleted Digimon.');
  }catch(e){ issues.push('Round22CO runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CO DexDoruGreymon inherited End-of-Attack chosen-level guard', issues};
}

function testRound22CNBeastAntylamonInheritedEndAttackCostGuard(){
  const issues=[];
  const specs={
    'BT17-049': { costType:'DELETE_OWN_DIGIMON_COST', payoff:'PLAY_FROM_TRASH', sourceZone:'trash', costWord:'deleting' },
    'EX6-034': { costType:'RETURN_TO_HAND_COST', payoff:'PLAY_FROM_HAND', sourceZone:'hand', costWord:'returning' }
  };
  for(const [id,spec] of Object.entries(specs)){
    const card=byId.get(id)||{};
    const sourceText=String(card.sourceEffect||'').replace(/\u00a0/g,' ');
    if(!/\[End of Attack\]/i.test(sourceText) || !/other suspended Digimon/i.test(sourceText) || !/level 3[^.]*\[Beast\]/i.test(sourceText)) issues.push(`${id}: source text should still be inherited End-of-Attack other-suspended-cost into Lv.3 Beast play.`);
    const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
    const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
      && m.isInherited===true
      && m.isOncePerTurn===true
      && String(m.cost?.type||'').toUpperCase()===spec.costType
      && m.cost?.target?.isSuspended===true
      && String(m.cost?.target?.owner||'').toLowerCase()==='own'
      && String(m.cost?.target?.cardType||'').toLowerCase()==='digimon'
      && (m.actions||[]).some(a=>String(a.type||'').toUpperCase()===spec.payoff
        && String(a.target?.owner||'').toLowerCase()==='own'
        && String(a.target?.cardType||'').toLowerCase()==='digimon'
        && Number(a.target?.level ?? a.target?.maxLevel)===3
        && String(a.target?.trait||'').toLowerCase()==='beast'));
    if(!end) issues.push(`${id}: lower/source effect must be inherited END_OF_ATTACK once-per-turn with ${spec.costType} on another suspended own Digimon and ${spec.payoff} Lv.3 Beast payoff.`);
    if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /PLAY_FROM_TRASH|PLAY_FROM_HAND|DELETE_DIGIMON|BOUNCE/.test(JSON.stringify(m.actions||[])) && /suspended|Beast/i.test(JSON.stringify(m)))) issues.push(`${id}: inherited source effect must not remain END_OF_TURN.`);
    if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /PLAY_FROM_TRASH|PLAY_FROM_HAND/.test(JSON.stringify(m.actions||[])) && /suspended|Beast/i.test(JSON.stringify(m)))) issues.push(`${id}: inherited source payoff must not be a top-level Antylamon effect.`);
  }
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/beastAntylamonInheritedEndAttackCostLeak/.test(audit) || !/BT17-049/.test(audit) || !/EX6-034/.test(audit)) issues.push('audit-mechanics should guard Round 22CN Beast Antylamon inherited End-of-Attack cost/payoff source effects.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CN BT17\/EX6 Antylamon inherited End-of-Attack/.test(auto)) issues.push('auto-mechanics should document Round 22CN guardrails.');
  try{
    const top=mkGame(['BT17-049','BT1-010'], ['BT2-010']);
    top.zones.p1.battleArea=[]; top.zones.p1.trash=[]; top.effectQueue=[]; top.pendingTarget=null;
    const topAnti=addBattle(top,'p1','BT17-049',{tag:'22cn-top'});
    const sacr=addBattle(top,'p1','BT1-010',{tag:'22cn-top-sacr',isSuspended:true,traits:'Beast',traitTokens:['Beast'],level:3});
    top.triggerEffect('p1', topAnti, 'END_OF_TURN'); autoResolve(top);
    if(!top.zones.p1.battleArea.some(c=>c.instanceId===sacr.instanceId)) issues.push('BT17-049 top-level Antylamon must not delete other Digimon at END_OF_TURN.');
    top.triggerEffect('p1', topAnti, 'END_OF_ATTACK'); autoResolve(top);
    if(!top.zones.p1.battleArea.some(c=>c.instanceId===sacr.instanceId)) issues.push('BT17-049 inherited source effect must not fire from top-level Antylamon at END_OF_ATTACK.');

    const g1=mkGame(['BT17-049','BT1-010'], ['BT2-010']);
    g1.zones.p1.battleArea=[]; g1.zones.p1.trash=[]; g1.effectQueue=[]; g1.pendingTarget=null;
    const host=addBattle(g1,'p1','BT1-010',{tag:'22cn-bt17-host',isSuspended:true});
    host.stack=[clone('BT17-049','22cn-bt17-source')];
    const beast=addBattle(g1,'p1','BT1-010',{tag:'22cn-bt17-beast',isSuspended:true,traits:'Beast',traitTokens:['Beast'],level:3});
    g1.triggerEffect('p1', host, 'END_OF_TURN'); autoResolve(g1);
    if(!g1.zones.p1.battleArea.some(c=>c.instanceId===beast.instanceId)) issues.push('BT17-049 source effect must not delete/play at END_OF_TURN.');
    g1.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g1);
    if(g1.zones.p1.battleArea.some(c=>c.instanceId===host.instanceId)===false) issues.push('BT17-049 cost says other suspended Digimon, so the source host must not delete itself.');
    if(!g1.zones.p1.battleArea.some(c=>c.instanceId===beast.instanceId)) issues.push('BT17-049 should be able to play the Lv.3 Beast Digimon it deleted as cost from trash.');
    if(g1.zones.p1.trash.some(c=>c.instanceId===beast.instanceId)) issues.push('BT17-049 cost Beast should not remain in trash after being played by the payoff.');

    const g2=mkGame(['EX6-034','BT1-010'], ['BT2-010']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.hand=[]; g2.effectQueue=[]; g2.pendingTarget=null;
    const host2=addBattle(g2,'p1','BT1-010',{tag:'22cn-ex6-host',isSuspended:true});
    host2.stack=[clone('EX6-034','22cn-ex6-source')];
    const beast2=addBattle(g2,'p1','BT1-010',{tag:'22cn-ex6-beast',isSuspended:true,traits:'Beast',traitTokens:['Beast'],level:3});
    g2.triggerEffect('p1', host2, 'END_OF_TURN'); autoResolve(g2);
    if(!g2.zones.p1.battleArea.some(c=>c.instanceId===beast2.instanceId)) issues.push('EX6-034 source effect must not return/play at END_OF_TURN.');
    g2.triggerEffect('p1', host2, 'END_OF_ATTACK'); autoResolve(g2);
    if(g2.zones.p1.battleArea.some(c=>c.instanceId===host2.instanceId)===false) issues.push('EX6-034 cost says other suspended Digimon, so the source host must not return itself.');
    if(!g2.zones.p1.battleArea.some(c=>c.instanceId===beast2.instanceId)) issues.push('EX6-034 should be able to play the Lv.3 Beast Digimon it returned to hand as cost.');
    if(g2.zones.p1.hand.some(c=>c.instanceId===beast2.instanceId)) issues.push('EX6-034 returned Beast should not remain in hand after being played by the payoff.');

    const g3=mkGame(['BT17-049','BT1-010'], ['BT2-010']);
    g3.zones.p1.battleArea=[]; g3.zones.p1.trash=[]; g3.effectQueue=[]; g3.pendingTarget=null;
    const host3=addBattle(g3,'p1','BT1-010',{tag:'22cn-bt17-hostonly',isSuspended:true});
    host3.stack=[clone('BT17-049','22cn-bt17-source-only')];
    g3.triggerEffect('p1', host3, 'END_OF_ATTACK'); autoResolve(g3);
    if(!g3.zones.p1.battleArea.some(c=>c.instanceId===host3.instanceId)) issues.push('BT17-049 must not pay the other-suspended cost with only the source host suspended.');
  }catch(e){ issues.push('Round22CN runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CN Beast Antylamon inherited End-of-Attack other-suspended cost guard', issues};
}

function testRound22CMEx4AllianceInheritedEndAttackAnotherSuspendedGuard(){
  const issues=[];
  const specs={
    'EX4-025': { actionType:'DP_MOD', dp:-2000 },
    'EX4-029': { actionType:'DP_MOD', dp:-2000, topRecovery:true },
    'EX4-054': { actionType:'ADD_TO_HAND', returnGreen:true },
    'EX4-057': { actionType:'ADD_TO_HAND', returnGreen:true }
  };
  for(const [id,spec] of Object.entries(specs)){
    const card=byId.get(id)||{};
    const sourceText=String(card.sourceEffect||'');
    if(!/\[End of Attack\]/i.test(sourceText) || !/another suspended Digimon/i.test(sourceText)) issues.push(`${id}: source text should still be inherited End-of-Attack another-suspended text.`);
    const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
    const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
      && m.isInherited===true
      && m.isOncePerTurn===true
      && String(m.condition?.type||'').toUpperCase()==='IS_SUSPENDED'
      && m.condition?.excludeSelf===true
      && (m.actions||[]).some(a=>{
        if(String(a.type||'').toUpperCase()!==spec.actionType) return false;
        if(spec.dp!==undefined) return Number(a.amount ?? a.value ?? a.buff?.value)===spec.dp;
        if(spec.returnGreen) return String(a.from||a.zone||'').toLowerCase().includes('trash') && /green/i.test(JSON.stringify(a.target||{}));
        return true;
      }));
    if(!end) issues.push(`${id}: lower/source effect must be inherited END_OF_ATTACK once-per-turn with IS_SUSPENDED excludeSelf:true and printed payoff.`);
    if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /DP_MOD|ADD_TO_HAND/.test(JSON.stringify(m.actions||[])) && /suspended|Green|-2000/i.test(JSON.stringify(m)))) issues.push(`${id}: inherited End-of-Attack source payoff must not remain END_OF_TURN.`);
    if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='MAIN' && m.isInherited===true && /Alliance/.test(JSON.stringify(m)))) issues.push(`${id}: lower/source effect must not be a fake MAIN inherited Alliance grant.`);
  }
  const ex4029=byId.get('EX4-029')||{};
  const topRecovery=(ex4029.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /RECOVERY_DECK/.test(JSON.stringify(m.actions||[])));
  if(!topRecovery) issues.push('EX4-029 top-level Recovery +1 must trigger at END_OF_ATTACK, not END_OF_TURN.');

  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/case ['"]IS_SUSPENDED['"][\s\S]{0,900}excludeSelf/.test(gs)) issues.push('game-state IS_SUSPENDED condition should support excludeSelf for “another suspended Digimon”.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/ex4AllianceInheritedEndAttackAnotherSuspendedLeak/.test(audit) || !/EX4-054/.test(audit)) issues.push('audit-mechanics should guard Round 22CM EX4 Alliance inherited End-of-Attack source scope.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CM EX4 Alliance inherited End-of-Attack/.test(auto)) issues.push('auto-mechanics should document Round 22CM guardrails.');

  try{
    const g0=mkGame(['EX4-025','BT1-010'], ['BT2-010']);
    g0.zones.p1.battleArea=[]; g0.zones.p2.battleArea=[];
    const host0=addBattle(g0,'p1','BT1-010',{tag:'22cm-cond-host',isSuspended:true});
    const cond={type:'IS_SUSPENDED',owner:'own',cardType:'digimon',excludeSelf:true};
    if(g0.evaluateStructuredCondition('p1',cond,host0,{})) issues.push('IS_SUSPENDED excludeSelf should be false when only the source host is suspended.');
    const other0=addBattle(g0,'p1','BT1-010',{tag:'22cm-cond-other',isSuspended:true});
    if(!g0.evaluateStructuredCondition('p1',cond,host0,{})) issues.push('IS_SUSPENDED excludeSelf should be true when another own Digimon is suspended.');

    const top=mkGame(['EX4-025','BT1-010'], ['BT2-010']);
    top.zones.p1.battleArea=[]; top.zones.p2.battleArea=[]; top.effectQueue=[]; top.actionLogs=[];
    const turTop=addBattle(top,'p1','EX4-025',{tag:'22cm-top',isSuspended:true});
    const oppTop=addBattle(top,'p2','BT2-010',{tag:'22cm-opp-top'});
    top.triggerEffect('p1',turTop,'END_OF_ATTACK'); autoResolve(top);
    if(hasTurnEffect(oppTop,'DP_MOD',e=>Number(e.value)===-2000)) issues.push('EX4-025 lower/source DP-down must not trigger from top-level Turuiemon.');

    const g1=mkGame(['EX4-025','BT1-010'], ['BT2-010']);
    g1.zones.p1.battleArea=[]; g1.zones.p2.battleArea=[]; g1.effectQueue=[]; g1.actionLogs=[];
    const host=addBattle(g1,'p1','BT1-010',{tag:'22cm-host',isSuspended:true});
    host.stack=[clone('EX4-025','22cm-source')];
    const opp=addBattle(g1,'p2','BT2-010',{tag:'22cm-opp'});
    g1.triggerEffect('p1',host,'END_OF_TURN'); autoResolve(g1);
    if(hasTurnEffect(opp,'DP_MOD',e=>Number(e.value)===-2000)) issues.push('EX4-025 inherited DP-down must not trigger at END_OF_TURN.');
    g1.triggerEffect('p1',host,'END_OF_ATTACK'); autoResolve(g1);
    if(hasTurnEffect(opp,'DP_MOD',e=>Number(e.value)===-2000)) issues.push('EX4-025 inherited DP-down must not count the attacking/source host as “another suspended Digimon”.');

    const g2=mkGame(['EX4-025','BT1-010'], ['BT2-010']);
    g2.zones.p1.battleArea=[]; g2.zones.p2.battleArea=[]; g2.effectQueue=[]; g2.actionLogs=[];
    const host2=addBattle(g2,'p1','BT1-010',{tag:'22cm-host2',isSuspended:true});
    host2.stack=[clone('EX4-025','22cm-source2')];
    const ally=addBattle(g2,'p1','BT1-010',{tag:'22cm-other-suspended',isSuspended:true});
    const opp2=addBattle(g2,'p2','BT2-010',{tag:'22cm-opp2'});
    g2.triggerEffect('p1',host2,'END_OF_ATTACK'); autoResolve(g2);
    if(!hasTurnEffect(opp2,'DP_MOD',e=>Number(e.value)===-2000)) issues.push('EX4-025 inherited END_OF_ATTACK should give an opponent Digimon -2000 DP when another own Digimon is suspended.');

    const g3=mkGame(['EX4-054','BT1-010'], ['BT2-010']);
    g3.zones.p1.battleArea=[]; g3.zones.p2.battleArea=[]; g3.zones.p1.trash=[]; g3.zones.p1.hand=[]; g3.effectQueue=[]; g3.actionLogs=[];
    const host3=addBattle(g3,'p1','BT1-010',{tag:'22cm-wendi-host',isSuspended:true});
    host3.stack=[clone('EX4-054','22cm-wendi-source')];
    const green={id:'22cm-green',name:'Green trash Digimon',type:'digimon',color:'Green',colors:['Green'],level:3,instanceId:'22cm-green'};
    g3.zones.p1.trash.push(green);
    g3.triggerEffect('p1',host3,'END_OF_ATTACK'); autoResolve(g3);
    if(g3.zones.p1.hand.some(c=>c.instanceId==='22cm-green')) issues.push('EX4-054 inherited trash-to-hand must not count only the source host as another suspended Digimon.');
    const g4=mkGame(['EX4-054','BT1-010'], ['BT2-010']);
    g4.zones.p1.battleArea=[]; g4.zones.p2.battleArea=[]; g4.zones.p1.trash=[]; g4.zones.p1.hand=[]; g4.effectQueue=[]; g4.actionLogs=[];
    const host4=addBattle(g4,'p1','BT1-010',{tag:'22cm-wendi-host2',isSuspended:true});
    host4.stack=[clone('EX4-054','22cm-wendi-source2')];
    const other4=addBattle(g4,'p1','BT1-010',{tag:'22cm-wendi-other',isSuspended:true});
    const green2={id:'22cm-green2',name:'Green trash Digimon 2',type:'digimon',color:'Green',colors:['Green'],level:3,instanceId:'22cm-green2'};
    g4.zones.p1.trash.push(green2);
    g4.triggerEffect('p1',host4,'END_OF_ATTACK'); autoResolve(g4);
    if(!g4.zones.p1.hand.some(c=>c.instanceId==='22cm-green2')) issues.push('EX4-054 inherited END_OF_ATTACK should return 1 green Digimon from trash to hand when another own Digimon is suspended.');
  }catch(e){ issues.push('Round22CM runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CM EX4 Alliance inherited End-of-Attack another-suspended source guard', issues};
}

function testRound22CLMadLeomonInheritedEndAttackSelfDeleteGuard(){
  const issues=[];
  const card=byId.get('BT16-071')||{};
  const sourceText=String(card.sourceEffect||'');
  if(!/\[End of Attack\]/i.test(sourceText) || !/deleting this Digimon/i.test(sourceText) || !/level 4 or lower/i.test(sourceText)) issues.push('BT16-071 source text should still print inherited End-of-Attack self-delete into Lv.4-or-lower trash play.');
  const mechanics=Array.isArray(card.mechanics)?card.mechanics:[];
  const end=mechanics.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK'
    && m.isInherited===true
    && String(m.cost?.type||'').toUpperCase()==='DELETE_OWN_DIGIMON_COST'
    && m.cost?.self===true
    && (m.actions||[]).some(a=>String(a.type||'').toUpperCase()==='PLAY_FROM_TRASH' && Number(a.target?.maxLevel)===4 && String(a.target?.cardType||'').toLowerCase()==='digimon'));
  if(!end) issues.push('BT16-071 must encode source text as inherited END_OF_ATTACK, DELETE_OWN_DIGIMON_COST self:true, then PLAY_FROM_TRASH maxLevel 4.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && /DELETE_OWN_DIGIMON_COST|PLAY_FROM_TRASH/.test(JSON.stringify(m)))) issues.push('BT16-071 inherited End-of-Attack self-delete/play effect must not remain END_OF_TURN.');
  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /DELETE_OWN_DIGIMON_COST|PLAY_FROM_TRASH/.test(JSON.stringify(m)))) issues.push('BT16-071 lower/source effect must not be encoded as a top-level MadLeomon effect.');
  const audit=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
  if(!/BT16-071/.test(audit) || !/requireSelfDeleteCost/.test(audit)) issues.push('audit-mechanics should guard Round 22CL BT16-071 inherited End-of-Attack self-delete source effect.');
  const auto=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
  if(!/Round 22CL BT16-071 MadLeomon inherited End-of-Attack/.test(auto)) issues.push('auto-mechanics should document Round 22CL guardrails.');
  try{
    const top=mkGame(['BT16-071','BT1-010'], ['BT2-010']);
    top.zones.p1.battleArea=[]; top.zones.p1.trash=[]; top.effectQueue=[]; top.pendingTarget=null; top.memory=0;
    const madTop=addBattle(top,'p1','BT16-071',{tag:'22cl-top'});
    const other=addBattle(top,'p1','BT1-010',{tag:'22cl-other'});
    top.triggerEffect('p1', madTop, 'END_OF_TURN'); autoResolve(top);
    if(!top.zones.p1.battleArea.some(c=>c.instanceId===madTop.instanceId) || !top.zones.p1.battleArea.some(c=>c.instanceId===other.instanceId)) issues.push('BT16-071 source effect must not fire from top-level MadLeomon at END_OF_TURN.');

    const g=mkGame(['BT16-071','BT1-010','BT2-010'], ['BT2-010']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[]; g.effectQueue=[]; g.pendingTarget=null; g.memory=0;
    const host=addBattle(g,'p1','BT1-010',{tag:'22cl-host'});
    const source=clone('BT16-071','22cl-source');
    host.stack=[source];
    const revive=clone('BT2-010','22cl-trash-target');
    g.zones.p1.trash.push(revive);
    g.triggerEffect('p1', host, 'END_OF_TURN'); autoResolve(g);
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===host.instanceId) || !g.zones.p1.trash.some(c=>c.instanceId===revive.instanceId)) issues.push('BT16-071 source effect must not delete/play at END_OF_TURN.');
    g.triggerEffect('p1', host, 'END_OF_ATTACK'); autoResolve(g);
    if(g.zones.p1.battleArea.some(c=>c.instanceId===host.instanceId)) issues.push('BT16-071 inherited END_OF_ATTACK cost should delete the source host / this Digimon.');
    if(!g.zones.p1.trash.some(c=>c.instanceId===host.instanceId)) issues.push('BT16-071 self-delete cost should move the host to trash.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===revive.instanceId)) issues.push('BT16-071 payoff should play 1 Lv.4 or lower Digimon card from trash after the self-delete cost.');
  }catch(e){ issues.push('Round22CL runtime simulation failed: '+(e.stack||e.message)); }
  return {name:'Round 22CL BT16-071 MadLeomon inherited End-of-Attack self-delete guard', issues};
}

