  if(mechanics.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited!==true && /UNSUSPEND/.test(JSON.stringify(m.actions||[])) && /Sakuyamon/i.test(JSON.stringify(m.actions||[])))) issues.push('ST22-04 lower text must not be encoded as top-level END_OF_ATTACK.');
