  const gradeEnd=gradeMechs.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited===true && /Alphamon/i.test(JSON.stringify(m.condition||{})) && (m.actions||[]).some(a=>a.type==='DELETE_DIGIMON' && Number(a.target?.maxCost)===5));
  const ouryuEnd=ouryuMechs.find(m=>String(m.trigger||'').toUpperCase()==='END_OF_ATTACK' && m.isInherited===true && m.isOncePerTurn===true && /Alphamon/i.test(JSON.stringify(m.condition||{})) && (m.actions||[]).some(a=>a.type==='UNSUSPEND' && a.target?.self===true));
  if(!gradeEnd) issues.push('BT9-064 Grademon must encode inherited END_OF_ATTACK host-Alphamon delete max play cost 5.');
  if(!ouryuEnd) issues.push('BT8-069 Ouryumon must encode inherited END_OF_ATTACK once-per-turn host-Alphamon self-unsuspend.');
  if(gradeMechs.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && JSON.stringify(m.actions||[]).includes('DELETE_DIGIMON'))) issues.push('BT9-064 inherited End of Attack deletion must not remain END_OF_TURN.');
  if(ouryuMechs.some(m=>String(m.trigger||'').toUpperCase()==='END_OF_TURN' && JSON.stringify(m.actions||[]).includes('UNSUSPEND'))) issues.push('BT8-069 inherited End of Attack unsuspend must not remain END_OF_TURN.');
