function testRound22EEVioletInbootsTimingGuard(){
  const issues=[];
  try{
    const card=base('EX11-068');
    const mech=(trig)=>(card.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()===trig);
    const start=mech('START_OF_TURN');
    const attack=mech('WHEN_ATTACKING') || mech('YOUR_TURN');
    const security=mech('SECURITY');
    const startBlob=JSON.stringify(start||{});
    const attackBlob=JSON.stringify(attack||{});
    const securityBlob=JSON.stringify(security||{});
    const startTypes=(start?.actions||[]).map(a=>String(a.type||'').toUpperCase());
    const attackTypes=(attack?.actions||[]).map(a=>String(a.type||'').toUpperCase());
    const securityTypes=(security?.actions||[]).map(a=>String(a.type||'').toUpperCase());
    if(!startTypes.includes('SET_MEMORY')) issues.push('EX11-068 Start of Your Turn must SET_MEMORY 3.');
    if(!start?.condition || String(start.condition.type||'').toUpperCase()!=='MEMORY_COUNT' || String(start.condition.operator||'')!=='<=' || Number(start.condition.value)!==2) issues.push('EX11-068 Start memory setter must be MEMORY_COUNT <= 2.');
    if(/DRAW|TRASH_HAND|REVEAL_AND_SELECT/.test(startBlob)) issues.push('EX11-068 attack loot leaked into START_OF_TURN.');
    if(!attack || !attackTypes.includes('DRAW') || !attackTypes.includes('TRASH_HAND')) issues.push('EX11-068 Ghost attack trigger must draw 1 and trash 1.');
    if(!/EVENT_CONTEXT/.test(attackBlob) || !/attacker/.test(attackBlob) || !/Ghost/.test(attackBlob)) issues.push('EX11-068 attack trigger must inspect EVENT_CONTEXT.attacker for Ghost trait.');
    if(!/(optionalProcessing|requiresActivationChoice|"optional"\s*:\s*true)/.test(attackBlob)) issues.push('EX11-068 suspend-cost attack trigger must be optional/confirmable.');
    if(!securityTypes.includes('PLAY_FROM_SECURITY')) issues.push('EX11-068 Security must PLAY_FROM_SECURITY.');
    if(/DRAW|TRASH_HAND|SET_MEMORY/.test(securityBlob)) issues.push('EX11-068 Security must not directly draw/trash/set memory.');

    const gStart=mkGame(['EX11-068','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    gStart.zones.p1.battleArea=[]; gStart.zones.p1.hand=[]; gStart.zones.p1.trash=[]; gStart.effectQueue=[]; gStart.pendingEffectSelection=null; gStart.pendingChoice=null; gStart.pendingReveal=null; gStart.memory=1;
    const violetStart=addBattle(gStart,'p1','EX11-068',{tag:'22ee-start'});
    const deckBeforeStart=gStart.zones.p1.deck.length;
    gStart.triggerEffect('p1', violetStart, 'START_OF_TURN');
    autoResolve(gStart);
    if(gStart.memory!==3) issues.push(`EX11-068 Start should set memory to 3 from 1, got ${gStart.memory}.`);
    if(gStart.zones.p1.deck.length!==deckBeforeStart) issues.push('EX11-068 Start must not draw/reveal deck cards.');
    if(gStart.zones.p1.trash.length!==0) issues.push('EX11-068 Start must not trash hand cards.');

    const gSecurity=mkGame(['EX11-068','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    gSecurity.zones.p1.battleArea=[]; gSecurity.zones.p1.trash=[]; gSecurity.zones.p1.hand=[]; gSecurity.effectQueue=[]; gSecurity.pendingEffectSelection=null; gSecurity.pendingChoice=null; gSecurity.pendingReveal=null;
    const violetSec=clone('EX11-068','22ee-security');
    gSecurity.zones.p1.security=[violetSec];
    gSecurity.triggerEffect('p1', violetSec, 'SECURITY');
    autoResolve(gSecurity);
    if(!gSecurity.zones.p1.battleArea.some(c=>c.instanceId===violetSec.instanceId)) issues.push('EX11-068 Security should play Violet Inboots from security into battle area.');
    if(gSecurity.zones.p1.hand.some(c=>c.instanceId===violetSec.instanceId) || gSecurity.zones.p1.trash.some(c=>c.instanceId===violetSec.instanceId)) issues.push('EX11-068 Security should not add to hand or trash itself.');

    const gAttack=mkGame(['EX11-068','EX11-048','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    gAttack.zones.p1.battleArea=[]; gAttack.zones.p1.hand=[clone('BT1-010','22ee-hand')]; gAttack.zones.p1.trash=[]; gAttack.effectQueue=[]; gAttack.pendingEffectSelection=null; gAttack.pendingChoice=null; gAttack.pendingReveal=null;
    const violetAtk=addBattle(gAttack,'p1','EX11-068',{tag:'22ee-attack', isSuspended:false});
    const ghost=addBattle(gAttack,'p1','EX11-048',{tag:'22ee-ghost', playedThisTurn:false});
    const nonGhost=addBattle(gAttack,'p1','BT1-010',{tag:'22ee-nonghost', playedThisTurn:false});
    const deckBeforeAttack=gAttack.zones.p1.deck.length;
    const trashBeforeAttack=gAttack.zones.p1.trash.length;
    gAttack.currentTriggerContext={attacker:nonGhost, attackerPlayerId:'p1'};
    gAttack.triggerEffect('p1', violetAtk, 'WHEN_ATTACKING');
    autoResolve(gAttack);
    if(violetAtk.isSuspended) issues.push('EX11-068 must not trigger when a non-Ghost Digimon attacks.');
    if(gAttack.zones.p1.deck.length!==deckBeforeAttack) issues.push('EX11-068 non-Ghost attack must not draw.');
    gAttack.currentTriggerContext={attacker:ghost, attackerPlayerId:'p1'};
    gAttack.triggerEffect('p1', violetAtk, 'WHEN_ATTACKING');
    if(!gAttack.pendingEffectSelection || gAttack.pendingEffectSelection.mode!=='OPTIONAL_EFFECT_CONFIRM') issues.push('EX11-068 Ghost attack should open optional confirm before suspending Tamer.');
    autoResolve(gAttack);
    if(!violetAtk.isSuspended) issues.push('EX11-068 Ghost attack effect should suspend Violet Inboots as cost after confirm.');
    if(gAttack.zones.p1.deck.length!==deckBeforeAttack-1) issues.push('EX11-068 Ghost attack effect should draw exactly 1 card.');
    if(gAttack.zones.p1.trash.length!==trashBeforeAttack+1) issues.push('EX11-068 Ghost attack effect should trash exactly 1 hand card after drawing.');
    issues.push(...checkInvariants(gStart,'round22eeStart'), ...checkInvariants(gSecurity,'round22eeSecurity'), ...checkInvariants(gAttack,'round22eeAttack'));

    const auditText=fs.readFileSync(path.join(__dirname,'audit-mechanics.js'),'utf8');
    const autoText=fs.readFileSync(path.join(__dirname,'auto-mechanics.js'),'utf8');
    if(!/violetInbootsTimingLeak/.test(auditText)) issues.push('audit-mechanics should include violetInbootsTimingLeak.');
    if(!/Round 22EE Violet Inboots/.test(autoText)) issues.push('auto-mechanics should document Round 22EE guardrails.');
  }catch(e){ issues.push('Round22EE Violet Inboots timing guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EE Violet Inboots timing guard', issues};
}

function testRound22EDOptionalStartTurnProcessingGuard(){
  const issues=[];
  try{
    const card=base('BT11-012');
    const mechs=card.mechanics||[];
    const start=mechs.find(m=>String(m.trigger||'').toUpperCase()==='START_OF_TURN');
    const onPlay=mechs.find(m=>String(m.trigger||'').toUpperCase()==='ON_PLAY');
    const startBlob=JSON.stringify(start||{});
    const onPlayBlob=JSON.stringify(onPlay||{});
    if(!start) issues.push('BT11-012 missing START_OF_TURN mechanic.');
    if(!(start?.optional===true || start?.optionalProcessing===true || start?.may===true)) issues.push('BT11-012 Start-of-Turn By deleting this Digimon must be optional/optionalProcessing.');
    if(!/DELETE_OWN_DIGIMON_COST/.test(startBlob) || !/"self"\s*:\s*true/.test(startBlob)) issues.push('BT11-012 Start-of-Turn must use DELETE_OWN_DIGIMON_COST self:true.');
    if(!/GAIN_MEMORY/.test(startBlob) || !/"amount"\s*:\s*1/.test(startBlob)) issues.push('BT11-012 Start-of-Turn must gain exactly 1 memory after cost.');
    if(/REVEAL_AND_SELECT|RETURN_REVEALED_REST_TO_DECK_BOTTOM/.test(startBlob)) issues.push('BT11-012 On Play reveal/search leaked into Start of Your Turn.');
    if(!onPlay || !/REVEAL_AND_SELECT/.test(onPlayBlob) || !/RETURN_REVEALED_REST_TO_DECK_BOTTOM/.test(onPlayBlob)) issues.push('BT11-012 On Play reveal/search/bottom-rest branch missing.');
    if(/"color"\s*:\s*"blue"/i.test(onPlayBlob)) issues.push('BT11-012 On Play should be trait-based, not blue-color restricted.');

    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/isOptionalStructuredEffect/.test(gs) || !/openOptionalStructuredEffectChoice/.test(gs) || !/OPTIONAL_EFFECT_CONFIRM/.test(gs)) issues.push('game-state must expose generic optional structured effect confirmation.');
    if(!/pendingStartPhase/.test(gs) || !/continuePendingStartPhase/.test(gs)) issues.push('game-state must pause official start sequence while optional Start-of-Turn choice is pending.');

    // Skip path: trigger opens a real choice before Unsuspend/Draw/Breeding; SKIP keeps X3 alive and then resumes the start sequence.
    const gSkip=mkGame(['BT11-012','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    gSkip.zones.p1.battleArea=[]; gSkip.zones.p1.hand=[]; gSkip.zones.p1.trash=[]; gSkip.actionLogs=[]; gSkip.effectQueue=[]; gSkip.pendingEffectSelection=null; gSkip.pendingStartPhase=null; gSkip.memory=0; gSkip.turnPlayer='p1'; gSkip.turnCount=3; gSkip.phase='MAIN';
    const x3Skip=addBattle(gSkip,'p1','BT11-012',{tag:'skip-x3'});
    const deckBeforeSkip=gSkip.zones.p1.deck.length;
    const startReturn=gSkip.startNewTurn();
    if(startReturn!==false) issues.push('startNewTurn should pause while BT11-012 optional Start-of-Turn choice is pending.');
    if(!gSkip.pendingEffectSelection || gSkip.pendingEffectSelection.mode!=='OPTIONAL_EFFECT_CONFIRM') issues.push('BT11-012 Start-of-Turn should open OPTIONAL_EFFECT_CONFIRM pendingEffectSelection.');
    if(!gSkip.pendingStartPhase) issues.push('Start phase should be marked pending while optional choice is open.');
    if(gSkip.phase==='HATCH' || gSkip.zones.p1.deck.length!==deckBeforeSkip) issues.push('Unsuspend/Draw/Breeding must not advance before optional Start-of-Turn choice is answered.');
    gSkip.resolveManualEffect('p1',0,false);
    if(gSkip.pendingEffectSelection) issues.push('Skipping BT11-012 optional effect should clear pendingEffectSelection.');
    if(gSkip.pendingStartPhase) issues.push('Skipping BT11-012 optional effect should resume and clear pendingStartPhase.');
    if(!gSkip.zones.p1.battleArea.some(c=>c.instanceId===x3Skip.instanceId)) issues.push('Skipping BT11-012 optional effect should keep Shoutmon X3 in battle area.');
    if(gSkip.memory!==0) issues.push(`Skipping BT11-012 optional effect should not gain memory, got ${gSkip.memory}.`);
    if(gSkip.phase!=='HATCH') issues.push(`After skip, start sequence should resume to HATCH/Breeding phase, got ${gSkip.phase}.`);
    if(gSkip.zones.p1.deck.length!==deckBeforeSkip-1) issues.push('After skip, exactly the normal draw should occur; no reveal/search should touch extra deck cards.');
    if(gSkip.zones.p1.trash.some(c=>c.instanceId===x3Skip.instanceId)) issues.push('Skipping BT11-012 optional effect should not delete Shoutmon X3.');

    // Activate path: confirmed effect stays STRUCTURED_ACTION, pays delete-this cost, gains 1 memory, then resumes start sequence.
    const gAct=mkGame(['BT11-012','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    gAct.zones.p1.battleArea=[]; gAct.zones.p1.hand=[]; gAct.zones.p1.trash=[]; gAct.actionLogs=[]; gAct.effectQueue=[]; gAct.pendingEffectSelection=null; gAct.pendingStartPhase=null; gAct.memory=0; gAct.turnPlayer='p1'; gAct.turnCount=3; gAct.phase='MAIN';
    const x3Act=addBattle(gAct,'p1','BT11-012',{tag:'act-x3'});
    const deckBeforeAct=gAct.zones.p1.deck.length;
    gAct.startNewTurn();
    if(!gAct.pendingEffectSelection) issues.push('Activate path: optional choice did not open.');
    gAct.resolveManualEffect('p1',0,true);
    if(gAct.pendingEffectSelection || gAct.pendingStartPhase) issues.push('Activate path should clear optional/start pending windows after resolution.');
    if(gAct.zones.p1.battleArea.some(c=>c.instanceId===x3Act.instanceId)) issues.push('Activating BT11-012 optional effect should delete Shoutmon X3 as cost.');
    if(!gAct.zones.p1.trash.some(c=>c.instanceId===x3Act.instanceId)) issues.push('Activating BT11-012 optional effect should move Shoutmon X3 to trash.');
    if(gAct.memory!==1) issues.push(`Activating BT11-012 optional effect should gain 1 memory from 0 to 1, got ${gAct.memory}.`);
    if(gAct.phase!=='HATCH') issues.push(`After activate, start sequence should resume to HATCH/Breeding phase, got ${gAct.phase}.`);
    if(gAct.zones.p1.deck.length!==deckBeforeAct-1) issues.push('Activate path should perform only normal draw after optional resolution, not On Play reveal/search.');
    issues.push(...checkInvariants(gSkip,'round22edSkip'), ...checkInvariants(gAct,'round22edActivate'));
  }catch(e){ issues.push('Round22ED optional Start-of-Turn processing guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22ED optional Start-of-Turn processing guard', issues};
}






function testRound22EIEffectAttackDuringExistingAttackGuard(){
  const issues=[];
  try{
    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/isAttackInProgress\s*\(\)/.test(gs) || !/rejectNestedAttackDeclaration\s*\(/.test(gs)) issues.push('game-state must expose a central nested-attack declaration guard.');
    for(const fn of ['requestAttack','requestAttackPlayer','requestAttackDigimon','startAttackWithoutSuspending','startForcedAttackWithLegalTarget']){
      const re=new RegExp(fn+'\\s*\\([^)]*\\)\\s*{[\\s\\S]{0,260}rejectNestedAttackDeclaration');
      if(!re.test(gs)) issues.push(`${fn} must reject new attack declarations while an existing attack is in progress.`);
    }

    const g=mkGame(['BT25-086','BT25-033','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.effectQueue=[]; g.pendingChoice=null; g.pendingTarget=null; g.pendingReveal=null; g.actionLogs=[]; g.turnPlayer='p1'; g.phase='MAIN'; g.memory=-1;
    const ts=addBattle(g,'p1','BT25-033',{tag:'round22ei-ts', isSuspended:false, playedThisTurn:false});
    const dan1=addBattle(g,'p1','BT25-086',{tag:'round22ei-dan1', isSuspended:true});
    const dan2=addBattle(g,'p1','BT25-086',{tag:'round22ei-dan2', isSuspended:false});
    g.counterTiming={isActive:true, step:'WHEN_ATTACKING', defenderId:'p2', pendingAttack:{attackerId:'p1', attackerInstanceId:ts.instanceId, targetType:'player', targetInstanceId:null}};
    const action={type:'REQUEST_ATTACK_PLAYER', label:'Dan Yuki follow-up attack', target:{owner:'own', cardType:'digimon', trait:'TS', count:1}, optional:true};
    const ok=g.requestAttackPlayer('p1', dan2, action);
    if(ok) issues.push('Dan Yuki second follow-up attack incorrectly returned success during an existing attack.');
    if(g.pendingChoice) issues.push(`Dan Yuki second follow-up attack opened ${g.pendingChoice.mode} during an existing attack.`);
    if(!g.counterTiming?.isActive || g.counterTiming.pendingAttack?.attackerInstanceId!==ts.instanceId) issues.push('Nested attack guard must preserve the already-resolving first attack.');
    if(!g.actionLogs.some(line=>/new attack can'?t be declared during an existing attack/i.test(line))) issues.push('Nested attack guard should log a clear skipped-attack reason.');

    const g2=mkGame(['BT25-086','BT25-033','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g2.zones.p1.battleArea=[]; g2.effectQueue=[]; g2.pendingChoice=null; g2.pendingTarget=null; g2.pendingReveal=null; g2.actionLogs=[]; g2.turnPlayer='p1'; g2.phase='MAIN'; g2.memory=-1; g2.counterTiming={isActive:false, step:'IDLE', defenderId:null, pendingAttack:null};
    const ts2=addBattle(g2,'p1','BT25-033',{tag:'round22ei-ts-legal', isSuspended:false, playedThisTurn:false});
    const danLegal=addBattle(g2,'p1','BT25-086',{tag:'round22ei-dan-legal', isSuspended:false});
    const okLegal=g2.requestAttackPlayer('p1', danLegal, action);
    if(!okLegal || g2.pendingChoice?.mode!=='ATTACK_PLAYER_CHOICE') issues.push('Nested attack guard overblocked a legal effect-created attack when no attack was in progress.');
    if(!g2.pendingChoice?.cards?.some(c=>c.instanceId===ts2.instanceId)) issues.push('Legal Dan Yuki follow-up should still offer the selected TS Digimon outside an existing attack.');
  }catch(e){ issues.push('Round22EI effect attack during existing attack guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EI effect-created attack during existing attack guard', issues};
}

function testRound22EHMastemonErrataSecuritySearchGuard(){
  const issues=[];
  try{
    const card=base('ST10-06');
    const text=[card.mainEffect||'',card.effectText||'',card.officialMainText||''].join(' ');
    const blob=JSON.stringify(card.mechanics||[]);
    if(/you may search your security stack for 1 level 5 or lower Digimon card and play it/i.test(text)) issues.push('ST10-06 still has pre-errata security-search wording.');
    if(!/search your security stack, and you may play 1 level 5 or lower Digimon card among it/i.test(text)) issues.push('ST10-06 should preserve official errata wording for security search/play.');
    if(/"type"\s*:\s*"PLACE_SOURCE"[\s\S]{0,160}"zone"\s*:\s*"security"/.test(blob)) issues.push('ST10-06 trash-to-security clause must not be encoded as PLACE_SOURCE zone:security.');
    if(!/PLACE_SECURITY_FROM_TRASH/.test(blob)) issues.push('ST10-06 missing PLACE_SECURITY_FROM_TRASH for trash→security clause.');
    if(!/DIGIVOLVE_CONTEXT/.test(blob) || !/"dna"\s*:\s*true/.test(blob)) issues.push('ST10-06 security-search branch must be gated to DNA digivolving.');
    if(!/REVEAL_AND_SELECT/.test(blob) || !/"(?:from|zone)"\s*:\s*"security"/.test(blob)) issues.push('ST10-06 DNA branch must reveal/search the security stack.');
    if(!/"from"\s*:\s*"revealed"/.test(blob)) issues.push('ST10-06 selected security card must be played from the revealed buffer, not hand/trash.');
    if(!/RETURN_REVEALED_REST_TO_SECURITY_SHUFFLE/.test(blob)) issues.push('ST10-06 DNA branch must shuffle the rest back into security.');

    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/placeSecurityFromTrash/.test(gs) || !/case 'PLACE_SECURITY_FROM_TRASH'/.test(gs)) issues.push('game-state must support PLACE_SECURITY_FROM_TRASH runtime action.');
    if(!/RETURN_REVEALED_REST_TO_SECURITY_SHUFFLE/.test(gs) || !/shouldShuffleSecurity/.test(gs)) issues.push('game-state must support security reveal-rest shuffle cleanup.');

    const g=mkGame(['ST10-06','BT11-042','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[]; g.zones.p1.hand=[]; g.zones.p1.security=[]; g.effectQueue=[]; g.pendingReveal=null; g.pendingChoice=null; g.pendingTarget=null; g.actionLogs=[]; g.memory=3; g.turnPlayer='p1'; g.phase='MAIN';
    const mast=addBattle(g,'p1','ST10-06',{tag:'round22eh-mast'});
    const trashMast=clone('ST10-06','round22eh-trash');
    const secLegal=clone('BT11-042','round22eh-security-play');
    const secOther=clone('BT1-010','round22eh-security-other');
    g.zones.p1.trash.push(trashMast);
    g.zones.p1.security.push(secOther, secLegal); // last element is top
    const beforeSecurityIds=new Set(g.zones.p1.security.map(c=>c.instanceId));
    const prevCtx=g.currentTriggerContext;
    g.currentTriggerContext={dnaDigivolved:true};
    g.triggerEffect('p1', mast, 'When Digivolving');
    g.currentTriggerContext=prevCtx||null;
    autoResolve(g,120);
    if(g.pendingReveal || g.pendingChoice || g.pendingTarget) issues.push('ST10-06 DNA security-search runtime left a pending window after autoResolve.');
    if(g.zones.p1.trash.some(c=>c.instanceId===trashMast.instanceId)) issues.push('ST10-06 trash→security card remained in trash.');
    if(!g.zones.p1.security.some(c=>c.instanceId===trashMast.instanceId)) issues.push('ST10-06 trash→security card was not placed into security before search cleanup.');
    if(g.zones.p1.security.some(c=>c.instanceId===secLegal.instanceId)) issues.push('ST10-06 selected Lv.5 security Digimon should leave security when played.');
    if(!g.zones.p1.battleArea.some(c=>c.instanceId===secLegal.instanceId || c.id==='BT11-042')) issues.push('ST10-06 selected security Digimon was not played to battle area.');
    if(!g.zones.p1.security.some(c=>c.instanceId===secOther.instanceId)) issues.push('ST10-06 unselected security cards should return to security, not deck/trash/hand.');
    issues.push(...checkInvariants(g,'round22ehDnaSearch'));

    const g2=mkGame(['ST10-06','BT11-042','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.trash=[]; g2.zones.p1.hand=[]; g2.zones.p1.security=[]; g2.effectQueue=[]; g2.pendingReveal=null; g2.pendingChoice=null; g2.pendingTarget=null; g2.actionLogs=[]; g2.memory=3; g2.turnPlayer='p1'; g2.phase='MAIN';
    const mast2=addBattle(g2,'p1','ST10-06',{tag:'round22eh-mast-non-dna'});
    const trashMast2=clone('ST10-06','round22eh-trash-non-dna');
    const secLegal2=clone('BT11-042','round22eh-security-non-dna');
    g2.zones.p1.trash.push(trashMast2);
    g2.zones.p1.security.push(secLegal2);
    g2.currentTriggerContext={dnaDigivolved:false};
    g2.triggerEffect('p1', mast2, 'When Digivolving');
    g2.currentTriggerContext=null;
    autoResolve(g2,80);
    if(g2.pendingReveal) issues.push('ST10-06 non-DNA digivolve must not open security search.');
    if(!g2.zones.p1.security.some(c=>c.instanceId===trashMast2.instanceId)) issues.push('ST10-06 non-DNA path should still place the trash card to security.');
    if(g2.zones.p1.battleArea.some(c=>c.instanceId===secLegal2.instanceId)) issues.push('ST10-06 non-DNA path should not play from security.');
    issues.push(...checkInvariants(g2,'round22ehNonDna'));
  }catch(e){ issues.push('Round22EH Mastemon errata security-search guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EH ST10-06 Mastemon errata security-search guard', issues};
}

function testRound22EGBt25057FinalJudgmentErrataDurationGuard(){
  const issues=[];
  try{
    const card=base('BT25-057');
    const mainText=String(card.mainEffect||card.effectText||'');
    if(/until your opponent['’]s turn ends/i.test(mainText)) issues.push('BT25-057 Final Judgment still uses pre-errata “until your opponent\'s turn ends” wording.');
    if(!/for the turn/i.test(mainText)) issues.push('BT25-057 Final Judgment must preserve May 15 2026 errata wording “for the turn”.');
    const mech=(card.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='MAIN' && m.dualOptionSide===true);
    if(!mech) issues.push('BT25-057 Final Judgment missing DUAL Option-side MAIN mechanic.');
    const buffActions=(mech?.actions||[]).filter(a=>['GRANT_KEYWORD','DP_MOD'].includes(String(a.type||'').toUpperCase()));
    if(buffActions.length<3) issues.push('BT25-057 Final Judgment should have Rush, Security A.+1, and +5000 DP buff actions.');
    for(const action of buffActions){
      const duration=String(action.duration||action.buff?.duration||'').toUpperCase();
      if(duration!=='END_OF_TURN') issues.push(`BT25-057 ${action.type} duration expected END_OF_TURN, got ${duration||'missing'}.`);
    }
    if(JSON.stringify(mech||{}).includes('OPPONENTS_END_OF_TURN')) issues.push('BT25-057 Final Judgment must not keep OPPONENTS_END_OF_TURN after official errata.');

    const g=mkGame(['BT25-057','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.actionLogs=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.memory=3; g.turnPlayer='p1'; g.turnCount=3; g.phase='MAIN';
    const source=clone('BT25-057','round22eg-source');
    const target=addBattle(g,'p1','BT1-010',{tag:'round22eg-target', isSuspended:false});
    enqueue(g,'p1',source,(mech?.actions||[]).filter(a=>['GRANT_KEYWORD','DP_MOD'].includes(String(a.type||'').toUpperCase())),'BT25-057 Final Judgment buffs');
    autoResolve(g,80);
    const hasBuffBefore=(target.turnEffects||[]).some(e=>String(e.duration||'').toUpperCase()==='END_OF_TURN' && ['GRANT_KEYWORD','DP_MOD'].includes(String(e.type||'').toUpperCase()));
    if(!hasBuffBefore) issues.push('Runtime proof: Final Judgment buffs were not applied with END_OF_TURN duration.');
    g.cleanupTurnEffectsForTiming('p1','END_OF_TURN');
    const stillAfterOwnEot=(target.turnEffects||[]).some(e=>['GRANT_KEYWORD','DP_MOD'].includes(String(e.type||'').toUpperCase()));
    if(stillAfterOwnEot) issues.push('Runtime proof: Final Judgment buffs should expire at the controller\'s End of Turn after errata.');
    issues.push(...checkInvariants(g,'round22egFinalJudgment'));
  }catch(e){ issues.push('Round22EG BT25-057 Final Judgment errata duration guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EG BT25-057 Final Judgment errata duration guard', issues};
}

function testRound22EFSuspendTamerCostTargetGuard(){
  const issues=[];
  try{
    const expected={
      'BT17-029': [{trigger:'WHEN_ATTACKING', colors:['Yellow']}],
      'BT17-033': [{trigger:'WHEN_ATTACKING', colors:['Yellow']}],
      'BT17-037': [{trigger:'WHEN_DIGIVOLVING', colors:['Yellow']}, {trigger:'WHEN_ATTACKING', colors:['Yellow']}],
      'BT21-045': [{trigger:'WHEN_ATTACKING', colors:['Yellow','Red']}]
    };
    for(const [id,rules] of Object.entries(expected)){
      const card=base(id);
      for(const rule of rules){
        const mech=(card.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()===rule.trigger && String(m.cost?.type||'').toUpperCase()==='SUSPEND');
        if(!mech){ issues.push(`${id}: missing ${rule.trigger} SUSPEND-cost mechanic.`); continue; }
        const target=mech.cost?.target||{};
        if(String(target.cardType||'').toLowerCase()!=='tamer') issues.push(`${id}: suspend cost must target Tamers, got ${JSON.stringify(target)}.`);
        const colors=[];
        if(target.color) colors.push(...String(target.color).split(/\s+or\s+|[,/]/i).map(x=>x.trim()).filter(Boolean));
        if(Array.isArray(target.colorAny)) colors.push(...target.colorAny);
        const low=colors.map(x=>String(x).toLowerCase());
        for(const color of rule.colors) if(!low.includes(color.toLowerCase())) issues.push(`${id}: suspend-cost Tamer selector missing ${color}.`);
        if(!(mech.optional===true || mech.optionalProcessing===true || mech.may===true || mech.requiresActivationChoice===true)) issues.push(`${id}: By-suspending trigger must ask before paying cost.`);
      }
    }

    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/Round 22EF: respect explicit suspend-cost targets/.test(gs) || !/targetSpec/.test(gs) || !/explicitSelf/.test(gs)) issues.push('game-state SUSPEND cost must respect explicit targetSpec before sourceCard fallback.');

    // Runtime proof: BT17-029 attacks while already suspended. The optional window
    // should open, and confirming must suspend a yellow Tamer and draw 1 without
    // trying to re-suspend the attacker/sourceCard.
    const g=mkGame(['BT17-029','BT17-087','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.zones.p1.hand=[]; g.zones.p1.trash=[]; g.actionLogs=[]; g.effectQueue=[]; g.pendingEffectSelection=null; g.counterTiming={isActive:false, defenderId:null, pendingAttack:null, step:'IDLE'}; g.memory=3; g.turnPlayer='p1'; g.turnCount=3; g.phase='MAIN';
    const agumon=addBattle(g,'p1','BT17-029',{tag:'round22ef-agumon'});
    const marcus=addBattle(g,'p1','BT17-087',{tag:'round22ef-marcus', isSuspended:false});
    const deckBefore=g.zones.p1.deck.length;
    const handBefore=g.zones.p1.hand.length;
    g.declareAttack('p1', agumon.instanceId, 'player', null);
    if(!agumon.isSuspended) issues.push('BT17-029 attacker should be suspended by attack declaration before cost resolution.');
    if(!g.pendingEffectSelection || g.pendingEffectSelection.mode!=='OPTIONAL_EFFECT_CONFIRM') issues.push('BT17-029 When Attacking By-suspending Tamer effect should open OPTIONAL_EFFECT_CONFIRM.');
    if(marcus.isSuspended) issues.push('BT17-029 should not suspend the yellow Tamer before the player confirms the optional processing.');
    g.resolveManualEffect('p1',0,false);
    if(marcus.isSuspended) issues.push('Skipping BT17-029 optional Tamer suspend cost should leave Marcus unsuspended.');
    if(g.zones.p1.hand.length!==handBefore) issues.push('Skipping BT17-029 optional effect must not draw.');
    autoResolve(g, 40);

    const g2=mkGame(['BT17-029','BT17-087','BT1-010','BT1-011','BT1-012'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.hand=[]; g2.zones.p1.trash=[]; g2.actionLogs=[]; g2.effectQueue=[]; g2.pendingEffectSelection=null; g2.counterTiming={isActive:false, defenderId:null, pendingAttack:null, step:'IDLE'}; g2.memory=3; g2.turnPlayer='p1'; g2.turnCount=3; g2.phase='MAIN';
    const agumon2=addBattle(g2,'p1','BT17-029',{tag:'round22ef-agumon-act'});
    const marcus2=addBattle(g2,'p1','BT17-087',{tag:'round22ef-marcus-act', isSuspended:false});
    const handBefore2=g2.zones.p1.hand.length;
    const deckBefore2=g2.zones.p1.deck.length;
    g2.declareAttack('p1', agumon2.instanceId, 'player', null);
    if(!g2.pendingEffectSelection) issues.push('Activate path: BT17-029 optional choice did not open.');
    g2.resolveManualEffect('p1',0,true);
    if(!marcus2.isSuspended) issues.push('Activating BT17-029 must suspend the eligible yellow Tamer, not the already-suspended attacker.');
    if(!agumon2.isSuspended) issues.push('Activating BT17-029 should not unsuspend or otherwise disturb the attacker.');
    if(g2.zones.p1.hand.length!==handBefore2+1) issues.push(`Activating BT17-029 should draw 1, hand ${handBefore2}->${g2.zones.p1.hand.length}.`);
    if(g2.zones.p1.deck.length!==deckBefore2-1) issues.push('Activating BT17-029 should consume exactly one deck card for Draw 1.');
    if(g2.pendingEffectSelection) issues.push('Activating BT17-029 should clear pendingEffectSelection after resolution.');
    autoResolve(g2, 40);
    issues.push(...checkInvariants(g,'round22efSkip'), ...checkInvariants(g2,'round22efActivate'));
  }catch(e){ issues.push('Round22EF suspend Tamer cost target guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EF suspend-cost Tamer targeting guard', issues};
}






function testRound22ENEffectPopupWordingGuard(){
  const issues=[];
  try{
    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
    if(!/Round 22EN: Human-readable pending-window prompts/.test(gs)) issues.push('game-state should document Round 22EN readable pending-window prompt helpers.');
    if(!/buildPendingTargetUiPrompt/.test(gs) || !/buildRevealUiPrompt/.test(gs) || !/buildStructuredChoiceUiPrompt/.test(gs)) issues.push('game-state should expose target/reveal/choice UI prompt builders.');
    if(!/Round 22EN: make every pending effect window explain the actual action/.test(html)) issues.push('index.html should document Round 22EN pending effect copy improvements.');
    if(!/describePendingTarget/.test(html) || !/describePendingReveal/.test(html) || !/describeTargetObject/.test(html)) issues.push('index.html should render readable pending target/reveal descriptions.');
    if(!/reveal-instruction-text'\)\.innerHTML\s*=\s*describePendingReveal/.test(html)) issues.push('reveal overlay should show the effect-specific reveal amount/slot summary instead of generic SELECT UP TO copy.');

    const g=mkGame(['EX6-020','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.zones.p2.battleArea=[]; g.effectQueue=[]; g.actionLogs=[]; g.pendingReveal=null; g.pendingTarget=null; g.memory=0; g.turnPlayer='p1'; g.phase='MAIN';
    const gatomon=addBattle(g,'p1','EX6-020',{tag:'round22en-gatomon', stack:[]});
    const revealAction=(base('EX6-020').mechanics||[]).find(m=>m.trigger==='ON_PLAY').actions[0];
    g.startRevealSelection('p1', gatomon, revealAction, {});
    const revealPrompt=String(g.pendingReveal?.uiPrompt || g.pendingReveal?.instruction || '');
    if(!/EX6-020|Gatomon/i.test(revealPrompt)) issues.push('Gatomon reveal prompt should include the effect source name.');
    if(!/reveal 3 card\(s\)|top of your deck|top 3|3 张/i.test(revealPrompt)) issues.push(`Gatomon reveal prompt should say it reveals 3 cards from deck top, got: ${revealPrompt}`);
    if(!/Angel|Archangel|Fallen Angel|Mirei/i.test(revealPrompt)) issues.push('Gatomon reveal prompt should summarize the selectable card slots.');

    const g2=mkGame(['EX6-020','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g2.zones.p1.battleArea=[]; g2.zones.p2.battleArea=[]; g2.effectQueue=[]; g2.actionLogs=[]; g2.pendingTarget=null; g2.memory=0; g2.turnPlayer='p1'; g2.phase='MAIN';
    const src=addBattle(g2,'p1','EX6-020',{tag:'round22en-dp-source', stack:[]});
    addBattle(g2,'p2','BT2-010',{tag:'round22en-dp-target', stack:[], dp:3000});
    enqueue(g2,'p1',src,[{type:'DP_MOD',amount:-2000,target:{owner:'opponent',cardType:'digimon',count:1},duration:'END_OF_TURN'}],'EX6-020 Gatomon');
    const dpPrompt=String(g2.pendingTarget?.uiPrompt || g2.pendingTarget?.instruction || '');
    if(!/Gatomon|EX6-020/i.test(dpPrompt)) issues.push('DP_MOD target prompt should include source/effect name.');
    if(!/-2000\s*DP|−2000\s*DP/i.test(dpPrompt)) issues.push(`DP_MOD target prompt should clearly show the DP amount, got: ${dpPrompt}`);
    if(!/opponent|对方/i.test(dpPrompt) || !/Digimon|数码兽/i.test(dpPrompt)) issues.push('DP_MOD target prompt should clearly say the target is an opponent Digimon.');

    const g3=mkGame(['EX4-011','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g3.zones.p1.battleArea=[]; g3.zones.p2.battleArea=[]; g3.effectQueue=[]; g3.actionLogs=[]; g3.pendingTarget=null; g3.memory=0; g3.turnPlayer='p1'; g3.phase='MAIN';
    const chaos=addBattle(g3,'p1','EX4-011',{tag:'round22en-delete-source', stack:[]});
    addBattle(g3,'p2','BT2-010',{tag:'round22en-delete-target', stack:[], dp:6000});
    enqueue(g3,'p1',chaos,[{type:'DELETE_DIGIMON',target:{owner:'opponent',cardType:'digimon',count:1,maxDp:7000}}],'EX4-011 ChaosGallantmon');
    const delPrompt=String(g3.pendingTarget?.uiPrompt || g3.pendingTarget?.instruction || '');
    if(!/delete/i.test(delPrompt)) issues.push(`DELETE target prompt should state the action is deletion, got: ${delPrompt}`);
    if(!/7000\s*DP or less|DP 7000|7000 DP/i.test(delPrompt)) issues.push('DELETE target prompt should show the DP ceiling.');
    if(!/opponent|对方/i.test(delPrompt) || !/Digimon|数码兽/i.test(delPrompt)) issues.push('DELETE target prompt should clearly say the target is an opponent Digimon.');
  }catch(e){ issues.push('Round22EN effect popup wording guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EN effect popup wording guard', issues};
}

