function testRound22ELInheritedReplacementTopCardScopeGuard(){
  const issues=[];
  try{
    // BT23-067 LadyDevimon has <Scapegoat> only as an inherited/source effect.
    // If she is the top battle-area Digimon with no sources, blocking/security
    // battle deletion must delete LadyDevimon herself and must not sacrifice a
    // neighboring Digimon to prevent that deletion.
    const g=mkGame(['BT1-010','BT1-011','BT1-012','BT1-013','BT1-014'], ['BT23-067','BT2-010','BT2-011','BT2-012','BT2-013']);
    g.zones.p2.battleArea=[]; g.zones.p2.trash=[]; g.actionLogs=[]; g.effectQueue=[]; g.pendingTarget=null; g.pendingChoice=null; g.pendingProtection=null; g.counterTiming={isActive:false, defenderId:null, pendingAttack:null, step:'IDLE'};
    const topLady=addBattle(g,'p2','BT23-067',{tag:'round22el-top-lady', stack:[]});
    const neighbor=addBattle(g,'p2','BT2-010',{tag:'round22el-neighbor', stack:[]});
    const deletedTop=g.applyDeletion('p2', topLady.instanceId, {inBattle:true, byEffect:false});
    if(deletedTop!==true) issues.push('Top-level BT23-067 without sources should be deleted in battle/security battle, not protected by its own inherited Scapegoat.');
    if(g.zones.p2.battleArea.some(c=>c.instanceId===topLady.instanceId)) issues.push('Top-level BT23-067 incorrectly remained in battle area after deletion.');
    if(!g.zones.p2.trash.some(c=>c.instanceId===topLady.instanceId)) issues.push('Top-level BT23-067 should move to trash after deletion.');
    if(!g.zones.p2.battleArea.some(c=>c.instanceId===neighbor.instanceId)) issues.push('Neighbor Digimon was incorrectly sacrificed by top-level LadyDevimon Scapegoat.');
    if(g.actionLogs.some(line=>/Scapegoat|Structured replacement prevented LadyDevimon/i.test(String(line)))) issues.push('Top-level BT23-067 should not log/use Scapegoat replacement.');
    issues.push(...checkInvariants(g,'round22elTopLadyNoSource'));

    // The same BT23-067 must still work when it is actually a digivolution
    // source under another Digimon: then Scapegoat may delete another own
    // Digimon to prevent the host from being deleted.
    const g2=mkGame(['BT1-010','BT1-011','BT1-012','BT1-013','BT1-014'], ['BT23-067','BT2-010','BT2-011','BT2-012','BT2-013']);
    g2.zones.p2.battleArea=[]; g2.zones.p2.trash=[]; g2.actionLogs=[]; g2.effectQueue=[]; g2.pendingTarget=null; g2.pendingChoice=null; g2.pendingProtection=null; g2.counterTiming={isActive:false, defenderId:null, pendingAttack:null, step:'IDLE'};
    const host=addBattle(g2,'p2','BT2-010',{tag:'round22el-host', stack:[clone('BT23-067','round22el-source')]});
    const sacrifice=addBattle(g2,'p2','BT2-011',{tag:'round22el-sacrifice', stack:[]});
    const deletedHost=g2.applyDeletion('p2', host.instanceId, {inBattle:true, byEffect:false});
    if(deletedHost!==false) issues.push('Host with BT23-067 as a source should have its deletion prevented by inherited Scapegoat.');
    if(!g2.zones.p2.battleArea.some(c=>c.instanceId===host.instanceId)) issues.push('Host should remain in battle area after inherited Scapegoat prevents deletion.');
    if(!g2.zones.p2.trash.some(c=>c.instanceId===sacrifice.instanceId)) issues.push('Inherited Scapegoat should delete another own Digimon as the prevention cost.');
    if(!Array.isArray(host.stack) || !host.stack.some(c=>c.id==='BT23-067')) issues.push('Inherited BT23-067 source should remain under the protected host.');
    issues.push(...checkInvariants(g2,'round22elLadySourceScapegoat'));

    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/Round 22EL/.test(gs)) issues.push('game-state should document the Round 22EL inherited replacement scope fix.');
    if(!/\(mech\?\.isInherited === true\) !== isSource\) return/.test(gs)) issues.push('Structured replacements must strictly separate inherited/source and top-card mechanics.');
    if(!/getBattleRuntimeText\(card\)/.test(gs) || !/getSourceRuntimeText\(src\)/.test(gs)) issues.push('Leave-protection text must use battle-scoped top text and source-scoped stack text.');
  }catch(e){ issues.push('Round22EL inherited replacement top-card scope guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EL inherited replacement top-card scope guard', issues};
}


function testRound22EKHandDockMemoryCenterRegressionGuard(){
  const issues=[];
  try{
    const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
    if(!/Round 22EK: keep the full hand-dock safe space/.test(html)) issues.push('index.html should document the Round 22EK hand-dock safe-space regression fix.');
    if(!/--hand-h:\s*clamp\(112px,\s*13vh,\s*132px\)/.test(html)) issues.push('Round 22EK must keep --hand-h large enough for the absolute dock and card fan.');
    if(!/\.player-area\.self\s*\{[^}]*padding-top:\s*calc\([^}]*var\(--memory-gutter\)[^}]*padding-bottom:\s*calc\(var\(--hand-h\)/s.test(html)) issues.push('Self field must reserve the full hand dock height plus memory gutter, not only the peek height.');
    if(/\.player-area\.self\s*\{[^}]*padding-bottom:\s*calc\(var\(--hand-peek\)/s.test(html)) issues.push('Self field padding must not regress to hand-peek-only spacing.');
    if(!/\.hand-area\s*\{[^}]*min-height:\s*var\(--hand-h\)[^}]*height:\s*var\(--hand-h\)[^}]*position:\s*absolute[^}]*bottom:\s*0/s.test(html)) issues.push('Hand dock must remain an absolute overlay with height tied to --hand-h.');
    if(!/transform:\s*translateX\(-50%\) translateY\(calc\(var\(--hand-card-h\) - var\(--hand-peek\)\)\)/.test(html)) issues.push('Hand dock must keep the YGO-style peek transform while reserving full safe space.');
  }catch(e){ issues.push('Round22EK hand dock regression guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EK hand dock memory center regression guard', issues};
}

function testRound22EJTacticalRetreatSendToSecurityGuard(){
  const issues=[];
  try{
    const tactical=base('BT4-105');
    const mainMech=(tactical.mechanics||[]).find(m=>String(m.trigger||'').toUpperCase()==='MAIN');
    const action=(mainMech?.actions||[])[0] || {};
    if(String(action.type||'').toUpperCase()!=='SEND_TO_SECURITY') issues.push('BT4-105 Tactical Retreat! Main effect must use SEND_TO_SECURITY, not PLACE_SOURCE zone:security.');
    if(String(action.position||action.zone||'').toLowerCase().includes('source')) issues.push('BT4-105 Tactical Retreat! must not place the selected Digimon as a digivolution source.');
    if(String(action.position||'top').toLowerCase()!=='top') issues.push('BT4-105 Tactical Retreat! should place the Digimon on top of security.');

    // Normal Digimon: it leaves battle area, its sources are trashed, and the top card itself becomes security.
    const g=mkGame(['BT4-105','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g.zones.p1.battleArea=[]; g.zones.p1.trash=[]; g.zones.p1.security=[]; g.actionLogs=[]; g.effectQueue=[]; g.pendingTarget=null; g.memory=3; g.turnPlayer='p1'; g.phase='MAIN';
    const mon=addBattle(g,'p1','BT1-010',{tag:'round22ej-target'});
    const src=clone('BT1-011','round22ej-source');
    mon.stack=[src];
    enqueue(g,'p1',tactical,[action],'BT4-105 Tactical Retreat');
    if(!g.pendingTarget || g.pendingTarget.actionType!=='SEND_TO_SECURITY') issues.push('BT4-105 should open a SEND_TO_SECURITY target window for a battle-area Digimon.');
    g.submitTarget('p1', mon.instanceId);
    if(g.zones.p1.battleArea.some(c=>c.instanceId===mon.instanceId)) issues.push('Tactical Retreat target should leave the battle area.');
    if(!g.zones.p1.security.some(c=>c.instanceId===mon.instanceId)) issues.push('Tactical Retreat target should be placed in security, not under another card.');
    if(!g.zones.p1.trash.some(c=>c.instanceId===src.instanceId)) issues.push('Tactical Retreat should trash the moved Digimon’s digivolution cards.');
    if((g.zones.p1.security.find(c=>c.instanceId===mon.instanceId)?.stack||[]).length) issues.push('Tactical Retreat security card should not keep its digivolution stack.');
    issues.push(...checkInvariants(g,'round22ejNormalDigimon'));

    // Official BT4-105 Q&A: a token chosen for this movement is removed instead of added to security.
    const g2=mkGame(['BT4-105','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g2.zones.p1.battleArea=[]; g2.zones.p1.security=[]; g2.zones.p1.removedFromGame=[]; g2.actionLogs=[]; g2.effectQueue=[]; g2.pendingTarget=null; g2.memory=3; g2.turnPlayer='p1'; g2.phase='MAIN';
    const token={id:'ROUND22EJ-TOKEN', name:'Round 22EJ Token', type:'digimon', cardKind:'token', isToken:true, tokenOwnerId:'p1', ownerPlayerId:'p1', instanceId:'round22ej-token', stack:[], isSuspended:false};
    g2.zones.p1.battleArea.push(token);
    enqueue(g2,'p1',tactical,[action],'BT4-105 Tactical Retreat token');
    const tokenCtx=g2.pendingTarget?.structuredEffectContext || {};
    g2.submitTarget('p1', token.instanceId);
    if(g2.zones.p1.security.some(c=>c.instanceId===token.instanceId)) issues.push('Token must not be added to security by Tactical Retreat.');
    if(!g2.zones.p1.removedFromGame.some(c=>c.instanceId===token.instanceId)) issues.push('Token must be removed from the game/token pile instead of security.');
    if((tokenCtx._placedCardsByThisEffect||[]).some(row=>row.instanceId===token.instanceId)) issues.push('Token replacement must not satisfy PLACED_BY_THIS_EFFECT/security-added context.');
    issues.push(...checkInvariants(g2,'round22ejToken'));

    // Official BT4-105 Q&A: Mother D-Reaper/Digi-Egg card goes to bottom of Digi-Egg deck instead of security.
    const g3=mkGame(['BT4-105','BT1-010','BT1-011','BT1-012','BT1-013'], ['BT2-010','BT2-011','BT2-012','BT2-013','BT2-014']);
    g3.zones.p1.battleArea=[]; g3.zones.p1.security=[]; g3.zones.p1.eggDeck=[]; g3.zones.p1.trash=[]; g3.actionLogs=[]; g3.effectQueue=[]; g3.pendingTarget=null; g3.memory=3; g3.turnPlayer='p1'; g3.phase='MAIN';
    const mother=addBattle(g3,'p1','EX2-007',{tag:'round22ej-mother'});
    const motherSource=clone('EX2-046','round22ej-mother-source');
    mother.stack=[motherSource];
    enqueue(g3,'p1',tactical,[action],'BT4-105 Tactical Retreat Mother');
    const eggCtx=g3.pendingTarget?.structuredEffectContext || {};
    g3.submitTarget('p1', mother.instanceId);
    if(g3.zones.p1.security.some(c=>c.instanceId===mother.instanceId)) issues.push('Digi-Egg/Mother D-Reaper must not be added to security by Tactical Retreat.');
    if(!g3.zones.p1.eggDeck.length || g3.zones.p1.eggDeck[0].instanceId!==mother.instanceId) issues.push('Digi-Egg/Mother D-Reaper should be placed on the bottom of the Digi-Egg deck.');
    if(!g3.zones.p1.trash.some(c=>c.instanceId===motherSource.instanceId)) issues.push('Digi-Egg replacement should still trash the moved battle card’s digivolution cards.');
    if((eggCtx._placedCardsByThisEffect||[]).some(row=>row.instanceId===mother.instanceId)) issues.push('Digi-Egg replacement must not satisfy PLACED_BY_THIS_EFFECT/security-added context.');
    issues.push(...checkInvariants(g3,'round22ejDigiEgg'));

    const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
    if(!/Round 22EJ/.test(gs) || !/actualSecurityAdded/.test(gs) || !/isDigiEggMovingToSecurity/.test(gs)) issues.push('game-state must preserve Round 22EJ token/Digi-Egg SEND_TO_SECURITY replacement guard.');
  }catch(e){ issues.push('Round22EJ Tactical Retreat guard failed: '+(e.stack||e.message)); }
  return {name:'Round 22EJ BT4-105 Tactical Retreat send-to-security guard', issues};
}

