function testRound18RAngelMastemonSecondPassGuard(){
  const issues=[];
  const c=id=>byId.get(id)||{};
  const has=(id,pred)=>Array.isArray(c(id).mechanics)&&c(id).mechanics.some(pred);
  if(has('ST10-04',m=>m.trigger==='YOUR_TURN' && JSON.stringify(m).includes('REDUCE_COST'))) issues.push('ST10-04 cost reduction must not be encoded as a YOUR_TURN action.');
  if(!has('ST10-04',m=>m.trigger==='WOULD_DIGIVOLVE' && JSON.stringify(m).includes('Archangel') && JSON.stringify(m).includes('Fallen Angel'))) issues.push('ST10-04 should use WOULD_DIGIVOLVE for Archangel/Fallen Angel cost reduction.');
  const bt11083=JSON.stringify(c('BT11-083').mechanics||[]);
  if(!/"anyOf"/.test(bt11083) || !/Mirei Mikagura/.test(bt11083)) issues.push('BT11-083 trash return should use OR semantics for Mirei vs Angel-family cards.');
  const bt22089=JSON.stringify(c('BT22-089').mechanics||[]);
  if(!/"anyOf"/.test(bt22089) || !/"trait":\s*"CS"/.test(bt22089)) issues.push('BT22-089 play target should use OR semantics: Mirei or CS Tamer.');
  const p187=JSON.stringify(c('P-187').mechanics||[]);
  if(!/"excludeSelf":\s*true/.test(p187)) issues.push('P-187 security placement should exclude this Mastemon itself.');
  if(!/PLACED_BY_THIS_EFFECT/.test(p187)) issues.push('P-187 opponent security trash should require the by-placing security action to succeed.');
  const bt23102=JSON.stringify(c('BT23-102').mechanics||[]);
  if(!/allSourceNames/.test(bt23102) || !/Angewomon/.test(bt23102) || !/LadyDevimon/.test(bt23102)) issues.push('BT23-102 Partition should require both specified source names.');
  const ex4074=JSON.stringify(c('EX4-074').mechanics||[]);
  if(!/"self":\s*true/.test(ex4074)) issues.push('EX4-074 End of Attack should delete this Digimon via self target.');
  const gs=fs.readFileSync(path.join(__dirname,'game-state.js'),'utf8');
  if(!/allSourceNames/.test(gs)) issues.push('game-state should support allSourceNames for Partition source checks.');
  if(!/target\.excludeSelf/.test(gs)) issues.push('game-state target selection should support excludeSelf.');
  if(!/recordPlacedByThisEffect\(.*SEND_TO_SECURITY/s.test(gs)) issues.push('SEND_TO_SECURITY should record PLACED_BY_THIS_EFFECT context for by-placing follow-ups.');
  return { name:'Round 18R Angel/Mastemon second-pass semantic guard', issues };
}

function testRound18QAngelMastemonPlayLocks(){
  const issues=[];
  const c=id=>byId.get(id)||{};
  const has=(id,pred)=>Array.isArray(c(id).mechanics)&&c(id).mechanics.some(pred);
  if(!has('BT9-033',m=>m.trigger==='ALL_TURNS' && JSON.stringify(m).includes('CANT_PLAY_BY_EFFECT'))) issues.push('BT9-033 should encode play-by-effect lock, not STUN.');
  if(!has('ST10-02',m=>m.trigger==='END_OF_TURN' && m.isInherited===true && m.actions?.[0]?.target?.count===2)) issues.push('ST10-02 inherited DNA count should be 2.');
  if(!has('EX6-020',m=>m.trigger==='WHEN_ATTACKING' && m.isInherited===true)) issues.push('EX6-020 inherited When Attacking missing.');
  if(!has('BT22-034',m=>m.trigger==='TRASHED_FROM_SECURITY')) issues.push('BT22-034 security-trash play trigger missing.');
  if(!has('BT11-042',m=>m.trigger==='OWN_CARD_PLAYED')) issues.push('BT11-042 played-card memory trigger missing.');
  if(!has('BT11-083',m=>m.trigger==='OWN_CARD_PLAYED')) issues.push('BT11-083 played-card memory trigger missing.');
  if(!has('BT23-102',m=>m.trigger==='WOULD_LEAVE_BATTLE_AREA')) issues.push('BT23-102 Partition should be would-leave, not On Deletion.');
  if(!has('EX4-074',m=>m.trigger==='END_OF_ATTACK')) issues.push('EX4-074 should trigger at End of Attack.');
  if(has('BT23-096',m=>m.trigger==='YOUR_TURN')) issues.push('BT23-096 Delay must not immediately fire from YOUR_TURN.');
  if(!has('BT22-089',m=>m.trigger==='START_OF_MAIN_PHASE')) issues.push('BT22-089 should trigger Start of Main Phase.');
  if(!has('BT11-094',m=>m.trigger==='DIGIVOLVED')) issues.push('BT11-094 should listen to DIGIVOLVED event.');
  if(!has('EX6-074',m=>m.trigger==='OWN_DIGIMON_PLAYED')) issues.push('EX6-074 should listen to OWN_DIGIMON_PLAYED.');
  if(!has('BT23-067',m=>m.trigger==='WOULD_BE_DELETED' && m.isInherited===true)) issues.push('BT23-067 Scapegoat should be inherited would-be-deleted replacement.');
  return { name:'Round 18Q Angel/Mastemon/anti-play lock card encoding guard', issues };
}
